insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (318, 36, 28, 40, 'سورة يس ٢٨ – ٤٠', '«يا حسرة على العباد»، و«وآية لهم الأرض الميتة أحييناها»، و«والشمس تجري لمستقرّ لها»، و«وكلٌّ في فلك يسبحون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 318) = $j$[{"lbl": "الآيات ٢٨ – ٣٢", "q": "۞وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندٖ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ ﴿٢٨﴾ إِن كَانَتۡ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ فَإِذَا هُمۡ خَٰمِدُونَ ﴿٢٩﴾ يَٰحَسۡرَةً عَلَى ٱلۡعِبَادِۚ مَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٣٠﴾ أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ أَنَّهُمۡ إِلَيۡهِمۡ لَا يَرۡجِعُونَ ﴿٣١﴾ وَإِن كُلّٞ لَّمَّا جَمِيعٞ لَّدَيۡنَا مُحۡضَرُونَ ﴿٣٢﴾", "w": [["وما أنزلنا على قومه", "على قوم حبيب بن النجار أهل أنطاكية."], ["من بعده", "من بعد موته."], ["من جند من السماء", "من الملائكة لإهلاكهم."], ["إن كانت إلا صيحة واحدة", "صيحة جبريل."], ["فإذا هم خامدون", "هلكى ساكنون لا حراك لهم."], ["يا حسرة على العباد", "احضري أيتها الحسرة، هذا أوان حضورك، والعباد هم المكذّبون للرسل."], ["ما يأتيهم من رسول إلا كانوا به يستهزئون", "هذا سبب التحسّر عليهم."], ["ألم يروا كم أهلكنا قبلهم", "ألم يعلم أهل مكة كم أهلكنا من القرون."], ["لدينا محضرون", "لحسابهم ومجازاتهم."]], "m": "وما أنزلنا على قوم حبيب بن النجار من بعد قتله جنداً من الملائكة للانتقام منهم، إذ لا حاجة إلى ذلك، وما كنا منزلين، إن كانت إلا صيحة واحدة من جبريل فإذا هم هلكى ساكنون. يا حسرة على العباد، احضري أيتها الحسرة فهذا أوانك، ما يأتيهم من رسول إلا كانوا به يستهزئون، وهذا موجب الحسرة. ألم يعلم أهل مكة كم أهلكنا قبلهم من القرون، كقوم نوح وعاد وثمود، أنهم إليهم لا يرجعون؟ فيعتبروا فيؤمنوا. وإنّ كلّ الخلائق لمجموعون لدينا محضرون لفصل القضاء، فينجو المؤمنون ويهلك الكافرون.", "h": ["مظاهر قدرة الله تعالى في إهلاك أهل أنطاكية بصيحة واحدة.", "إبداء التحسّر على العباد من أنفسهم، إذ هم الظالمون لها.", "حرمة الاستهزاء بما هو من حرمات الله تعالى التي يجب تعظيمها.", "طلب العبرة من أخبار الماضين وأحوالهم، والعاقل من اعتبر بغيره."], "k": "«يا حسرة على العباد»… ما الذي سأتحسّر عليه إن مضى عمري هكذا؟"}, {"lbl": "الآيات ٣٣ – ٣٦", "q": "وَءَايَةٞ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ أَحۡيَيۡنَٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبّٗا فَمِنۡهُ يَأۡكُلُونَ ﴿٣٣﴾ وَجَعَلۡنَا فِيهَا جَنَّـٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ وَفَجَّرۡنَا فِيهَا مِنَ ٱلۡعُيُونِ ﴿٣٤﴾ لِيَأۡكُلُواْ مِن ثَمَرِهِۦ وَمَا عَمِلَتۡهُ أَيۡدِيهِمۡۚ أَفَلَا يَشۡكُرُونَ ﴿٣٥﴾ سُبۡحَٰنَ ٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا يَعۡلَمُونَ ﴿٣٦﴾", "w": [["وآية لهم الأرض الميتة", "علامة على صحة البعث وإمكانه."], ["أحييناها", "بإنزال المطر عليها فأصبحت حيّة بالنبات."], ["وجعلنا فيها جنات", "بساتين."], ["وما عملته أيديهم", "لم تصنعه أيديهم وإنما هو صنع الله."], ["أفلا يشكرون", "أيرون هذه النعم ولا يشكرونها؟"], ["سبحان الذي خلق الأزواج كلها", "تنزيهاً لله الخالق."], ["ومن أنفسهم", "الذكور والإناث."], ["ومما لا يعلمون", "من المخلوقات في السماوات وتحت الأرض."]], "m": "لما قرّر البعث ذكر الدليل العقلي على إمكانه: وآية لهم الأرض الميتة، أحييناها بالمطر فأخرجنا منها حباً فمنه يأكلون، كذلك يحيي الله الموتى، إذ ينزل ماءً من تحت العرش فتحيا البشرية من عجب الذنب كما صحّ الخبر. وجعلنا فيها بساتين من نخيل وأعناب، وفجّرنا فيها من عيون الماء، ليأكلوا من ثمره، وما صنعته أيديهم بل يد الله، أفلا يشكرون؟ سبحان الذي خلق الأصناف كلها مما تنبت الأرض ومن أنفسهم ذكوراً وإناثاً ومما لا يعلمون مما في السماوات وباطن الأرض، فكل المخلوقات أزواج، والله وحده الفرد المنزّه عن صفات الخلق.", "h": ["تقرير عقيدة البعث والجزاء التي هي القوة الدافعة للعمل الصالح.", "دليل نظام الزوجية آية على أن القرآن وحي الله، إذ لم يعرف الناس هذا النظام في الذرّة وغيرها إلا في القرن الأخير.", "وجوب شكر الله تعالى بالإيمان وبطاعته على نعمه، كالإمداد بالغذاء والماء والهواء."], "k": "«وما عملته أيديهم أفلا يشكرون»… لقمة اليوم صنع الله قبل أن تكون كسبي؛ فهل شكرته عليها؟"}, {"lbl": "الآيات ٣٧ – ٤٠", "q": "وَءَايَةٞ لَّهُمُ ٱلَّيۡلُ نَسۡلَخُ مِنۡهُ ٱلنَّهَارَ فَإِذَا هُم مُّظۡلِمُونَ ﴿٣٧﴾ وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرّٖ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ﴿٣٨﴾ وَٱلۡقَمَرَ قَدَّرۡنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ ﴿٣٩﴾ لَا ٱلشَّمۡسُ يَنۢبَغِي لَهَآ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّيۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلّٞ فِي فَلَكٖ يَسۡبَحُونَ ﴿٤٠﴾", "w": [["الليل نسلخ منه النهار", "نكشط النهار عن الليل فإذا هم مظلمون."], ["لمستقرّ لها", "مكان لها لا تتجاوزه."], ["ذلك تقدير العزيز العليم", "جريها في فلكها تقدير من الله."], ["والقمر قدّرناه منازل", "ثمانية وعشرين منزلاً."], ["حتى عاد كالعرجون القديم", "كعود العِذق الأصفر الدقيق المقوّس."], ["لا الشمس ينبغي لها أن تدرك القمر", "لا يصح لها ولا يسهل."], ["ولا الليل سابق النهار", "بأن يأتي قبل انقضائه."], ["وكلٌّ في فلك يسبحون", "الشمس والقمر والنجوم يسيرون في أفلاكها."]], "m": "ما زال السياق في البرهنة على البعث: وآية لهم الليل نكشط منه النهار فإذا هم في الظلام. والشمس تجري في فلكها لمستقرّ لها، وإنها لتسجد كل يوم تحت العرش وتستأذن في استئناف دورانها فيؤذن لها كما صحّ الخبر، ذلك تقدير العزيز العليم، تسير بدقة لا تختل طوال الحياة، فالقادر على ذلك قادر على إحياء الموتى. والقمر قدّرناه منازل يتنقّل فيها كل شهر ليعرف أهل الأرض عدد السنين والحساب، يبدأ هلالاً ثم يكتمل بدراً في نصف الشهر ثم يضمحل حتى يعود كعود العذق القديم. لا الشمس ينبغي لها أن تدرك القمر فيذهب نورها بنوره، ولا الليل يسبق النهار، وكلٌّ من الشمس والقمر والكواكب في فلك يسبحون، فلا يصطدم بعضها ببعض إلى نهاية الحياة.", "h": ["إقامة الأدلة القاطعة والبراهين الساطعة على إمكان البعث.", "ذكر القرآن لأمور الفلك التي لم يعرفها الناس إلا اليوم دليل على أنه وحي الله، وأن من أوحي إليه رسول الله قطعاً.", "ما ذكره القرآن عن الكون العلوي واضح يفهمه العالم والأمي، لتقوم الحجة على الجميع فيعبدوا الله وحده."], "k": "«ذلك تقدير العزيز العليم»… الكون كله يسير بتقديره بدقة؛ فهل أطمئن إلى تقديره في شأني الصغير؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 318;
insert into public.tdb_cards(topic, i, body) select 318, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٨ – ٣٢", "q": "۞وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندٖ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ ﴿٢٨﴾ إِن كَانَتۡ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ فَإِذَا هُمۡ خَٰمِدُونَ ﴿٢٩﴾ يَٰحَسۡرَةً عَلَى ٱلۡعِبَادِۚ مَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٣٠﴾ أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ أَنَّهُمۡ إِلَيۡهِمۡ لَا يَرۡجِعُونَ ﴿٣١﴾ وَإِن كُلّٞ لَّمَّا جَمِيعٞ لَّدَيۡنَا مُحۡضَرُونَ ﴿٣٢﴾", "w": [["وما أنزلنا على قومه", "على قوم حبيب بن النجار أهل أنطاكية."], ["من بعده", "من بعد موته."], ["من جند من السماء", "من الملائكة لإهلاكهم."], ["إن كانت إلا صيحة واحدة", "صيحة جبريل."], ["فإذا هم خامدون", "هلكى ساكنون لا حراك لهم."], ["يا حسرة على العباد", "احضري أيتها الحسرة، هذا أوان حضورك، والعباد هم المكذّبون للرسل."], ["ما يأتيهم من رسول إلا كانوا به يستهزئون", "هذا سبب التحسّر عليهم."], ["ألم يروا كم أهلكنا قبلهم", "ألم يعلم أهل مكة كم أهلكنا من القرون."], ["لدينا محضرون", "لحسابهم ومجازاتهم."]], "m": "وما أنزلنا على قوم حبيب بن النجار من بعد قتله جنداً من الملائكة للانتقام منهم، إذ لا حاجة إلى ذلك، وما كنا منزلين، إن كانت إلا صيحة واحدة من جبريل فإذا هم هلكى ساكنون. يا حسرة على العباد، احضري أيتها الحسرة فهذا أوانك، ما يأتيهم من رسول إلا كانوا به يستهزئون، وهذا موجب الحسرة. ألم يعلم أهل مكة كم أهلكنا قبلهم من القرون، كقوم نوح وعاد وثمود، أنهم إليهم لا يرجعون؟ فيعتبروا فيؤمنوا. وإنّ كلّ الخلائق لمجموعون لدينا محضرون لفصل القضاء، فينجو المؤمنون ويهلك الكافرون.", "h": ["مظاهر قدرة الله تعالى في إهلاك أهل أنطاكية بصيحة واحدة.", "إبداء التحسّر على العباد من أنفسهم، إذ هم الظالمون لها.", "حرمة الاستهزاء بما هو من حرمات الله تعالى التي يجب تعظيمها.", "طلب العبرة من أخبار الماضين وأحوالهم، والعاقل من اعتبر بغيره."], "k": "«يا حسرة على العباد»… ما الذي سأتحسّر عليه إن مضى عمري هكذا؟"}, {"lbl": "الآيات ٣٣ – ٣٦", "q": "وَءَايَةٞ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ أَحۡيَيۡنَٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبّٗا فَمِنۡهُ يَأۡكُلُونَ ﴿٣٣﴾ وَجَعَلۡنَا فِيهَا جَنَّـٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ وَفَجَّرۡنَا فِيهَا مِنَ ٱلۡعُيُونِ ﴿٣٤﴾ لِيَأۡكُلُواْ مِن ثَمَرِهِۦ وَمَا عَمِلَتۡهُ أَيۡدِيهِمۡۚ أَفَلَا يَشۡكُرُونَ ﴿٣٥﴾ سُبۡحَٰنَ ٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا يَعۡلَمُونَ ﴿٣٦﴾", "w": [["وآية لهم الأرض الميتة", "علامة على صحة البعث وإمكانه."], ["أحييناها", "بإنزال المطر عليها فأصبحت حيّة بالنبات."], ["وجعلنا فيها جنات", "بساتين."], ["وما عملته أيديهم", "لم تصنعه أيديهم وإنما هو صنع الله."], ["أفلا يشكرون", "أيرون هذه النعم ولا يشكرونها؟"], ["سبحان الذي خلق الأزواج كلها", "تنزيهاً لله الخالق."], ["ومن أنفسهم", "الذكور والإناث."], ["ومما لا يعلمون", "من المخلوقات في السماوات وتحت الأرض."]], "m": "لما قرّر البعث ذكر الدليل العقلي على إمكانه: وآية لهم الأرض الميتة، أحييناها بالمطر فأخرجنا منها حباً فمنه يأكلون، كذلك يحيي الله الموتى، إذ ينزل ماءً من تحت العرش فتحيا البشرية من عجب الذنب كما صحّ الخبر. وجعلنا فيها بساتين من نخيل وأعناب، وفجّرنا فيها من عيون الماء، ليأكلوا من ثمره، وما صنعته أيديهم بل يد الله، أفلا يشكرون؟ سبحان الذي خلق الأصناف كلها مما تنبت الأرض ومن أنفسهم ذكوراً وإناثاً ومما لا يعلمون مما في السماوات وباطن الأرض، فكل المخلوقات أزواج، والله وحده الفرد المنزّه عن صفات الخلق.", "h": ["تقرير عقيدة البعث والجزاء التي هي القوة الدافعة للعمل الصالح.", "دليل نظام الزوجية آية على أن القرآن وحي الله، إذ لم يعرف الناس هذا النظام في الذرّة وغيرها إلا في القرن الأخير.", "وجوب شكر الله تعالى بالإيمان وبطاعته على نعمه، كالإمداد بالغذاء والماء والهواء."], "k": "«وما عملته أيديهم أفلا يشكرون»… لقمة اليوم صنع الله قبل أن تكون كسبي؛ فهل شكرته عليها؟"}, {"lbl": "الآيات ٣٧ – ٤٠", "q": "وَءَايَةٞ لَّهُمُ ٱلَّيۡلُ نَسۡلَخُ مِنۡهُ ٱلنَّهَارَ فَإِذَا هُم مُّظۡلِمُونَ ﴿٣٧﴾ وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرّٖ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ﴿٣٨﴾ وَٱلۡقَمَرَ قَدَّرۡنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ ﴿٣٩﴾ لَا ٱلشَّمۡسُ يَنۢبَغِي لَهَآ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّيۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلّٞ فِي فَلَكٖ يَسۡبَحُونَ ﴿٤٠﴾", "w": [["الليل نسلخ منه النهار", "نكشط النهار عن الليل فإذا هم مظلمون."], ["لمستقرّ لها", "مكان لها لا تتجاوزه."], ["ذلك تقدير العزيز العليم", "جريها في فلكها تقدير من الله."], ["والقمر قدّرناه منازل", "ثمانية وعشرين منزلاً."], ["حتى عاد كالعرجون القديم", "كعود العِذق الأصفر الدقيق المقوّس."], ["لا الشمس ينبغي لها أن تدرك القمر", "لا يصح لها ولا يسهل."], ["ولا الليل سابق النهار", "بأن يأتي قبل انقضائه."], ["وكلٌّ في فلك يسبحون", "الشمس والقمر والنجوم يسيرون في أفلاكها."]], "m": "ما زال السياق في البرهنة على البعث: وآية لهم الليل نكشط منه النهار فإذا هم في الظلام. والشمس تجري في فلكها لمستقرّ لها، وإنها لتسجد كل يوم تحت العرش وتستأذن في استئناف دورانها فيؤذن لها كما صحّ الخبر، ذلك تقدير العزيز العليم، تسير بدقة لا تختل طوال الحياة، فالقادر على ذلك قادر على إحياء الموتى. والقمر قدّرناه منازل يتنقّل فيها كل شهر ليعرف أهل الأرض عدد السنين والحساب، يبدأ هلالاً ثم يكتمل بدراً في نصف الشهر ثم يضمحل حتى يعود كعود العذق القديم. لا الشمس ينبغي لها أن تدرك القمر فيذهب نورها بنوره، ولا الليل يسبق النهار، وكلٌّ من الشمس والقمر والكواكب في فلك يسبحون، فلا يصطدم بعضها ببعض إلى نهاية الحياة.", "h": ["إقامة الأدلة القاطعة والبراهين الساطعة على إمكان البعث.", "ذكر القرآن لأمور الفلك التي لم يعرفها الناس إلا اليوم دليل على أنه وحي الله، وأن من أوحي إليه رسول الله قطعاً.", "ما ذكره القرآن عن الكون العلوي واضح يفهمه العالم والأمي، لتقوم الحجة على الجميع فيعبدوا الله وحده."], "k": "«ذلك تقدير العزيز العليم»… الكون كله يسير بتقديره بدقة؛ فهل أطمئن إلى تقديره في شأني الصغير؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (319, 36, 41, 58, 'سورة يس ٤١ – ٥٨', '«وإذا قيل لهم أنفقوا مما رزقكم الله»، و«ونُفخ في الصور فإذا هم من الأجداث إلى ربهم ينسلون»، و«إن أصحاب الجنة اليوم في شغل فاكهون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 319) = $j$[{"lbl": "الآيات ٤١ – ٤٦", "q": "وَءَايَةٞ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّيَّتَهُمۡ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ﴿٤١﴾ وَخَلَقۡنَا لَهُم مِّن مِّثۡلِهِۦ مَا يَرۡكَبُونَ ﴿٤٢﴾ وَإِن نَّشَأۡ نُغۡرِقۡهُمۡ فَلَا صَرِيخَ لَهُمۡ وَلَا هُمۡ يُنقَذُونَ ﴿٤٣﴾ إِلَّا رَحۡمَةٗ مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٖ ﴿٤٤﴾ وَإِذَا قِيلَ لَهُمُ ٱتَّقُواْ مَا بَيۡنَ أَيۡدِيكُمۡ وَمَا خَلۡفَكُمۡ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿٤٥﴾ وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ ﴿٤٦﴾", "w": [["وآية لهم", "وعلامة على قدرتنا على البعث."], ["أنا حملنا ذريّتهم", "ذرية قوم نوح من المؤمنين، وأغرقنا آباءهم المشركين."], ["في الفلك المشحون", "سفينة نوح المملوءة."], ["وخلقنا لهم من مثله", "من مثل فلك نوح ما يركبون."], ["فلا صريخ لهم", "لا مغيث ينجيهم."], ["ومتاعاً إلى حين", "تمتيعاً لهم إلى آجالهم."], ["اتّقوا ما بين أيديكم", "من عذاب الدنيا."], ["وما خلفكم", "من عذاب الآخرة."], ["إلا كانوا عنها معرضين", "غير ملتفتين إليها."]], "m": "ما زال السياق في عرض الآيات الكونية: وآية لهم أنا حملنا ذرية قوم نوح المؤمنين في سفينة نوح المملوءة فأنجيناهم بإيمانهم، وأغرقنا الآباء المشركين، ولو كان مشركو مكة يعقلون لكان لهم فيه عبرة. وخلقنا لهم من مثل السفينة ما يركبون إلى يوم القيامة. وإن نشأ نغرقهم فلا مغيث لهم ولا هم يُنقذون، إلا رحمة منا وتمتيعاً لهم إلى آجالهم. وإذا قيل لهم: اتّقوا ما بين أيديكم من عذاب الدنيا، فإن موجبه قائم وهو كفركم، وما خلفكم من عذاب الآخرة، لعلكم ترحمون، أعرضوا، وما تأتيهم من آية من آيات ربهم تحمل الحجج على التوحيد إلا كانوا عنها معرضين تمام الإعراض.", "h": ["بيان فضل الله على البشرية في إنجاء ذرية قوم نوح المؤمنين، إذ لو أهلك الجميع لم يبق بشر.", "حماية الله تعالى للعباد ورعايته لهم، وإلا لهلكوا.", "بيان إصرار كفار قريش وعنادهم.", "الإشارة بالمثلية في قوله: «من مثله» إلى تنوّع السفن والمراكب."], "k": "«إلا رحمة منا ومتاعاً إلى حين»… كل نجاة مررت بها رحمة؛ فهل أتذكّرها؟"}, {"lbl": "الآيات ٤٧ – ٥٤", "q": "وَإِذَا قِيلَ لَهُمۡ أَنفِقُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَنُطۡعِمُ مَن لَّوۡ يَشَآءُ ٱللَّهُ أَطۡعَمَهُۥٓ إِنۡ أَنتُمۡ إِلَّا فِي ضَلَٰلٖ مُّبِينٖ ﴿٤٧﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٤٨﴾ مَا يَنظُرُونَ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ تَأۡخُذُهُمۡ وَهُمۡ يَخِصِّمُونَ ﴿٤٩﴾ فَلَا يَسۡتَطِيعُونَ تَوۡصِيَةٗ وَلَآ إِلَىٰٓ أَهۡلِهِمۡ يَرۡجِعُونَ ﴿٥٠﴾ وَنُفِخَ فِي ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلۡأَجۡدَاثِ إِلَىٰ رَبِّهِمۡ يَنسِلُونَ ﴿٥١﴾ قَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ هَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ ﴿٥٢﴾ إِن كَانَتۡ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ فَإِذَا هُمۡ جَمِيعٞ لَّدَيۡنَا مُحۡضَرُونَ ﴿٥٣﴾ فَٱلۡيَوۡمَ لَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗا وَلَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ ﴿٥٤﴾", "w": [["وإذا قيل لهم أنفقوا", "وإذا قال فقراء المؤمنين للمشركين."], ["مما رزقكم الله", "من المال."], ["أنطعم من لو يشاء الله أطعمه", "قالوا ذلك استهزاءً."], ["إن أنتم إلا في ضلال مبين", "ما أنتم إلا في ذهاب عن الحق."], ["متى هذا الوعد", "البعث، استهزاءً واستعجالاً."], ["ما ينظرون إلا صيحة واحدة", "نفخة إسرافيل."], ["تأخذهم وهم يخصّمون", "يختصمون في أسواقهم في البيع والشراء."], ["فلا يستطيعون توصية", "لا يقدر أحدهم أن يوصي."], ["من الأجداث", "من القبور."], ["ينسلون", "يخرجون مسرعين."], ["من بعثنا من مرقدنا", "قاله الكفار."], ["هذا ما وعد الرحمن", "قاله المؤمنون."]], "m": "وإذا قيل للمشركين: أنفقوا على المساكين مما رزقكم الله، قالوا استهزاءً: أنطعم من لو يشاء الله أطعمه؟ ما أنتم إلا في ضلال مبين، وقد رُوي أن أبا بكر كان يطعم مساكين فقال له أبو جهل: أتزعم أن الله قادر على إطعامهم؟ قال: نعم، ولكنه ابتلى قوماً بالفقر وقوماً بالغنى، وأمر الفقراء بالصبر والأغنياء بالإعطاء. ويقولون مستعجلين: متى هذا الوعد إن كنتم صادقين؟ ما ينتظرون إلا صيحة واحدة، نفخة إسرافيل، تأخذهم وهم يتخاصمون في أسواقهم، فلا يستطيعون أن يوصوا بشيء، ولا إلى أهلهم يرجعون، بل يهلكون في أماكنهم. ونُفخ في الصور فإذا هم من القبور إلى ربهم يخرجون مسرعين، قالوا: يا ويلنا من بعثنا من مرقدنا؟ فيجيبهم المؤمنون: هذا ما وعد الرحمن وصدق المرسلون. إن كانت إلا صيحة واحدة فإذا هم جميع لدينا محضرون، فاليوم لا تُظلم نفس شيئاً بنقص حسنة أو زيادة سيئة، ولا تُجزون إلا ما كنتم تعملون.", "h": ["بيان علوّ الكافرين وطغيانهم وسخريتهم بالمؤمنين.", "تقرير عقيدة البعث والجزاء بذكر مبادئها ونهاياتها.", "الساعة لا تأتي إلا بغتة.", "الظاهر أن النفخات أربع، أولاها نفخة الفناء، وآخرها نفخة القيام بين يدي رب العالمين.", "تقرير العدل الإلهي يوم الحساب والجزاء."], "k": "«أنطعم من لو يشاء الله أطعمه»… هل أتّخذ القدر حجّة لأمسك ما في يدي؟"}, {"lbl": "الآيات ٥٥ – ٥٨", "q": "إِنَّ أَصۡحَٰبَ ٱلۡجَنَّةِ ٱلۡيَوۡمَ فِي شُغُلٖ فَٰكِهُونَ ﴿٥٥﴾ هُمۡ وَأَزۡوَٰجُهُمۡ فِي ظِلَٰلٍ عَلَى ٱلۡأَرَآئِكِ مُتَّكِـُٔونَ ﴿٥٦﴾ لَهُمۡ فِيهَا فَٰكِهَةٞ وَلَهُم مَّا يَدَّعُونَ ﴿٥٧﴾ سَلَٰمٞ قَوۡلٗا مِّن رَّبّٖ رَّحِيمٖ ﴿٥٨﴾", "w": [["في شغل فاكهون", "في شغل عما فيه أهل النار، شغلهم النعيم المقيم."], ["فاكهون", "ناعمون يتلذّذون بالنعيم."], ["على الأرائك", "الأسرّة ذات الحِجال."], ["ولهم ما يدّعون", "ما يتمنّون ويطلبون."], ["سلام قولاً من رب رحيم", "يسلّم عليهم ربهم."]], "m": "ما إن حضروا بين يدي الله للحساب والجزاء حتى قال تعالى: إن أصحاب الجنة اليوم في شغل عما فيه أهل النار، ناعمون بالتلذّذ بألوان المطاعم والمشارب، هم وأزواجهم في ظلال الجنة على الأسرّة متكئون، لهم فيها فاكهة من كل نوع ولون، ولهم ما يتمنّون ويطلبون، وعليهم سلام بالقول من رب رحيم، وروى البغوي أنه بينما أهل الجنة في نعيمهم إذا الرب قد أشرف عليهم من فوقهم: السلام عليكم يا أهل الجنة، فينظر إليهم وينظرون إليه فلا يلتفتون إلى شيء من النعيم ما داموا ينظرون إليه.", "h": ["تقرير المعاد.", "بيان نعيم الجنة.", "سلام الله تعالى على أهل الجنة، ونظرهم إلى وجهه الكريم."], "k": "«سلام قولاً من رب رحيم»… أعظم نعيم أن يسلّم الله عليّ؛ فما الذي يقرّبني إلى سلامه؟"}]$j$::jsonb then 0 else 1 end;
