insert into public.tdb_cards(topic, i, body) select 319, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤١ – ٤٦", "q": "وَءَايَةٞ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّيَّتَهُمۡ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ﴿٤١﴾ وَخَلَقۡنَا لَهُم مِّن مِّثۡلِهِۦ مَا يَرۡكَبُونَ ﴿٤٢﴾ وَإِن نَّشَأۡ نُغۡرِقۡهُمۡ فَلَا صَرِيخَ لَهُمۡ وَلَا هُمۡ يُنقَذُونَ ﴿٤٣﴾ إِلَّا رَحۡمَةٗ مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٖ ﴿٤٤﴾ وَإِذَا قِيلَ لَهُمُ ٱتَّقُواْ مَا بَيۡنَ أَيۡدِيكُمۡ وَمَا خَلۡفَكُمۡ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿٤٥﴾ وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ ﴿٤٦﴾", "w": [["وآية لهم", "وعلامة على قدرتنا على البعث."], ["أنا حملنا ذريّتهم", "ذرية قوم نوح من المؤمنين، وأغرقنا آباءهم المشركين."], ["في الفلك المشحون", "سفينة نوح المملوءة."], ["وخلقنا لهم من مثله", "من مثل فلك نوح ما يركبون."], ["فلا صريخ لهم", "لا مغيث ينجيهم."], ["ومتاعاً إلى حين", "تمتيعاً لهم إلى آجالهم."], ["اتّقوا ما بين أيديكم", "من عذاب الدنيا."], ["وما خلفكم", "من عذاب الآخرة."], ["إلا كانوا عنها معرضين", "غير ملتفتين إليها."]], "m": "ما زال السياق في عرض الآيات الكونية: وآية لهم أنا حملنا ذرية قوم نوح المؤمنين في سفينة نوح المملوءة فأنجيناهم بإيمانهم، وأغرقنا الآباء المشركين، ولو كان مشركو مكة يعقلون لكان لهم فيه عبرة. وخلقنا لهم من مثل السفينة ما يركبون إلى يوم القيامة. وإن نشأ نغرقهم فلا مغيث لهم ولا هم يُنقذون، إلا رحمة منا وتمتيعاً لهم إلى آجالهم. وإذا قيل لهم: اتّقوا ما بين أيديكم من عذاب الدنيا، فإن موجبه قائم وهو كفركم، وما خلفكم من عذاب الآخرة، لعلكم ترحمون، أعرضوا، وما تأتيهم من آية من آيات ربهم تحمل الحجج على التوحيد إلا كانوا عنها معرضين تمام الإعراض.", "h": ["بيان فضل الله على البشرية في إنجاء ذرية قوم نوح المؤمنين، إذ لو أهلك الجميع لم يبق بشر.", "حماية الله تعالى للعباد ورعايته لهم، وإلا لهلكوا.", "بيان إصرار كفار قريش وعنادهم.", "الإشارة بالمثلية في قوله: «من مثله» إلى تنوّع السفن والمراكب."], "k": "«إلا رحمة منا ومتاعاً إلى حين»… كل نجاة مررت بها رحمة؛ فهل أتذكّرها؟"}, {"lbl": "الآيات ٤٧ – ٥٤", "q": "وَإِذَا قِيلَ لَهُمۡ أَنفِقُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَنُطۡعِمُ مَن لَّوۡ يَشَآءُ ٱللَّهُ أَطۡعَمَهُۥٓ إِنۡ أَنتُمۡ إِلَّا فِي ضَلَٰلٖ مُّبِينٖ ﴿٤٧﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٤٨﴾ مَا يَنظُرُونَ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ تَأۡخُذُهُمۡ وَهُمۡ يَخِصِّمُونَ ﴿٤٩﴾ فَلَا يَسۡتَطِيعُونَ تَوۡصِيَةٗ وَلَآ إِلَىٰٓ أَهۡلِهِمۡ يَرۡجِعُونَ ﴿٥٠﴾ وَنُفِخَ فِي ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلۡأَجۡدَاثِ إِلَىٰ رَبِّهِمۡ يَنسِلُونَ ﴿٥١﴾ قَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ هَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ ﴿٥٢﴾ إِن كَانَتۡ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ فَإِذَا هُمۡ جَمِيعٞ لَّدَيۡنَا مُحۡضَرُونَ ﴿٥٣﴾ فَٱلۡيَوۡمَ لَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗا وَلَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ ﴿٥٤﴾", "w": [["وإذا قيل لهم أنفقوا", "وإذا قال فقراء المؤمنين للمشركين."], ["مما رزقكم الله", "من المال."], ["أنطعم من لو يشاء الله أطعمه", "قالوا ذلك استهزاءً."], ["إن أنتم إلا في ضلال مبين", "ما أنتم إلا في ذهاب عن الحق."], ["متى هذا الوعد", "البعث، استهزاءً واستعجالاً."], ["ما ينظرون إلا صيحة واحدة", "نفخة إسرافيل."], ["تأخذهم وهم يخصّمون", "يختصمون في أسواقهم في البيع والشراء."], ["فلا يستطيعون توصية", "لا يقدر أحدهم أن يوصي."], ["من الأجداث", "من القبور."], ["ينسلون", "يخرجون مسرعين."], ["من بعثنا من مرقدنا", "قاله الكفار."], ["هذا ما وعد الرحمن", "قاله المؤمنون."]], "m": "وإذا قيل للمشركين: أنفقوا على المساكين مما رزقكم الله، قالوا استهزاءً: أنطعم من لو يشاء الله أطعمه؟ ما أنتم إلا في ضلال مبين، وقد رُوي أن أبا بكر كان يطعم مساكين فقال له أبو جهل: أتزعم أن الله قادر على إطعامهم؟ قال: نعم، ولكنه ابتلى قوماً بالفقر وقوماً بالغنى، وأمر الفقراء بالصبر والأغنياء بالإعطاء. ويقولون مستعجلين: متى هذا الوعد إن كنتم صادقين؟ ما ينتظرون إلا صيحة واحدة، نفخة إسرافيل، تأخذهم وهم يتخاصمون في أسواقهم، فلا يستطيعون أن يوصوا بشيء، ولا إلى أهلهم يرجعون، بل يهلكون في أماكنهم. ونُفخ في الصور فإذا هم من القبور إلى ربهم يخرجون مسرعين، قالوا: يا ويلنا من بعثنا من مرقدنا؟ فيجيبهم المؤمنون: هذا ما وعد الرحمن وصدق المرسلون. إن كانت إلا صيحة واحدة فإذا هم جميع لدينا محضرون، فاليوم لا تُظلم نفس شيئاً بنقص حسنة أو زيادة سيئة، ولا تُجزون إلا ما كنتم تعملون.", "h": ["بيان علوّ الكافرين وطغيانهم وسخريتهم بالمؤمنين.", "تقرير عقيدة البعث والجزاء بذكر مبادئها ونهاياتها.", "الساعة لا تأتي إلا بغتة.", "الظاهر أن النفخات أربع، أولاها نفخة الفناء، وآخرها نفخة القيام بين يدي رب العالمين.", "تقرير العدل الإلهي يوم الحساب والجزاء."], "k": "«أنطعم من لو يشاء الله أطعمه»… هل أتّخذ القدر حجّة لأمسك ما في يدي؟"}, {"lbl": "الآيات ٥٥ – ٥٨", "q": "إِنَّ أَصۡحَٰبَ ٱلۡجَنَّةِ ٱلۡيَوۡمَ فِي شُغُلٖ فَٰكِهُونَ ﴿٥٥﴾ هُمۡ وَأَزۡوَٰجُهُمۡ فِي ظِلَٰلٍ عَلَى ٱلۡأَرَآئِكِ مُتَّكِـُٔونَ ﴿٥٦﴾ لَهُمۡ فِيهَا فَٰكِهَةٞ وَلَهُم مَّا يَدَّعُونَ ﴿٥٧﴾ سَلَٰمٞ قَوۡلٗا مِّن رَّبّٖ رَّحِيمٖ ﴿٥٨﴾", "w": [["في شغل فاكهون", "في شغل عما فيه أهل النار، شغلهم النعيم المقيم."], ["فاكهون", "ناعمون يتلذّذون بالنعيم."], ["على الأرائك", "الأسرّة ذات الحِجال."], ["ولهم ما يدّعون", "ما يتمنّون ويطلبون."], ["سلام قولاً من رب رحيم", "يسلّم عليهم ربهم."]], "m": "ما إن حضروا بين يدي الله للحساب والجزاء حتى قال تعالى: إن أصحاب الجنة اليوم في شغل عما فيه أهل النار، ناعمون بالتلذّذ بألوان المطاعم والمشارب، هم وأزواجهم في ظلال الجنة على الأسرّة متكئون، لهم فيها فاكهة من كل نوع ولون، ولهم ما يتمنّون ويطلبون، وعليهم سلام بالقول من رب رحيم، وروى البغوي أنه بينما أهل الجنة في نعيمهم إذا الرب قد أشرف عليهم من فوقهم: السلام عليكم يا أهل الجنة، فينظر إليهم وينظرون إليه فلا يلتفتون إلى شيء من النعيم ما داموا ينظرون إليه.", "h": ["تقرير المعاد.", "بيان نعيم الجنة.", "سلام الله تعالى على أهل الجنة، ونظرهم إلى وجهه الكريم."], "k": "«سلام قولاً من رب رحيم»… أعظم نعيم أن يسلّم الله عليّ؛ فما الذي يقرّبني إلى سلامه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (320, 36, 59, 83, 'سورة يس ٥٩ – ٨٣', '«وامتازوا اليوم أيها المجرمون»، و«اليوم نختم على أفواههم»، و«قل يحييها الذي أنشأها أول مرة»، و«إنما أمره إذا أراد شيئاً أن يقول له كن فيكون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 320) = $j$[{"lbl": "الآيات ٥٩ – ٦٨", "q": "وَٱمۡتَٰزُواْ ٱلۡيَوۡمَ أَيُّهَا ٱلۡمُجۡرِمُونَ ﴿٥٩﴾ ۞أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ﴿٦٠﴾ وَأَنِ ٱعۡبُدُونِيۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ﴿٦١﴾ وَلَقَدۡ أَضَلَّ مِنكُمۡ جِبِلّٗا كَثِيرًاۖ أَفَلَمۡ تَكُونُواْ تَعۡقِلُونَ ﴿٦٢﴾ هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي كُنتُمۡ تُوعَدُونَ ﴿٦٣﴾ ٱصۡلَوۡهَا ٱلۡيَوۡمَ بِمَا كُنتُمۡ تَكۡفُرُونَ ﴿٦٤﴾ ٱلۡيَوۡمَ نَخۡتِمُ عَلَىٰٓ أَفۡوَٰهِهِمۡ وَتُكَلِّمُنَآ أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُواْ يَكۡسِبُونَ ﴿٦٥﴾ وَلَوۡ نَشَآءُ لَطَمَسۡنَا عَلَىٰٓ أَعۡيُنِهِمۡ فَٱسۡتَبَقُواْ ٱلصِّرَٰطَ فَأَنَّىٰ يُبۡصِرُونَ ﴿٦٦﴾ وَلَوۡ نَشَآءُ لَمَسَخۡنَٰهُمۡ عَلَىٰ مَكَانَتِهِمۡ فَمَا ٱسۡتَطَٰعُواْ مُضِيّٗا وَلَا يَرۡجِعُونَ ﴿٦٧﴾ وَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِي ٱلۡخَلۡقِۚ أَفَلَا يَعۡقِلُونَ ﴿٦٨﴾", "w": [["وامتازوا اليوم أيها المجرمون", "انفردوا عن المؤمنين."], ["ألم أعهد إليكم", "ألم أوصكم بترك عبادة الشيطان."], ["وأن اعبدوني", "وحدي، في كتبي وعلى ألسنة رسلي."], ["هذا صراط مستقيم", "ترك عبادة الشيطان وطاعة الرحمن."], ["جبلاً كثيراً", "خلقاً كثيراً."], ["اليوم نختم على أفواههم", "فلا تنطق."], ["ولو نشاء لطمسنا على أعينهم", "لأعميناهم، ولكنا لم نشأ رحمة منا."], ["فاستبقوا الصراط", "ابتدروا الطريق كعادتهم، فكيف يبصرون؟"], ["لمسخناهم على مكانتهم", "بدّلنا خلقهم في أماكنهم."], ["ومن نعمّره ننكّسه في الخلق", "نطيل عمره فنردّه إلى الضعف."]], "m": "يأمر الله يوم القيامة المجرمين الذين أفسدوا أنفسهم بالشرك أن ينفردوا عن المؤمنين، ويُسار بأهل الجنة إلى الجنة، ثم يوبّخهم: ألم أعهد إليكم يا بني آدم على ألسنة رسلي وفي كتبي ألا تعبدوا الشيطان، إنه لكم عدو مبين، وأن اعبدوني وحدي، هذا صراط مستقيم موصل إلى دار السلام؟ ولقد أضلّ الشيطان منكم خلقاً كثيراً، أفلم تكونوا تعقلون عداوته وأنا الذي خلقتكم ورزقتكم؟ هذه جهنم التي كنتم توعدون، احترقوا بها اليوم بما كنتم تكفرون. اليوم نختم على أفواههم حين يُنكرون أعمالهم، وتكلّمنا أيديهم وتشهد أرجلهم بما كانوا يكسبون. ولو نشاء لطمسنا على أعينهم فابتدروا الطريق فأنّى يبصرون، ولو نشاء لمسخناهم في أماكنهم فلا يستطيعون مضياً ولا رجوعاً، ولكن لم نشأ ذلك رحمة منا. ومن نطل عمره نردّه في الخلق، فكما كان طفلاً ينمو يأخذ يضعف حتى يصير كالطفل، أفلا يعقلون أن القادر على ذلك قادر على بعثهم؟", "h": ["تقرير المعاد وبيان مواقف منه.", "تأكيد عداوة الشيطان للإنسان.", "عجز الإنسان يوم القيامة عن كتمان شيء من سيئ أعماله.", "التحذير من عقوبة الله في الدنيا بالمسخ ونحوه.", "مظاهر قدرة الله تعالى في ردّ الإنسان بعد القوة إلى الضعف."], "k": "«وتكلّمنا أيديهم وتشهد أرجلهم»… يدي التي تكتب الآن ستشهد؛ فبماذا أحب أن تشهد؟"}, {"lbl": "الآيات ٦٩ – ٧٦", "q": "وَمَا عَلَّمۡنَٰهُ ٱلشِّعۡرَ وَمَا يَنۢبَغِي لَهُۥٓۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ وَقُرۡءَانٞ مُّبِينٞ ﴿٦٩﴾ لِّيُنذِرَ مَن كَانَ حَيّٗا وَيَحِقَّ ٱلۡقَوۡلُ عَلَى ٱلۡكَٰفِرِينَ ﴿٧٠﴾ أَوَلَمۡ يَرَوۡاْ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَيۡدِينَآ أَنۡعَٰمٗا فَهُمۡ لَهَا مَٰلِكُونَ ﴿٧١﴾ وَذَلَّلۡنَٰهَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ وَمِنۡهَا يَأۡكُلُونَ ﴿٧٢﴾ وَلَهُمۡ فِيهَا مَنَٰفِعُ وَمَشَارِبُۚ أَفَلَا يَشۡكُرُونَ ﴿٧٣﴾ وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لَّعَلَّهُمۡ يُنصَرُونَ ﴿٧٤﴾ لَا يَسۡتَطِيعُونَ نَصۡرَهُمۡ وَهُمۡ لَهُمۡ جُندٞ مُّحۡضَرُونَ ﴿٧٥﴾ فَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ ﴿٧٦﴾", "w": [["وما علّمناه الشعر", "ما علّمنا رسولنا الشعر."], ["وما ينبغي له", "ما يصلح له ولا يصح منه."], ["إن هو إلا ذكر وقرآن مبين", "ما هو إلا عظة وقرآن مبيّن للحق."], ["لينذر من كان حيّاً", "يعقل ما يُخاطب به، وهم المؤمنون."], ["ويحقّ القول على الكافرين", "يجب عليهم العذاب لأنهم لا يقبلون النذارة."], ["فهم لها مالكون", "يتصرّفون فيها."], ["وذلّلناها لهم", "سخّرناها وجعلناهم قاهرين لها."], ["ومشارب", "ألبانها."], ["وهم لهم جند محضرون", "المشركون للأصنام جند يدافعون عنها."], ["فلا يحزنك قولهم", "إنك شاعر وكاهن."]], "m": "ردّ على المشركين الذين قالوا إن محمداً شاعر: وما علّمناه الشعر وما يصلح له، ما هو الذي يتلوه إلا عظة وقرآن مبيّن للحق، أنزلناه لينذر من كان حيّ القلب، ويحقّ القول بالعذاب على الكافرين الذين يعيشون على الضلال ويموتون عليه. أوَلم يروا أنا خلقنا لهم مما عملت أيدينا أنعاماً فهم لها مالكون يتصرّفون فيها، وذلّلناها لهم فمنها ركوبهم كالإبل ومنها يأكلون، ولهم فيها منافع كالصوف والوبر، ومشارب من ألبانها، أفلا يشكرون الله بالإيمان والتوحيد؟ واتّخذوا من دون الله آلهة لعلهم يُنصرون بشفاعتها، لا يستطيعون نصرهم، والحال أن المشركين هم جند محضرون للأصنام يدافعون عنها ويغضبون لها، فكيف تنصرهم؟ فلا يحزنك قولهم إنك شاعر وساحر وكاهن، إنا نعلم ما يُسرّون من الحسد والعناد وما يعلنون.", "h": ["تقرير النبوة المحمدية، وأن القرآن ذكر وليس شعراً كما يزعم المشركون.", "الحكمة من نزول القرآن أن يُنذر به الرسول الأحياء.", "بيان خطأ الذين يقرؤون القرآن على الأموات ويتركون الأحياء دون إرشاد وتعليم وتذكير.", "وجوب ذكر النعم وشكرها بالاعتراف بها وصرفها في مرضاة الله.", "بيان سخف المشركين في عبادتهم أصناماً يرجون نصرها وهم ينصرونها."], "k": "«لينذر من كان حيّاً»… هل قلبي حيّ يتّعظ بما أقرأ، أم أقرأ القرآن كأنه للموتى؟"}, {"lbl": "الآيات ٧٧ – ٨٣", "q": "أَوَلَمۡ يَرَ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن نُّطۡفَةٖ فَإِذَا هُوَ خَصِيمٞ مُّبِينٞ ﴿٧٧﴾ وَضَرَبَ لَنَا مَثَلٗا وَنَسِيَ خَلۡقَهُۥۖ قَالَ مَن يُحۡيِ ٱلۡعِظَٰمَ وَهِيَ رَمِيمٞ ﴿٧٨﴾ قُلۡ يُحۡيِيهَا ٱلَّذِيٓ أَنشَأَهَآ أَوَّلَ مَرَّةٖۖ وَهُوَ بِكُلِّ خَلۡقٍ عَلِيمٌ ﴿٧٩﴾ ٱلَّذِي جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارٗا فَإِذَآ أَنتُم مِّنۡهُ تُوقِدُونَ ﴿٨٠﴾ أَوَلَيۡسَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۚ بَلَىٰ وَهُوَ ٱلۡخَلَّـٰقُ ٱلۡعَلِيمُ ﴿٨١﴾ إِنَّمَآ أَمۡرُهُۥٓ إِذَآ أَرَادَ شَيۡـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ ﴿٨٢﴾ فَسُبۡحَٰنَ ٱلَّذِي بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٨٣﴾", "w": [["أوَلم يرَ الإنسان", "المنكر للبعث كالعاص بن وائل."], ["أنا خلقناه من نطفة", "من منيّ إلى أن صيّرناه رجلاً قوياً."], ["فإذا هو خصيم مبين", "شديد الخصومة في نفي البعث."], ["وضرب لنا مثلاً", "أخذ عظماً ففتّه أمام رسول الله."], ["ونسي خلقه", "أنه مخلوق من ماء مهين، والقادر على الخلق الأول قادر على الثاني."], ["وهي رميم", "وقد رمّت وبليت."], ["من الشجر الأخضر ناراً", "من شجر المرخ والعفار يُحكّ بعضه ببعض فتخرج النار."], ["بقادر على أن يخلق مثلهم", "بلى، إذ خلق السماوات والأرض أكبر من خلق الناس."], ["بيده ملكوت كل شيء", "ملك كل شيء، زيدت التاء للمبالغة."]], "m": "ما زال السياق في تقرير البعث: جاء العاص بن وائل إلى رسول الله وفي يده عظم ففتّه وذرّاه وقال: أتزعم يا محمد أن الله يحيي هذا؟ قال: «نعم، يميتك ثم يحييك ثم يحشرك إلى جهنم»، فنزلت: أوَلم يرَ الإنسان أنا خلقناه من نطفة فإذا هو خصيم مبين، وضرب لنا مثلاً ونسي أصل خلقه، قال: من يحيي العظام وهي رميم؟ قل: يحييها الذي أنشأها أول مرة، وهو بكل خلق عليم، وهذا برهان أول: القادر على البدء قادر على الإعادة. والبرهان الثاني: الذي جعل لكم من الشجر الأخضر ناراً، يُخرج النار من الماء الساري في الشجر، فإذا أنتم منه توقدون. والثالث: أوليس الذي خلق السماوات والأرض بقادر على أن يخلق مثلهم؟ بلى، وهو الخلّاق العليم. والرابع: إنما أمره إذا أراد شيئاً أن يقول له كن فيكون، فمن كان هذا شأنه لا يصعب عليه أن يحيي الموتى بكلمة. فسبحان الذي بيده ملك كل شيء، وإليه ترجعون أحببتم أم كرهتم.", "h": ["تقرير عقيدة البعث والجزاء بإيراد أربعة براهين قاطعة.", "مشروعية استعمال العقليات في الحجج والمجادلة.", "تنزيه الله تعالى عن العجز والنقص وعن الشريك والولد.", "تقرير أن الله تعالى بيده وفي تصرّفه وتحت قهره كل شيء."], "k": "«ونسي خلقه»… من ينسى من أين جاء يستبعد ما سيكون؛ فهل أتذكّر بدايتي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 320;
insert into public.tdb_cards(topic, i, body) select 320, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٩ – ٦٨", "q": "وَٱمۡتَٰزُواْ ٱلۡيَوۡمَ أَيُّهَا ٱلۡمُجۡرِمُونَ ﴿٥٩﴾ ۞أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ﴿٦٠﴾ وَأَنِ ٱعۡبُدُونِيۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ﴿٦١﴾ وَلَقَدۡ أَضَلَّ مِنكُمۡ جِبِلّٗا كَثِيرًاۖ أَفَلَمۡ تَكُونُواْ تَعۡقِلُونَ ﴿٦٢﴾ هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي كُنتُمۡ تُوعَدُونَ ﴿٦٣﴾ ٱصۡلَوۡهَا ٱلۡيَوۡمَ بِمَا كُنتُمۡ تَكۡفُرُونَ ﴿٦٤﴾ ٱلۡيَوۡمَ نَخۡتِمُ عَلَىٰٓ أَفۡوَٰهِهِمۡ وَتُكَلِّمُنَآ أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُواْ يَكۡسِبُونَ ﴿٦٥﴾ وَلَوۡ نَشَآءُ لَطَمَسۡنَا عَلَىٰٓ أَعۡيُنِهِمۡ فَٱسۡتَبَقُواْ ٱلصِّرَٰطَ فَأَنَّىٰ يُبۡصِرُونَ ﴿٦٦﴾ وَلَوۡ نَشَآءُ لَمَسَخۡنَٰهُمۡ عَلَىٰ مَكَانَتِهِمۡ فَمَا ٱسۡتَطَٰعُواْ مُضِيّٗا وَلَا يَرۡجِعُونَ ﴿٦٧﴾ وَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِي ٱلۡخَلۡقِۚ أَفَلَا يَعۡقِلُونَ ﴿٦٨﴾", "w": [["وامتازوا اليوم أيها المجرمون", "انفردوا عن المؤمنين."], ["ألم أعهد إليكم", "ألم أوصكم بترك عبادة الشيطان."], ["وأن اعبدوني", "وحدي، في كتبي وعلى ألسنة رسلي."], ["هذا صراط مستقيم", "ترك عبادة الشيطان وطاعة الرحمن."], ["جبلاً كثيراً", "خلقاً كثيراً."], ["اليوم نختم على أفواههم", "فلا تنطق."], ["ولو نشاء لطمسنا على أعينهم", "لأعميناهم، ولكنا لم نشأ رحمة منا."], ["فاستبقوا الصراط", "ابتدروا الطريق كعادتهم، فكيف يبصرون؟"], ["لمسخناهم على مكانتهم", "بدّلنا خلقهم في أماكنهم."], ["ومن نعمّره ننكّسه في الخلق", "نطيل عمره فنردّه إلى الضعف."]], "m": "يأمر الله يوم القيامة المجرمين الذين أفسدوا أنفسهم بالشرك أن ينفردوا عن المؤمنين، ويُسار بأهل الجنة إلى الجنة، ثم يوبّخهم: ألم أعهد إليكم يا بني آدم على ألسنة رسلي وفي كتبي ألا تعبدوا الشيطان، إنه لكم عدو مبين، وأن اعبدوني وحدي، هذا صراط مستقيم موصل إلى دار السلام؟ ولقد أضلّ الشيطان منكم خلقاً كثيراً، أفلم تكونوا تعقلون عداوته وأنا الذي خلقتكم ورزقتكم؟ هذه جهنم التي كنتم توعدون، احترقوا بها اليوم بما كنتم تكفرون. اليوم نختم على أفواههم حين يُنكرون أعمالهم، وتكلّمنا أيديهم وتشهد أرجلهم بما كانوا يكسبون. ولو نشاء لطمسنا على أعينهم فابتدروا الطريق فأنّى يبصرون، ولو نشاء لمسخناهم في أماكنهم فلا يستطيعون مضياً ولا رجوعاً، ولكن لم نشأ ذلك رحمة منا. ومن نطل عمره نردّه في الخلق، فكما كان طفلاً ينمو يأخذ يضعف حتى يصير كالطفل، أفلا يعقلون أن القادر على ذلك قادر على بعثهم؟", "h": ["تقرير المعاد وبيان مواقف منه.", "تأكيد عداوة الشيطان للإنسان.", "عجز الإنسان يوم القيامة عن كتمان شيء من سيئ أعماله.", "التحذير من عقوبة الله في الدنيا بالمسخ ونحوه.", "مظاهر قدرة الله تعالى في ردّ الإنسان بعد القوة إلى الضعف."], "k": "«وتكلّمنا أيديهم وتشهد أرجلهم»… يدي التي تكتب الآن ستشهد؛ فبماذا أحب أن تشهد؟"}, {"lbl": "الآيات ٦٩ – ٧٦", "q": "وَمَا عَلَّمۡنَٰهُ ٱلشِّعۡرَ وَمَا يَنۢبَغِي لَهُۥٓۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ وَقُرۡءَانٞ مُّبِينٞ ﴿٦٩﴾ لِّيُنذِرَ مَن كَانَ حَيّٗا وَيَحِقَّ ٱلۡقَوۡلُ عَلَى ٱلۡكَٰفِرِينَ ﴿٧٠﴾ أَوَلَمۡ يَرَوۡاْ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَيۡدِينَآ أَنۡعَٰمٗا فَهُمۡ لَهَا مَٰلِكُونَ ﴿٧١﴾ وَذَلَّلۡنَٰهَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ وَمِنۡهَا يَأۡكُلُونَ ﴿٧٢﴾ وَلَهُمۡ فِيهَا مَنَٰفِعُ وَمَشَارِبُۚ أَفَلَا يَشۡكُرُونَ ﴿٧٣﴾ وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لَّعَلَّهُمۡ يُنصَرُونَ ﴿٧٤﴾ لَا يَسۡتَطِيعُونَ نَصۡرَهُمۡ وَهُمۡ لَهُمۡ جُندٞ مُّحۡضَرُونَ ﴿٧٥﴾ فَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ ﴿٧٦﴾", "w": [["وما علّمناه الشعر", "ما علّمنا رسولنا الشعر."], ["وما ينبغي له", "ما يصلح له ولا يصح منه."], ["إن هو إلا ذكر وقرآن مبين", "ما هو إلا عظة وقرآن مبيّن للحق."], ["لينذر من كان حيّاً", "يعقل ما يُخاطب به، وهم المؤمنون."], ["ويحقّ القول على الكافرين", "يجب عليهم العذاب لأنهم لا يقبلون النذارة."], ["فهم لها مالكون", "يتصرّفون فيها."], ["وذلّلناها لهم", "سخّرناها وجعلناهم قاهرين لها."], ["ومشارب", "ألبانها."], ["وهم لهم جند محضرون", "المشركون للأصنام جند يدافعون عنها."], ["فلا يحزنك قولهم", "إنك شاعر وكاهن."]], "m": "ردّ على المشركين الذين قالوا إن محمداً شاعر: وما علّمناه الشعر وما يصلح له، ما هو الذي يتلوه إلا عظة وقرآن مبيّن للحق، أنزلناه لينذر من كان حيّ القلب، ويحقّ القول بالعذاب على الكافرين الذين يعيشون على الضلال ويموتون عليه. أوَلم يروا أنا خلقنا لهم مما عملت أيدينا أنعاماً فهم لها مالكون يتصرّفون فيها، وذلّلناها لهم فمنها ركوبهم كالإبل ومنها يأكلون، ولهم فيها منافع كالصوف والوبر، ومشارب من ألبانها، أفلا يشكرون الله بالإيمان والتوحيد؟ واتّخذوا من دون الله آلهة لعلهم يُنصرون بشفاعتها، لا يستطيعون نصرهم، والحال أن المشركين هم جند محضرون للأصنام يدافعون عنها ويغضبون لها، فكيف تنصرهم؟ فلا يحزنك قولهم إنك شاعر وساحر وكاهن، إنا نعلم ما يُسرّون من الحسد والعناد وما يعلنون.", "h": ["تقرير النبوة المحمدية، وأن القرآن ذكر وليس شعراً كما يزعم المشركون.", "الحكمة من نزول القرآن أن يُنذر به الرسول الأحياء.", "بيان خطأ الذين يقرؤون القرآن على الأموات ويتركون الأحياء دون إرشاد وتعليم وتذكير.", "وجوب ذكر النعم وشكرها بالاعتراف بها وصرفها في مرضاة الله.", "بيان سخف المشركين في عبادتهم أصناماً يرجون نصرها وهم ينصرونها."], "k": "«لينذر من كان حيّاً»… هل قلبي حيّ يتّعظ بما أقرأ، أم أقرأ القرآن كأنه للموتى؟"}, {"lbl": "الآيات ٧٧ – ٨٣", "q": "أَوَلَمۡ يَرَ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن نُّطۡفَةٖ فَإِذَا هُوَ خَصِيمٞ مُّبِينٞ ﴿٧٧﴾ وَضَرَبَ لَنَا مَثَلٗا وَنَسِيَ خَلۡقَهُۥۖ قَالَ مَن يُحۡيِ ٱلۡعِظَٰمَ وَهِيَ رَمِيمٞ ﴿٧٨﴾ قُلۡ يُحۡيِيهَا ٱلَّذِيٓ أَنشَأَهَآ أَوَّلَ مَرَّةٖۖ وَهُوَ بِكُلِّ خَلۡقٍ عَلِيمٌ ﴿٧٩﴾ ٱلَّذِي جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارٗا فَإِذَآ أَنتُم مِّنۡهُ تُوقِدُونَ ﴿٨٠﴾ أَوَلَيۡسَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۚ بَلَىٰ وَهُوَ ٱلۡخَلَّـٰقُ ٱلۡعَلِيمُ ﴿٨١﴾ إِنَّمَآ أَمۡرُهُۥٓ إِذَآ أَرَادَ شَيۡـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ ﴿٨٢﴾ فَسُبۡحَٰنَ ٱلَّذِي بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٨٣﴾", "w": [["أوَلم يرَ الإنسان", "المنكر للبعث كالعاص بن وائل."], ["أنا خلقناه من نطفة", "من منيّ إلى أن صيّرناه رجلاً قوياً."], ["فإذا هو خصيم مبين", "شديد الخصومة في نفي البعث."], ["وضرب لنا مثلاً", "أخذ عظماً ففتّه أمام رسول الله."], ["ونسي خلقه", "أنه مخلوق من ماء مهين، والقادر على الخلق الأول قادر على الثاني."], ["وهي رميم", "وقد رمّت وبليت."], ["من الشجر الأخضر ناراً", "من شجر المرخ والعفار يُحكّ بعضه ببعض فتخرج النار."], ["بقادر على أن يخلق مثلهم", "بلى، إذ خلق السماوات والأرض أكبر من خلق الناس."], ["بيده ملكوت كل شيء", "ملك كل شيء، زيدت التاء للمبالغة."]], "m": "ما زال السياق في تقرير البعث: جاء العاص بن وائل إلى رسول الله وفي يده عظم ففتّه وذرّاه وقال: أتزعم يا محمد أن الله يحيي هذا؟ قال: «نعم، يميتك ثم يحييك ثم يحشرك إلى جهنم»، فنزلت: أوَلم يرَ الإنسان أنا خلقناه من نطفة فإذا هو خصيم مبين، وضرب لنا مثلاً ونسي أصل خلقه، قال: من يحيي العظام وهي رميم؟ قل: يحييها الذي أنشأها أول مرة، وهو بكل خلق عليم، وهذا برهان أول: القادر على البدء قادر على الإعادة. والبرهان الثاني: الذي جعل لكم من الشجر الأخضر ناراً، يُخرج النار من الماء الساري في الشجر، فإذا أنتم منه توقدون. والثالث: أوليس الذي خلق السماوات والأرض بقادر على أن يخلق مثلهم؟ بلى، وهو الخلّاق العليم. والرابع: إنما أمره إذا أراد شيئاً أن يقول له كن فيكون، فمن كان هذا شأنه لا يصعب عليه أن يحيي الموتى بكلمة. فسبحان الذي بيده ملك كل شيء، وإليه ترجعون أحببتم أم كرهتم.", "h": ["تقرير عقيدة البعث والجزاء بإيراد أربعة براهين قاطعة.", "مشروعية استعمال العقليات في الحجج والمجادلة.", "تنزيه الله تعالى عن العجز والنقص وعن الشريك والولد.", "تقرير أن الله تعالى بيده وفي تصرّفه وتحت قهره كل شيء."], "k": "«ونسي خلقه»… من ينسى من أين جاء يستبعد ما سيكون؛ فهل أتذكّر بدايتي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (321, 37, 1, 21, 'سورة الصافات ١ – ٢١', 'الصافات: إن إلهكم لواحد', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 321) = $j$[{"lbl": "الآيات ١ – ١٠", "q": "وَٱلصَّـٰٓفَّـٰتِ صَفّٗا ﴿١﴾ فَٱلزَّـٰجِرَٰتِ زَجۡرٗا ﴿٢﴾ فَٱلتَّـٰلِيَٰتِ ذِكۡرًا ﴿٣﴾ إِنَّ إِلَٰهَكُمۡ لَوَٰحِدٞ ﴿٤﴾ رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَرَبُّ ٱلۡمَشَٰرِقِ ﴿٥﴾ إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِزِينَةٍ ٱلۡكَوَاكِبِ ﴿٦﴾ وَحِفۡظٗا مِّن كُلِّ شَيۡطَٰنٖ مَّارِدٖ ﴿٧﴾ لَّا يَسَّمَّعُونَ إِلَى ٱلۡمَلَإِ ٱلۡأَعۡلَىٰ وَيُقۡذَفُونَ مِن كُلِّ جَانِبٖ ﴿٨﴾ دُحُورٗاۖ وَلَهُمۡ عَذَابٞ وَاصِبٌ ﴿٩﴾ إِلَّا مَنۡ خَطِفَ ٱلۡخَطۡفَةَ فَأَتۡبَعَهُۥ شِهَابٞ ثَاقِبٞ ﴿١٠﴾", "w": [["والصافات صفاً", "الملائكة تصف أنفسها في الصلاة وأجنحتها في الهواء."], ["فالزاجرات زجراً", "الملائكة تزجر السحاب أي تسوقه حيث يأذن الله."], ["فالتاليات ذكراً", "الجماعات التاليات للقرآن."], ["ورب المشارق", "والمغارب، وهي مشارق الشمس ومغاربها، إذ للشمس كل يوم مشرق ومغرب."], ["وحفظاً من كل شيطان مارد", "حفظناها حفظاً من كل شيطان خارج عن الطاعة."], ["لا يسّمّعون إلى الملإ الأعلى", "لا يستمعون إلى الملائكة في السماوات العلا."], ["دحوراً", "يُرمون بالشهب من كل جوانب السماء إبعاداً لهم."], ["عذاب واصب", "دائم لا يفارقهم."], ["إلا من خطف الخطفة", "اختطف الكلمة من الملائكة بسرعة وهرب."], ["فأتبعه شهاب ثاقب", "كوكب مضيء يثقبه أو يحرقه أو يخبله أي يفسده."]], "m": "هذا قسم إلهي يؤكد به تعالى إلهيته على عباده، فأقسم بالصافات والزاجرات والتاليات ذكراً، ولله أن يقسم بما شاء من خلقه، وإنما الممنوع أن يقسم العبد بغير ربه. والقسم جارٍ على عرف البشر في تأكيد الخبر باليمين ليزول الشك. والمقسم عليه: إن إلهكم لواحد، فإله البشرية كلها واحد هو الله خالقها ورازقها، وما عندها من آلهة فباطلة، يكفي في بطلانها أنها أصنام وصور وتماثيل وصلبان لا تسمع ولا تبصر ولا تنفع ولا تضر. ثم دلّل على وحدانيته بأنه رب السماوات والأرض وما بينهما ورب المشارق، فالإله الحق هو الخالق للعوالم المدبر لها، لا الذي ينحته الرجل بيده. ثم ذكر مظاهر قدرته: زيّن السماء الدنيا بالكواكب، وحفظها من كل شيطان متمرد، فلا يتسمّعون إلى الملائكة لينقلوا أخبار الغيب إلى أوليائهم من الكهان، ويُرمَون من كل جهة دحوراً، ولهم عذاب دائم، إلا من اختطف الكلمة بسرعة فأتبعه شهاب ثاقب فقتله أو أحرقه أو أفسده. وبهذا حُميت السماء من استراق السمع.", "h": ["بيان أن الله تعالى يُقسم ببعض مخلوقاته إما تنويهاً بعظمتها المقرِّر ضمناً لعظمة خالقها، وإما بياناً لفضلها، وإما لفتاً لنظر العباد إلى ما فيها من الفوائد.", "تقرير التوحيد وأنه لا إله إلا الله.", "بيان الحكمة من وجود النجوم في السماء الدنيا.", "بيان أن الشياطين حُرموا من استراق السمع."], "k": "«إن إلهكم لواحد»… أقسم الله ليُزيل الشك؛ فهل في قلبي التفات إلى غيره؟"}, {"lbl": "الآيات ١١ – ٢١", "q": "فَٱسۡتَفۡتِهِمۡ أَهُمۡ أَشَدُّ خَلۡقًا أَم مَّنۡ خَلَقۡنَآۚ إِنَّا خَلَقۡنَٰهُم مِّن طِينٖ لَّازِبِۭ ﴿١١﴾ بَلۡ عَجِبۡتَ وَيَسۡخَرُونَ ﴿١٢﴾ وَإِذَا ذُكِّرُواْ لَا يَذۡكُرُونَ ﴿١٣﴾ وَإِذَا رَأَوۡاْ ءَايَةٗ يَسۡتَسۡخِرُونَ ﴿١٤﴾ وَقَالُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٌ ﴿١٥﴾ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ ﴿١٦﴾ أَوَءَابَآؤُنَا ٱلۡأَوَّلُونَ ﴿١٧﴾ قُلۡ نَعَمۡ وَأَنتُمۡ دَٰخِرُونَ ﴿١٨﴾ فَإِنَّمَا هِيَ زَجۡرَةٞ وَٰحِدَةٞ فَإِذَا هُمۡ يَنظُرُونَ ﴿١٩﴾ وَقَالُواْ يَٰوَيۡلَنَا هَٰذَا يَوۡمُ ٱلدِّينِ ﴿٢٠﴾ هَٰذَا يَوۡمُ ٱلۡفَصۡلِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ ﴿٢١﴾", "w": [["فاستفتهم", "استخبر كفار مكة تقريراً وتوبيخاً."], ["أهم أشد خلقاً أم من خلقنا", "خلقهم في ذواتهم وإعادتهم بعد موتهم، أم من خلق تعالى من الملائكة والسماوات والأرض."], ["من طين لازب", "يلصق باليد."], ["بل عجبت ويسخرون", "عجبت يا نبي الله من إنكارهم للبعث، وهم يسخرون من دعوتك إلى الإيمان به."], ["وإذا ذُكّروا لا يذكرون", "وإذا وُعظوا لا يتعظون."], ["وإذا رأوا آية يستسخرون", "إذا رأوا حجة تقرر البعث والتوحيد والنبوة يستهزئون."], ["قل نعم وأنتم داخرون", "نعم تُبعثون وأنتم صاغرون أذلاء."], ["فإنما هي زجرة واحدة", "صيحة تزجرهم، وهي نفخة إسرافيل في الصور النفخة الثانية."], ["هذا يوم الدين", "يوم الحساب والجزاء."]], "m": "ما زال السياق في تقرير التوحيد والبعث والجزاء: فاستخبرهم: أأنتم أشد خلقاً أم من خلق الله من الملائكة والسماوات والأرض؟ والجواب معلوم أن خلق غيرهم أشد، فكيف ينكرون البعث بدعوى صعوبته؟ إنا خلقنا أباهم آدم من طين لازب ثم خلقناهم بالتناسل، أفيعجزنا إعادتهم؟ لا. بل عجبتَ من تكذيبهم بالبعث لوضوح أدلته، وهم يسخرون من قولك به، وإذا ذُكّروا بالآيات لا يتذكرون لقسوة قلوبهم وظلمة ذنوبهم، وإذا رأوا آية يستهزئون ويقولون: ما هذا إلا سحر مبين، وهم كاذبون قطعاً للفرق بين السحر الذي هو تخييل باطل وبين الحق الثابت. ويقولون متعجبين: أإذا متنا وكنا تراباً وعظاماً أإنا لمبعوثون؟ قل: نعم تُبعثون وأنتم صاغرون، وما إعادتكم إلا نفخة إسرافيل في الصور، فإذا هم قيام ينظرون، ويقولون: يا ويلنا، يدعون على أنفسهم بالهلاك لشدة ما شاهدوا، هذا يوم الدين؛ اعتراف بالبعث في وقت لا ينفعهم فيه، فيقال لهم: هذا يوم الفصل الذي يفصل الله فيه بين عباده بالعدل، الذي كنتم به تكذبون.", "h": ["بيان أصل خلق الإنسان وهو الطين اللازب أي اللاصق باليد.", "بيان موقفين متضادين: الرسول يعجب من كفر المشركين وتكذيبهم، والمشركون يسخرون من دعوته إياهم إلى الإيمان.", "تقرير البعث وبيان طريقة وقوعه.", "عدم الانتفاع بالإيمان عند معاينة العذاب."], "k": "«وإذا ذُكّروا لا يذكرون»… هل يمرّ بي التذكير فلا يحرّك فيّ شيئاً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 321;
insert into public.tdb_cards(topic, i, body) select 321, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٠", "q": "وَٱلصَّـٰٓفَّـٰتِ صَفّٗا ﴿١﴾ فَٱلزَّـٰجِرَٰتِ زَجۡرٗا ﴿٢﴾ فَٱلتَّـٰلِيَٰتِ ذِكۡرًا ﴿٣﴾ إِنَّ إِلَٰهَكُمۡ لَوَٰحِدٞ ﴿٤﴾ رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَرَبُّ ٱلۡمَشَٰرِقِ ﴿٥﴾ إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِزِينَةٍ ٱلۡكَوَاكِبِ ﴿٦﴾ وَحِفۡظٗا مِّن كُلِّ شَيۡطَٰنٖ مَّارِدٖ ﴿٧﴾ لَّا يَسَّمَّعُونَ إِلَى ٱلۡمَلَإِ ٱلۡأَعۡلَىٰ وَيُقۡذَفُونَ مِن كُلِّ جَانِبٖ ﴿٨﴾ دُحُورٗاۖ وَلَهُمۡ عَذَابٞ وَاصِبٌ ﴿٩﴾ إِلَّا مَنۡ خَطِفَ ٱلۡخَطۡفَةَ فَأَتۡبَعَهُۥ شِهَابٞ ثَاقِبٞ ﴿١٠﴾", "w": [["والصافات صفاً", "الملائكة تصف أنفسها في الصلاة وأجنحتها في الهواء."], ["فالزاجرات زجراً", "الملائكة تزجر السحاب أي تسوقه حيث يأذن الله."], ["فالتاليات ذكراً", "الجماعات التاليات للقرآن."], ["ورب المشارق", "والمغارب، وهي مشارق الشمس ومغاربها، إذ للشمس كل يوم مشرق ومغرب."], ["وحفظاً من كل شيطان مارد", "حفظناها حفظاً من كل شيطان خارج عن الطاعة."], ["لا يسّمّعون إلى الملإ الأعلى", "لا يستمعون إلى الملائكة في السماوات العلا."], ["دحوراً", "يُرمون بالشهب من كل جوانب السماء إبعاداً لهم."], ["عذاب واصب", "دائم لا يفارقهم."], ["إلا من خطف الخطفة", "اختطف الكلمة من الملائكة بسرعة وهرب."], ["فأتبعه شهاب ثاقب", "كوكب مضيء يثقبه أو يحرقه أو يخبله أي يفسده."]], "m": "هذا قسم إلهي يؤكد به تعالى إلهيته على عباده، فأقسم بالصافات والزاجرات والتاليات ذكراً، ولله أن يقسم بما شاء من خلقه، وإنما الممنوع أن يقسم العبد بغير ربه. والقسم جارٍ على عرف البشر في تأكيد الخبر باليمين ليزول الشك. والمقسم عليه: إن إلهكم لواحد، فإله البشرية كلها واحد هو الله خالقها ورازقها، وما عندها من آلهة فباطلة، يكفي في بطلانها أنها أصنام وصور وتماثيل وصلبان لا تسمع ولا تبصر ولا تنفع ولا تضر. ثم دلّل على وحدانيته بأنه رب السماوات والأرض وما بينهما ورب المشارق، فالإله الحق هو الخالق للعوالم المدبر لها، لا الذي ينحته الرجل بيده. ثم ذكر مظاهر قدرته: زيّن السماء الدنيا بالكواكب، وحفظها من كل شيطان متمرد، فلا يتسمّعون إلى الملائكة لينقلوا أخبار الغيب إلى أوليائهم من الكهان، ويُرمَون من كل جهة دحوراً، ولهم عذاب دائم، إلا من اختطف الكلمة بسرعة فأتبعه شهاب ثاقب فقتله أو أحرقه أو أفسده. وبهذا حُميت السماء من استراق السمع.", "h": ["بيان أن الله تعالى يُقسم ببعض مخلوقاته إما تنويهاً بعظمتها المقرِّر ضمناً لعظمة خالقها، وإما بياناً لفضلها، وإما لفتاً لنظر العباد إلى ما فيها من الفوائد.", "تقرير التوحيد وأنه لا إله إلا الله.", "بيان الحكمة من وجود النجوم في السماء الدنيا.", "بيان أن الشياطين حُرموا من استراق السمع."], "k": "«إن إلهكم لواحد»… أقسم الله ليُزيل الشك؛ فهل في قلبي التفات إلى غيره؟"}, {"lbl": "الآيات ١١ – ٢١", "q": "فَٱسۡتَفۡتِهِمۡ أَهُمۡ أَشَدُّ خَلۡقًا أَم مَّنۡ خَلَقۡنَآۚ إِنَّا خَلَقۡنَٰهُم مِّن طِينٖ لَّازِبِۭ ﴿١١﴾ بَلۡ عَجِبۡتَ وَيَسۡخَرُونَ ﴿١٢﴾ وَإِذَا ذُكِّرُواْ لَا يَذۡكُرُونَ ﴿١٣﴾ وَإِذَا رَأَوۡاْ ءَايَةٗ يَسۡتَسۡخِرُونَ ﴿١٤﴾ وَقَالُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٌ ﴿١٥﴾ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ ﴿١٦﴾ أَوَءَابَآؤُنَا ٱلۡأَوَّلُونَ ﴿١٧﴾ قُلۡ نَعَمۡ وَأَنتُمۡ دَٰخِرُونَ ﴿١٨﴾ فَإِنَّمَا هِيَ زَجۡرَةٞ وَٰحِدَةٞ فَإِذَا هُمۡ يَنظُرُونَ ﴿١٩﴾ وَقَالُواْ يَٰوَيۡلَنَا هَٰذَا يَوۡمُ ٱلدِّينِ ﴿٢٠﴾ هَٰذَا يَوۡمُ ٱلۡفَصۡلِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ ﴿٢١﴾", "w": [["فاستفتهم", "استخبر كفار مكة تقريراً وتوبيخاً."], ["أهم أشد خلقاً أم من خلقنا", "خلقهم في ذواتهم وإعادتهم بعد موتهم، أم من خلق تعالى من الملائكة والسماوات والأرض."], ["من طين لازب", "يلصق باليد."], ["بل عجبت ويسخرون", "عجبت يا نبي الله من إنكارهم للبعث، وهم يسخرون من دعوتك إلى الإيمان به."], ["وإذا ذُكّروا لا يذكرون", "وإذا وُعظوا لا يتعظون."], ["وإذا رأوا آية يستسخرون", "إذا رأوا حجة تقرر البعث والتوحيد والنبوة يستهزئون."], ["قل نعم وأنتم داخرون", "نعم تُبعثون وأنتم صاغرون أذلاء."], ["فإنما هي زجرة واحدة", "صيحة تزجرهم، وهي نفخة إسرافيل في الصور النفخة الثانية."], ["هذا يوم الدين", "يوم الحساب والجزاء."]], "m": "ما زال السياق في تقرير التوحيد والبعث والجزاء: فاستخبرهم: أأنتم أشد خلقاً أم من خلق الله من الملائكة والسماوات والأرض؟ والجواب معلوم أن خلق غيرهم أشد، فكيف ينكرون البعث بدعوى صعوبته؟ إنا خلقنا أباهم آدم من طين لازب ثم خلقناهم بالتناسل، أفيعجزنا إعادتهم؟ لا. بل عجبتَ من تكذيبهم بالبعث لوضوح أدلته، وهم يسخرون من قولك به، وإذا ذُكّروا بالآيات لا يتذكرون لقسوة قلوبهم وظلمة ذنوبهم، وإذا رأوا آية يستهزئون ويقولون: ما هذا إلا سحر مبين، وهم كاذبون قطعاً للفرق بين السحر الذي هو تخييل باطل وبين الحق الثابت. ويقولون متعجبين: أإذا متنا وكنا تراباً وعظاماً أإنا لمبعوثون؟ قل: نعم تُبعثون وأنتم صاغرون، وما إعادتكم إلا نفخة إسرافيل في الصور، فإذا هم قيام ينظرون، ويقولون: يا ويلنا، يدعون على أنفسهم بالهلاك لشدة ما شاهدوا، هذا يوم الدين؛ اعتراف بالبعث في وقت لا ينفعهم فيه، فيقال لهم: هذا يوم الفصل الذي يفصل الله فيه بين عباده بالعدل، الذي كنتم به تكذبون.", "h": ["بيان أصل خلق الإنسان وهو الطين اللازب أي اللاصق باليد.", "بيان موقفين متضادين: الرسول يعجب من كفر المشركين وتكذيبهم، والمشركون يسخرون من دعوته إياهم إلى الإيمان.", "تقرير البعث وبيان طريقة وقوعه.", "عدم الانتفاع بالإيمان عند معاينة العذاب."], "k": "«وإذا ذُكّروا لا يذكرون»… هل يمرّ بي التذكير فلا يحرّك فيّ شيئاً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (322, 37, 22, 39, 'سورة الصافات ٢٢ – ٣٩', 'الصافات: وقفوهم إنهم مسؤولون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 322) = $j$[{"lbl": "الآيات ٢٢ – ٣٠", "q": "۞ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ وَمَا كَانُواْ يَعۡبُدُونَ ﴿٢٢﴾ مِن دُونِ ٱللَّهِ فَٱهۡدُوهُمۡ إِلَىٰ صِرَٰطِ ٱلۡجَحِيمِ ﴿٢٣﴾ وَقِفُوهُمۡۖ إِنَّهُم مَّسۡـُٔولُونَ ﴿٢٤﴾ مَا لَكُمۡ لَا تَنَاصَرُونَ ﴿٢٥﴾ بَلۡ هُمُ ٱلۡيَوۡمَ مُسۡتَسۡلِمُونَ ﴿٢٦﴾ وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ ﴿٢٧﴾ قَالُوٓاْ إِنَّكُمۡ كُنتُمۡ تَأۡتُونَنَا عَنِ ٱلۡيَمِينِ ﴿٢٨﴾ قَالُواْ بَل لَّمۡ تَكُونُواْ مُؤۡمِنِينَ ﴿٢٩﴾ وَمَا كَانَ لَنَا عَلَيۡكُم مِّن سُلۡطَٰنِۭۖ بَلۡ كُنتُمۡ قَوۡمٗا طَٰغِينَ ﴿٣٠﴾", "w": [["احشروا الذين ظلموا", "ظلموا أنفسهم بالشرك والمعاصي."], ["وأزواجهم", "قرناءهم من الشياطين."], ["من دون الله", "من غير الله من الأوثان والأصنام."], ["فاهدوهم", "دلّوهم وسوقوهم."], ["إلى صراط الجحيم", "إلى طريق النار."], ["وقفوهم إنهم مسؤولون", "احبسوهم عند الصراط، إنهم مسؤولون عن جميع أقوالهم."], ["ما لكم لا تناصرون", "ما لكم لا ينصر بعضكم بعضاً كما كنتم في الدنيا، توبيخاً."], ["تأتوننا عن اليمين", "عن يمين أحدنا، تزيّنون له الباطل وتأمرونه بالشرك وتنهونه عن التوحيد."], ["وما كان لنا عليكم من سلطان", "من حجة ولا قوة نحملكم بها على الشرك والباطل."], ["بل كنتم قوماً طاغين", "طغاة ظلمة تعبدون غير الله تعالى."]], "m": "ما زال السياق في موقف عرصات القيامة: بعد اعترافهم بأن هذا يوم الدين يقول الجبار عز وجل: احشروا الذين ظلموا بالشرك والمعاصي وقرناءهم من الجن وما كانوا يعبدون من دون الله من الأصنام، فدلّوهم إلى طريق النار، وقفوهم إنهم مسؤولون، ثم يُسألون: ما لكم لا ينصر بعضكم بعضاً كما كنتم في الدنيا؟ بل هم اليوم مستسلمون منقادون أذلاء. وأقبل الأتباع على المتبوعين يتلاومون، كلٌّ يلقي المسؤولية على الآخر، فقال الأتباع من الإنس لقرنائهم: إنكم كنتم تأتوننا عن اليمين والشمال توسوسون لنا وتحسّنون لنا الشرك والشر. فردّ قرناؤهم: بل لم تكونوا مؤمنين فكفّرناكم ولا موحدين فحملناكم على الشرك، وما كان لنا عليكم من حجج أقنعناكم بها ولا قدرة أرهقناكم بها، بل كنتم أنتم قوماً متجاوزين الحد في الظلم والشر.", "h": ["بيان صورة لموقف من مواقف عرصات القيامة.", "بيان أن الأشباه في الكفر أو في الفجور أو في الفسق تُحشر مع بعضها بعضاً.", "عدم جدوى براءة العابدين من المعبودين واحتجاج التابعين على المتبوعين."], "k": "«وقفوهم إنهم مسؤولون»… سأُوقَف وأُسأل؛ فهل أعددتُ لكل قول جواباً؟"}, {"lbl": "الآيات ٣١ – ٣٩", "q": "فَحَقَّ عَلَيۡنَا قَوۡلُ رَبِّنَآۖ إِنَّا لَذَآئِقُونَ ﴿٣١﴾ فَأَغۡوَيۡنَٰكُمۡ إِنَّا كُنَّا غَٰوِينَ ﴿٣٢﴾ فَإِنَّهُمۡ يَوۡمَئِذٖ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ ﴿٣٣﴾ إِنَّا كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ ﴿٣٤﴾ إِنَّهُمۡ كَانُوٓاْ إِذَا قِيلَ لَهُمۡ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسۡتَكۡبِرُونَ ﴿٣٥﴾ وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓاْ ءَالِهَتِنَا لِشَاعِرٖ مَّجۡنُونِۭ ﴿٣٦﴾ بَلۡ جَآءَ بِٱلۡحَقِّ وَصَدَّقَ ٱلۡمُرۡسَلِينَ ﴿٣٧﴾ إِنَّكُمۡ لَذَآئِقُواْ ٱلۡعَذَابِ ٱلۡأَلِيمِ ﴿٣٨﴾ وَمَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ ﴿٣٩﴾", "w": [["فحقّ علينا قول ربنا", "وجب علينا العذاب."], ["إنا لذائقون", "العذاب نحن وأنتم."], ["فأغويناكم إنا كنا غاوين", "أضللناكم إنا كنا ضالين."], ["في العذاب مشتركون", "لأنهم كانوا في الغواية مشتركين."], ["إنا كذلك نفعل بالمجرمين", "كما عذّبنا هؤلاء التابعين والمتبوعين نعذّب التابعين والمتبوعين في كل ضلال وكفر وفساد."], ["لا إله إلا الله يستكبرون", "إذا قيل لهم قولوا لا إله إلا الله ولا تعبدوا إلا الله يستكبرون فلا يقولون ولا يوحّدون."], ["لشاعر مجنون", "يعنون محمداً ﷺ."], ["بل جاء بالحق وصدّق المرسلين", "جاء بلا إله إلا الله وهو الحق الذي جاءت به الرسل، وصدّقهم فيما جاؤوا به من التوحيد."]], "m": "ما زال السياق في تساؤلات الظالمين: قال المتبوعون لأتباعهم: بسبب غوايتنا وضلالنا وجب علينا العذاب، إنا وأنتم لذائقوه لا محالة، وقالوا معترفين: فأغويناكم إنا كنا غاوين؛ وهذا قول الجن للإنس. قال تعالى: فإنهم يومئذ في العذاب مشتركون لاشتراكهم في الشرك والشر والفساد، إنا كذلك نفعل بالمجرمين من سائر الأصناف كالزناة وأكلة الربا وسافكي الدماء، فنعذّب الصنف مع صنفه. إنهم كانوا في الدنيا إذا قال لهم رسول الله أو المؤمنون: قولوا لا إله إلا الله، يستكبرون ولا يقولونها، بل يقولون: أإنا لتاركو آلهتنا لشاعر مجنون؟ يصفون القرآن بالشعر ومحمداً تاليه بالشاعر، ولِما يدعوهم إليه من الإيمان بالبعث والجزاء بالجنون. فردّ تعالى عليهم: بل جاء بالحق فأنكرتموه تقليداً وعناداً، وهو لا إله إلا الله، وصدّق المرسلين الذين جاؤوا قبله بها.", "h": ["بيان هلاك الضالّ ومن أضلّه.", "ردّ الله تعالى ما وجّهه المشركون لرسول الله ﷺ من التهم الباطلة.", "التعظيم من شأن لا إله إلا الله، وأنها دعوة كل الرسل الذين سبقوا النبي محمداً ﷺ.", "تقرير التوحيد والبعث والجزاء والنبوة المحمدية."], "k": "«إذا قيل لهم لا إله إلا الله يستكبرون»… هل أقولها بلساني وفي قلبي كِبر عن بعض ما تقتضيه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 322;
insert into public.tdb_cards(topic, i, body) select 322, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٢ – ٣٠", "q": "۞ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ وَمَا كَانُواْ يَعۡبُدُونَ ﴿٢٢﴾ مِن دُونِ ٱللَّهِ فَٱهۡدُوهُمۡ إِلَىٰ صِرَٰطِ ٱلۡجَحِيمِ ﴿٢٣﴾ وَقِفُوهُمۡۖ إِنَّهُم مَّسۡـُٔولُونَ ﴿٢٤﴾ مَا لَكُمۡ لَا تَنَاصَرُونَ ﴿٢٥﴾ بَلۡ هُمُ ٱلۡيَوۡمَ مُسۡتَسۡلِمُونَ ﴿٢٦﴾ وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ ﴿٢٧﴾ قَالُوٓاْ إِنَّكُمۡ كُنتُمۡ تَأۡتُونَنَا عَنِ ٱلۡيَمِينِ ﴿٢٨﴾ قَالُواْ بَل لَّمۡ تَكُونُواْ مُؤۡمِنِينَ ﴿٢٩﴾ وَمَا كَانَ لَنَا عَلَيۡكُم مِّن سُلۡطَٰنِۭۖ بَلۡ كُنتُمۡ قَوۡمٗا طَٰغِينَ ﴿٣٠﴾", "w": [["احشروا الذين ظلموا", "ظلموا أنفسهم بالشرك والمعاصي."], ["وأزواجهم", "قرناءهم من الشياطين."], ["من دون الله", "من غير الله من الأوثان والأصنام."], ["فاهدوهم", "دلّوهم وسوقوهم."], ["إلى صراط الجحيم", "إلى طريق النار."], ["وقفوهم إنهم مسؤولون", "احبسوهم عند الصراط، إنهم مسؤولون عن جميع أقوالهم."], ["ما لكم لا تناصرون", "ما لكم لا ينصر بعضكم بعضاً كما كنتم في الدنيا، توبيخاً."], ["تأتوننا عن اليمين", "عن يمين أحدنا، تزيّنون له الباطل وتأمرونه بالشرك وتنهونه عن التوحيد."], ["وما كان لنا عليكم من سلطان", "من حجة ولا قوة نحملكم بها على الشرك والباطل."], ["بل كنتم قوماً طاغين", "طغاة ظلمة تعبدون غير الله تعالى."]], "m": "ما زال السياق في موقف عرصات القيامة: بعد اعترافهم بأن هذا يوم الدين يقول الجبار عز وجل: احشروا الذين ظلموا بالشرك والمعاصي وقرناءهم من الجن وما كانوا يعبدون من دون الله من الأصنام، فدلّوهم إلى طريق النار، وقفوهم إنهم مسؤولون، ثم يُسألون: ما لكم لا ينصر بعضكم بعضاً كما كنتم في الدنيا؟ بل هم اليوم مستسلمون منقادون أذلاء. وأقبل الأتباع على المتبوعين يتلاومون، كلٌّ يلقي المسؤولية على الآخر، فقال الأتباع من الإنس لقرنائهم: إنكم كنتم تأتوننا عن اليمين والشمال توسوسون لنا وتحسّنون لنا الشرك والشر. فردّ قرناؤهم: بل لم تكونوا مؤمنين فكفّرناكم ولا موحدين فحملناكم على الشرك، وما كان لنا عليكم من حجج أقنعناكم بها ولا قدرة أرهقناكم بها، بل كنتم أنتم قوماً متجاوزين الحد في الظلم والشر.", "h": ["بيان صورة لموقف من مواقف عرصات القيامة.", "بيان أن الأشباه في الكفر أو في الفجور أو في الفسق تُحشر مع بعضها بعضاً.", "عدم جدوى براءة العابدين من المعبودين واحتجاج التابعين على المتبوعين."], "k": "«وقفوهم إنهم مسؤولون»… سأُوقَف وأُسأل؛ فهل أعددتُ لكل قول جواباً؟"}, {"lbl": "الآيات ٣١ – ٣٩", "q": "فَحَقَّ عَلَيۡنَا قَوۡلُ رَبِّنَآۖ إِنَّا لَذَآئِقُونَ ﴿٣١﴾ فَأَغۡوَيۡنَٰكُمۡ إِنَّا كُنَّا غَٰوِينَ ﴿٣٢﴾ فَإِنَّهُمۡ يَوۡمَئِذٖ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ ﴿٣٣﴾ إِنَّا كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ ﴿٣٤﴾ إِنَّهُمۡ كَانُوٓاْ إِذَا قِيلَ لَهُمۡ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسۡتَكۡبِرُونَ ﴿٣٥﴾ وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓاْ ءَالِهَتِنَا لِشَاعِرٖ مَّجۡنُونِۭ ﴿٣٦﴾ بَلۡ جَآءَ بِٱلۡحَقِّ وَصَدَّقَ ٱلۡمُرۡسَلِينَ ﴿٣٧﴾ إِنَّكُمۡ لَذَآئِقُواْ ٱلۡعَذَابِ ٱلۡأَلِيمِ ﴿٣٨﴾ وَمَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ ﴿٣٩﴾", "w": [["فحقّ علينا قول ربنا", "وجب علينا العذاب."], ["إنا لذائقون", "العذاب نحن وأنتم."], ["فأغويناكم إنا كنا غاوين", "أضللناكم إنا كنا ضالين."], ["في العذاب مشتركون", "لأنهم كانوا في الغواية مشتركين."], ["إنا كذلك نفعل بالمجرمين", "كما عذّبنا هؤلاء التابعين والمتبوعين نعذّب التابعين والمتبوعين في كل ضلال وكفر وفساد."], ["لا إله إلا الله يستكبرون", "إذا قيل لهم قولوا لا إله إلا الله ولا تعبدوا إلا الله يستكبرون فلا يقولون ولا يوحّدون."], ["لشاعر مجنون", "يعنون محمداً ﷺ."], ["بل جاء بالحق وصدّق المرسلين", "جاء بلا إله إلا الله وهو الحق الذي جاءت به الرسل، وصدّقهم فيما جاؤوا به من التوحيد."]], "m": "ما زال السياق في تساؤلات الظالمين: قال المتبوعون لأتباعهم: بسبب غوايتنا وضلالنا وجب علينا العذاب، إنا وأنتم لذائقوه لا محالة، وقالوا معترفين: فأغويناكم إنا كنا غاوين؛ وهذا قول الجن للإنس. قال تعالى: فإنهم يومئذ في العذاب مشتركون لاشتراكهم في الشرك والشر والفساد، إنا كذلك نفعل بالمجرمين من سائر الأصناف كالزناة وأكلة الربا وسافكي الدماء، فنعذّب الصنف مع صنفه. إنهم كانوا في الدنيا إذا قال لهم رسول الله أو المؤمنون: قولوا لا إله إلا الله، يستكبرون ولا يقولونها، بل يقولون: أإنا لتاركو آلهتنا لشاعر مجنون؟ يصفون القرآن بالشعر ومحمداً تاليه بالشاعر، ولِما يدعوهم إليه من الإيمان بالبعث والجزاء بالجنون. فردّ تعالى عليهم: بل جاء بالحق فأنكرتموه تقليداً وعناداً، وهو لا إله إلا الله، وصدّق المرسلين الذين جاؤوا قبله بها.", "h": ["بيان هلاك الضالّ ومن أضلّه.", "ردّ الله تعالى ما وجّهه المشركون لرسول الله ﷺ من التهم الباطلة.", "التعظيم من شأن لا إله إلا الله، وأنها دعوة كل الرسل الذين سبقوا النبي محمداً ﷺ.", "تقرير التوحيد والبعث والجزاء والنبوة المحمدية."], "k": "«إذا قيل لهم لا إله إلا الله يستكبرون»… هل أقولها بلساني وفي قلبي كِبر عن بعض ما تقتضيه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (323, 37, 40, 61, 'سورة الصافات ٤٠ – ٦١', 'الصافات: لمثل هذا فليعمل العاملون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 323) = $j$[{"lbl": "الآيات ٤٠ – ٤٩", "q": "إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ ﴿٤٠﴾ أُوْلَـٰٓئِكَ لَهُمۡ رِزۡقٞ مَّعۡلُومٞ ﴿٤١﴾ فَوَٰكِهُ وَهُم مُّكۡرَمُونَ ﴿٤٢﴾ فِي جَنَّـٰتِ ٱلنَّعِيمِ ﴿٤٣﴾ عَلَىٰ سُرُرٖ مُّتَقَٰبِلِينَ ﴿٤٤﴾ يُطَافُ عَلَيۡهِم بِكَأۡسٖ مِّن مَّعِينِۭ ﴿٤٥﴾ بَيۡضَآءَ لَذَّةٖ لِّلشَّـٰرِبِينَ ﴿٤٦﴾ لَا فِيهَا غَوۡلٞ وَلَا هُمۡ عَنۡهَا يُنزَفُونَ ﴿٤٧﴾ وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ عِينٞ ﴿٤٨﴾ كَأَنَّهُنَّ بَيۡضٞ مَّكۡنُونٞ ﴿٤٩﴾", "w": [["وما تُجزون إلا ما كنتم تعملون", "إلا جزاء ما كنتم تعملونه من الشرك والمعاصي."], ["إلا عباد الله المخلَصين", "لكن عباد الله الذين أخلصوا العبادة له وحده يُجزون بأكثر من أعمالهم، إذ الحسنة بعشر أمثالها وأكثر."], ["لهم رزق معلوم", "في الجنة بكرة وعشياً."], ["فواكه", "طعامهم وشرابهم فيها للتلذذ به كما يُتلذذ بالفواكه، لا لحفظ أجسامهم كما في الدنيا."], ["وهم مكرمون", "لا تلحقهم فيها إهانة، بخلاف أهل النار."], ["من معين", "من خمر تجري على وجه الأرض كعيون الماء الجارية."], ["لذة للشاربين", "موصوفة بأنها لذة للشاربين."], ["لا فيها غول", "ما يغتال عقولهم وأجسامهم فيهلكهم."], ["ولا هم عنها يُنزَفون", "لا يسكرون بسببها كما هي خمر الدنيا."], ["قاصرات الطرف", "لا ينظرن إلى غير أزواجهن لحسنهم وجمالهم عندهن."], ["عِين", "واسعات الأعين، الواحدة عيناء."], ["بيض مكنون", "مستور لا يصله غبار ولا غيره."]], "m": "يقال لأهل النار وهم موقوفون: إنكم لذائقو العذاب الأليم، وما تُجزون إلا بما كنتم تعملون؛ فلا يُظلمون، بل هو جزاء عادل: السيئة بمثلها. ثم استثنى تعالى عباده المؤمنين الذين استخلصهم لعبادته فإنهم يُجزون بأكثر من أعمالهم فضلاً منه، فالحسنة بعشر أمثالها إلى سبعمائة وأكثر، أولئك لهم رزق معلوم يأكلونه بكرة وعشياً، وقوله «فواكه» إشارة إلى أنهم يأكلون ويشربون تلذذاً لا لدفع الجوع كما في الدنيا، وهم مكرمون لا تلحقهم إهانة، في جنات النعيم، على سرر متقابلين ينظر بعضهم إلى بعض، يطوف عليهم خدم بكأس من خمر تجري بها الأنهار كعيون الماء، بيضاء لذة للشاربين، لا فيها غول كالصداع ووجع البطن، ولا هم عنها يسكرون فتذهب بعقولهم. وعندهم زوجات قاصرات الطرف على أزواجهن لا تنظر الواحدة إلا إلى زوجها، واسعات الأعين، كأنهن بيض النعام في بياضه المشرب بصفرة، مستور لا يناله غبار ولا أذى.", "h": ["بيان عدالة الحق تبارك وتعالى في أنه يجزي السيئة بمثلها، ولا يؤاخذ أحداً بغير كسبه في الحياة الدنيا.", "بيان فضل الله تعالى إذ يجزي المؤمنين الحسنة بعشر أمثالها إلى أكثر من سبعمائة.", "تقرير البعث وبيان بعض ما يجري فيه من قول وعمل.", "وصف نعيم أهل الجنة طعاماً وشراباً وجلوساً واستمتاعاً."], "k": "«إلا عباد الله المخلَصين»… الإخلاص هو الفارق بين الفريقين؛ فلمن أعمل؟"}, {"lbl": "الآيات ٥٠ – ٦١", "q": "فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ ﴿٥٠﴾ قَالَ قَآئِلٞ مِّنۡهُمۡ إِنِّي كَانَ لِي قَرِينٞ ﴿٥١﴾ يَقُولُ أَءِنَّكَ لَمِنَ ٱلۡمُصَدِّقِينَ ﴿٥٢﴾ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ ﴿٥٣﴾ قَالَ هَلۡ أَنتُم مُّطَّلِعُونَ ﴿٥٤﴾ فَٱطَّلَعَ فَرَءَاهُ فِي سَوَآءِ ٱلۡجَحِيمِ ﴿٥٥﴾ قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرۡدِينِ ﴿٥٦﴾ وَلَوۡلَا نِعۡمَةُ رَبِّي لَكُنتُ مِنَ ٱلۡمُحۡضَرِينَ ﴿٥٧﴾ أَفَمَا نَحۡنُ بِمَيِّتِينَ ﴿٥٨﴾ إِلَّا مَوۡتَتَنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُعَذَّبِينَ ﴿٥٩﴾ إِنَّ هَٰذَا لَهُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٦٠﴾ لِمِثۡلِ هَٰذَا فَلۡيَعۡمَلِ ٱلۡعَٰمِلُونَ ﴿٦١﴾", "w": [["فأقبل بعضهم على بعض", "أقبل أهل الجنة."], ["يتساءلون", "عما مرّ بهم في الدنيا وما جرى لهم فيها."], ["إني كان لي قرين", "صاحب ينكر البعث."], ["أإنك لمن المصدّقين", "يقول تبكيتاً لي وتوبيخاً: أتصدّق بالبعث والجزاء؟"], ["أإنا لمدينون", "محاسَبون ومَجزيّون بأعمالنا، إنكاراً وتكذيباً."], ["هل أنتم مطّلعون", "معي إلى النار لننظر حاله."], ["في سواء الجحيم", "في وسط النار."], ["إن كدتَ لتُردين", "لتهلكني."], ["لكنت من المحضَرين", "المسوقين إلى جهنم المحضَرين فيها."], ["أفما نحن بميتين", "أمخلَّدون فما نحن بميتين؟ والاستفهام للتقرير أي نعم."], ["إلا موتتنا الأولى", "التي ماتوها في الدنيا."], ["لمثل هذا فليعمل العاملون", "لمثل هذا النعيم فليعمل العاملون بكثرة الصالحات واجتناب السيئات."]], "m": "ما زال السياق في نعيم أهل الجنة: جلسوا على السرر متقابلين يتجاذبون الحديث متذكرين ما مرّ بهم في الدنيا، فقال أحدهم: إني كان لي في الدنيا صاحب يقول لي استهزاءً وإنكاراً: أإنك لمن المصدّقين بالبعث؟ أإذا متنا وكنا تراباً وعظاماً أإنا لمحاسَبون؟ ثم قال لأهل مجلسه: هل أنتم مطّلعون معي على أهل النار لنرى صاحبي؟ فاطّلع فرآه في وسط الجحيم، فقال: والله إن كدتَ لتهلكني لما كنت تنكر عليّ الإيمان بالبعث وتسخر مني، ولولا نعمة ربي عليّ بالعصمة والحفظ لكنت من المحضَرين معك في العذاب. ثم قال مقرِّراً: أفما نحن بميتين إلا موتتنا الأولى وما نحن بمعذَّبين؟ أي نعم مخلَّدون، نحن في الجنة وأنتم في النار. إن هذا لهو الفوز العظيم، إذ كان نجاة من النار ودخولاً للجنة دار النعيم المقيم. قال تعالى: لمثل هذا فليعمل العاملون، أي فليواصلوا عملهم وليخلصوا فيه لله.", "h": ["بيان عظمة الله تعالى في إقدار المؤمن على أن يتكلم مع من هو في وسط الجحيم، ويرى صورته ويتخاطب معه ويفهم بعضهم بعضاً.", "التحذير من قرناء السوء كالشباب الملحد وغيره.", "بيان كيف كان المكذبون يسخرون من المؤمنين ويعدّونهم متخلفين عقلياً.", "لا موت في الآخرة، وإنما حياة أبدية في النعيم أو في الجحيم.", "الحث على كثرة الأعمال الصالحة، والبعد عن الأعمال الفاسدة."], "k": "«ولولا نعمة ربي لكنت من المحضَرين»… كم صاحبٍ كاد يُرديني لولا أن حفظني الله؟ فمن أصاحب اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 323;
insert into public.tdb_cards(topic, i, body) select 323, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٠ – ٤٩", "q": "إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ ﴿٤٠﴾ أُوْلَـٰٓئِكَ لَهُمۡ رِزۡقٞ مَّعۡلُومٞ ﴿٤١﴾ فَوَٰكِهُ وَهُم مُّكۡرَمُونَ ﴿٤٢﴾ فِي جَنَّـٰتِ ٱلنَّعِيمِ ﴿٤٣﴾ عَلَىٰ سُرُرٖ مُّتَقَٰبِلِينَ ﴿٤٤﴾ يُطَافُ عَلَيۡهِم بِكَأۡسٖ مِّن مَّعِينِۭ ﴿٤٥﴾ بَيۡضَآءَ لَذَّةٖ لِّلشَّـٰرِبِينَ ﴿٤٦﴾ لَا فِيهَا غَوۡلٞ وَلَا هُمۡ عَنۡهَا يُنزَفُونَ ﴿٤٧﴾ وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ عِينٞ ﴿٤٨﴾ كَأَنَّهُنَّ بَيۡضٞ مَّكۡنُونٞ ﴿٤٩﴾", "w": [["وما تُجزون إلا ما كنتم تعملون", "إلا جزاء ما كنتم تعملونه من الشرك والمعاصي."], ["إلا عباد الله المخلَصين", "لكن عباد الله الذين أخلصوا العبادة له وحده يُجزون بأكثر من أعمالهم، إذ الحسنة بعشر أمثالها وأكثر."], ["لهم رزق معلوم", "في الجنة بكرة وعشياً."], ["فواكه", "طعامهم وشرابهم فيها للتلذذ به كما يُتلذذ بالفواكه، لا لحفظ أجسامهم كما في الدنيا."], ["وهم مكرمون", "لا تلحقهم فيها إهانة، بخلاف أهل النار."], ["من معين", "من خمر تجري على وجه الأرض كعيون الماء الجارية."], ["لذة للشاربين", "موصوفة بأنها لذة للشاربين."], ["لا فيها غول", "ما يغتال عقولهم وأجسامهم فيهلكهم."], ["ولا هم عنها يُنزَفون", "لا يسكرون بسببها كما هي خمر الدنيا."], ["قاصرات الطرف", "لا ينظرن إلى غير أزواجهن لحسنهم وجمالهم عندهن."], ["عِين", "واسعات الأعين، الواحدة عيناء."], ["بيض مكنون", "مستور لا يصله غبار ولا غيره."]], "m": "يقال لأهل النار وهم موقوفون: إنكم لذائقو العذاب الأليم، وما تُجزون إلا بما كنتم تعملون؛ فلا يُظلمون، بل هو جزاء عادل: السيئة بمثلها. ثم استثنى تعالى عباده المؤمنين الذين استخلصهم لعبادته فإنهم يُجزون بأكثر من أعمالهم فضلاً منه، فالحسنة بعشر أمثالها إلى سبعمائة وأكثر، أولئك لهم رزق معلوم يأكلونه بكرة وعشياً، وقوله «فواكه» إشارة إلى أنهم يأكلون ويشربون تلذذاً لا لدفع الجوع كما في الدنيا، وهم مكرمون لا تلحقهم إهانة، في جنات النعيم، على سرر متقابلين ينظر بعضهم إلى بعض، يطوف عليهم خدم بكأس من خمر تجري بها الأنهار كعيون الماء، بيضاء لذة للشاربين، لا فيها غول كالصداع ووجع البطن، ولا هم عنها يسكرون فتذهب بعقولهم. وعندهم زوجات قاصرات الطرف على أزواجهن لا تنظر الواحدة إلا إلى زوجها، واسعات الأعين، كأنهن بيض النعام في بياضه المشرب بصفرة، مستور لا يناله غبار ولا أذى.", "h": ["بيان عدالة الحق تبارك وتعالى في أنه يجزي السيئة بمثلها، ولا يؤاخذ أحداً بغير كسبه في الحياة الدنيا.", "بيان فضل الله تعالى إذ يجزي المؤمنين الحسنة بعشر أمثالها إلى أكثر من سبعمائة.", "تقرير البعث وبيان بعض ما يجري فيه من قول وعمل.", "وصف نعيم أهل الجنة طعاماً وشراباً وجلوساً واستمتاعاً."], "k": "«إلا عباد الله المخلَصين»… الإخلاص هو الفارق بين الفريقين؛ فلمن أعمل؟"}, {"lbl": "الآيات ٥٠ – ٦١", "q": "فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ ﴿٥٠﴾ قَالَ قَآئِلٞ مِّنۡهُمۡ إِنِّي كَانَ لِي قَرِينٞ ﴿٥١﴾ يَقُولُ أَءِنَّكَ لَمِنَ ٱلۡمُصَدِّقِينَ ﴿٥٢﴾ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ ﴿٥٣﴾ قَالَ هَلۡ أَنتُم مُّطَّلِعُونَ ﴿٥٤﴾ فَٱطَّلَعَ فَرَءَاهُ فِي سَوَآءِ ٱلۡجَحِيمِ ﴿٥٥﴾ قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرۡدِينِ ﴿٥٦﴾ وَلَوۡلَا نِعۡمَةُ رَبِّي لَكُنتُ مِنَ ٱلۡمُحۡضَرِينَ ﴿٥٧﴾ أَفَمَا نَحۡنُ بِمَيِّتِينَ ﴿٥٨﴾ إِلَّا مَوۡتَتَنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُعَذَّبِينَ ﴿٥٩﴾ إِنَّ هَٰذَا لَهُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٦٠﴾ لِمِثۡلِ هَٰذَا فَلۡيَعۡمَلِ ٱلۡعَٰمِلُونَ ﴿٦١﴾", "w": [["فأقبل بعضهم على بعض", "أقبل أهل الجنة."], ["يتساءلون", "عما مرّ بهم في الدنيا وما جرى لهم فيها."], ["إني كان لي قرين", "صاحب ينكر البعث."], ["أإنك لمن المصدّقين", "يقول تبكيتاً لي وتوبيخاً: أتصدّق بالبعث والجزاء؟"], ["أإنا لمدينون", "محاسَبون ومَجزيّون بأعمالنا، إنكاراً وتكذيباً."], ["هل أنتم مطّلعون", "معي إلى النار لننظر حاله."], ["في سواء الجحيم", "في وسط النار."], ["إن كدتَ لتُردين", "لتهلكني."], ["لكنت من المحضَرين", "المسوقين إلى جهنم المحضَرين فيها."], ["أفما نحن بميتين", "أمخلَّدون فما نحن بميتين؟ والاستفهام للتقرير أي نعم."], ["إلا موتتنا الأولى", "التي ماتوها في الدنيا."], ["لمثل هذا فليعمل العاملون", "لمثل هذا النعيم فليعمل العاملون بكثرة الصالحات واجتناب السيئات."]], "m": "ما زال السياق في نعيم أهل الجنة: جلسوا على السرر متقابلين يتجاذبون الحديث متذكرين ما مرّ بهم في الدنيا، فقال أحدهم: إني كان لي في الدنيا صاحب يقول لي استهزاءً وإنكاراً: أإنك لمن المصدّقين بالبعث؟ أإذا متنا وكنا تراباً وعظاماً أإنا لمحاسَبون؟ ثم قال لأهل مجلسه: هل أنتم مطّلعون معي على أهل النار لنرى صاحبي؟ فاطّلع فرآه في وسط الجحيم، فقال: والله إن كدتَ لتهلكني لما كنت تنكر عليّ الإيمان بالبعث وتسخر مني، ولولا نعمة ربي عليّ بالعصمة والحفظ لكنت من المحضَرين معك في العذاب. ثم قال مقرِّراً: أفما نحن بميتين إلا موتتنا الأولى وما نحن بمعذَّبين؟ أي نعم مخلَّدون، نحن في الجنة وأنتم في النار. إن هذا لهو الفوز العظيم، إذ كان نجاة من النار ودخولاً للجنة دار النعيم المقيم. قال تعالى: لمثل هذا فليعمل العاملون، أي فليواصلوا عملهم وليخلصوا فيه لله.", "h": ["بيان عظمة الله تعالى في إقدار المؤمن على أن يتكلم مع من هو في وسط الجحيم، ويرى صورته ويتخاطب معه ويفهم بعضهم بعضاً.", "التحذير من قرناء السوء كالشباب الملحد وغيره.", "بيان كيف كان المكذبون يسخرون من المؤمنين ويعدّونهم متخلفين عقلياً.", "لا موت في الآخرة، وإنما حياة أبدية في النعيم أو في الجحيم.", "الحث على كثرة الأعمال الصالحة، والبعد عن الأعمال الفاسدة."], "k": "«ولولا نعمة ربي لكنت من المحضَرين»… كم صاحبٍ كاد يُرديني لولا أن حفظني الله؟ فمن أصاحب اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (324, 37, 62, 82, 'سورة الصافات ٦٢ – ٨٢', 'الصافات: شجرة الزقوم ونجاة نوح', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 324) = $j$[{"lbl": "الآيات ٦٢ – ٧٤", "q": "أَذَٰلِكَ خَيۡرٞ نُّزُلًا أَمۡ شَجَرَةُ ٱلزَّقُّومِ ﴿٦٢﴾ إِنَّا جَعَلۡنَٰهَا فِتۡنَةٗ لِّلظَّـٰلِمِينَ ﴿٦٣﴾ إِنَّهَا شَجَرَةٞ تَخۡرُجُ فِيٓ أَصۡلِ ٱلۡجَحِيمِ ﴿٦٤﴾ طَلۡعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ ﴿٦٥﴾ فَإِنَّهُمۡ لَأٓكِلُونَ مِنۡهَا فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ ﴿٦٦﴾ ثُمَّ إِنَّ لَهُمۡ عَلَيۡهَا لَشَوۡبٗا مِّنۡ حَمِيمٖ ﴿٦٧﴾ ثُمَّ إِنَّ مَرۡجِعَهُمۡ لَإِلَى ٱلۡجَحِيمِ ﴿٦٨﴾ إِنَّهُمۡ أَلۡفَوۡاْ ءَابَآءَهُمۡ ضَآلِّينَ ﴿٦٩﴾ فَهُمۡ عَلَىٰٓ ءَاثَٰرِهِمۡ يُهۡرَعُونَ ﴿٧٠﴾ وَلَقَدۡ ضَلَّ قَبۡلَهُمۡ أَكۡثَرُ ٱلۡأَوَّلِينَ ﴿٧١﴾ وَلَقَدۡ أَرۡسَلۡنَا فِيهِم مُّنذِرِينَ ﴿٧٢﴾ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ ﴿٧٣﴾ إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ ﴿٧٤﴾", "w": [["أذلك خير نزلاً", "ذلك المذكور لأهل الجنة خير نُزُلاً، وهو ما يُعدّ للنازل من قِرى."], ["أم شجرة الزقوم", "المُعدّة لأهل النار، وهي من أخبث الشجر طعماً ومرارة."], ["إنا جعلناها فتنة للظالمين", "امتحاناً واختباراً لهم في الدنيا وعذاباً لهم في الآخرة."], ["تخرج في أصل الجحيم", "في قعر الجحيم وأغصانها في دركاتها."], ["طلعها كأنه رؤوس الشياطين", "ما يطلع من ثمرها أولاً كالحيّات القبيحة المنظر."], ["لشوباً من حميم", "بعد أكلها يُسقون ماءً حميماً، فذلك الشوب أي الخلط."], ["إنهم ألفَوا آباءهم", "وجدوا آباءهم."], ["فهم على آثارهم يُهرعون", "يسرعون مندفعين إلى اتباعهم بدون فكر ولا رويّة."], ["ولقد أرسلنا فيهم منذرين", "رسلاً منذرين لهم من العذاب."], ["فانظر كيف كان عاقبة المنذَرين", "كانت عذاباً أليماً لإصرارهم على الكفر."], ["إلا عباد الله المخلَصين", "فإنهم نجوا من العذاب ولم يهلكوا."]], "m": "لما ذكر تعالى ما أعدّه لأهل الإيمان من النعيم المقيم قال: أذلك خير نزلاً، والنزل ما يُعدّ من قِرى للضيف، أم شجرة الزقوم؟ أي ثمرها، وهو ثمر سمج مرّ قبيح المنظر. ثم أخبر أنه جعلها فتنة للظالمين من كفار قريش، إذ قالوا لما سمعوا بها: كيف تنبت الشجرة في النار والنار تحرق الشجر؟ فكذّبوا بها فكانت فتنة لهم. ثم وصفها بأنها تخرج في قعر الجحيم وتمتد فروعها في دركات النار، طلعها في قبح منظره كأنه رؤوس الشياطين، لأن العرب تضرب المثل بالشيطان في القبح. فإنهم لآكلون منها لشدة جوعهم فمالئون منها بطونهم، ثم إنهم لما يأكلون يعطشون فيُسقون من حميم يُخلط به ما أكلوا، ثم إن مردّهم بعد ذلك إلى الجحيم. إنهم وجدوا آباءهم ضالين عن الهدى، فهم يهرولون وراءهم يتبعونهم في الشرك والضلال، وليس هؤلاء أول من ضل، فقد ضل قبلهم أكثر الأولين، ولقد أرسلنا فيهم رسلاً ينذرونهم فلم يؤمنوا فأهلكناهم، فانظر كيف كانت عاقبتهم هلاكاً ودماراً، إلا عباد الله الذين استخلصهم لعبادته فآمنوا وأطاعوا فنجّاهم. وفي الآية تهديد ووعيد لكفار قريش بما لا مزيد عليه.", "h": ["بيان أحسن الأساليب في الدعوة، وهو الترهيب والترغيب.", "تقرير البعث والجزاء بأسلوب العرض للأحداث التي تتم في القيامة.", "التنديد بالاتباع في الضلال للآباء والأجداد وأهل البلاد.", "إهلاك الله تعالى للظالمين وإنجاؤه للمؤمنين عند الأخذ بالذنوب في الدنيا والآخرة."], "k": "«فهم على آثارهم يُهرعون»… كم عادةٍ أتبعها لأني وجدت الناس عليها، دون أن أسأل: أهي حق؟"}, {"lbl": "الآيات ٧٥ – ٨٢", "q": "وَلَقَدۡ نَادَىٰنَا نُوحٞ فَلَنِعۡمَ ٱلۡمُجِيبُونَ ﴿٧٥﴾ وَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ ﴿٧٦﴾ وَجَعَلۡنَا ذُرِّيَّتَهُۥ هُمُ ٱلۡبَاقِينَ ﴿٧٧﴾ وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ ﴿٧٨﴾ سَلَٰمٌ عَلَىٰ نُوحٖ فِي ٱلۡعَٰلَمِينَ ﴿٧٩﴾ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿٨٠﴾ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ﴿٨١﴾ ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ ﴿٨٢﴾", "w": [["ولقد نادانا نوح", "قال: إني مغلوب فانتصر."], ["فلنعم المجيبون", "له، إذ نجّيناه وأهلكنا الكافرين."], ["وجعلنا ذريته هم الباقين", "إذ عامة الناس كانوا من ذريته: سام وحام ويافث."], ["وتركنا عليه في الآخرين", "أبقينا عليه ثناءً حسناً عند سائر الأمم والشعوب."], ["سلام على نوح في العالمين", "سلام منا على نوح في العالمين."], ["إنا كذلك نجزي المحسنين", "كما جزينا نوحاً بالذكر الحسن نجزي المحسنين."], ["ثم أغرقنا الآخرين", "كفار قومه المشركين بعد إنجائه والمؤمنين."]], "m": "على إثر ذكره تعالى إهلاك المنذَرين وإنجاء المؤمنين ذكر مثالاً لذلك: نوح وقومه، أنذرهم فلما جاء العذاب نادى ربه فقال: رب انصرني بما كذّبون، وقال: إني مغلوب فانتصر، فلنعم المجيبون نحن له، ونجّيناه وأهله إلا امرأته وولده كنعان، من الكرب العظيم وهو عذاب الغرق. وجعلنا ذريته هم الباقين إلى يوم القيامة جزاءً على دعوته وإخلاصه وصدقه، إذ كل الناس اليوم من أولاده الثلاثة: سام أبو العرب والروم وفارس، وحام أبو السودان، ويافث أبو الترك والخزر ويأجوج ومأجوج. وتركنا عليه في أجيال البشرية التي أتت بعده الذكر الحسن: سلام على نوح في العالمين. إنا كذلك نجزي المحسنين، فلإيمانه وصبره وتقواه وصدقه ونصحه وإخلاصه جزيناه، وفي هذا بشرى للمؤمنين ودعوة إلى الإيمان بالترغيب فيه، إنه من عبادنا المؤمنين. ثم أغرقنا الآخرين من قومه لكفرهم وشركهم وتكذيبهم بعد أن أنجينا المؤمنين.", "h": ["بيان إكرام الله لأوليائه، وإهانته لأعدائه.", "إجابة دعاء الصالحين لا سيما عندما يُظلمون.", "فضل الإحسان وحسن عاقبة أهله.", "فضل الإيمان وكرامة أهله عند الله في الدنيا والآخرة.", "قول «سلام على نوح في العالمين» إذا قاله المؤمن حين يمسي أو يصبح يحفظه الله تعالى من لسعة العقرب، وأصحّ منه قول: «أعوذ بكلمات الله التامات من شر ما خلق» لصحة الحديث فيه."], "k": "«إنه من عبادنا المؤمنين»… بقي ذكر نوح في العالمين لصدقه؛ فما الذي سيبقى من ذكري؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 324;
insert into public.tdb_cards(topic, i, body) select 324, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٢ – ٧٤", "q": "أَذَٰلِكَ خَيۡرٞ نُّزُلًا أَمۡ شَجَرَةُ ٱلزَّقُّومِ ﴿٦٢﴾ إِنَّا جَعَلۡنَٰهَا فِتۡنَةٗ لِّلظَّـٰلِمِينَ ﴿٦٣﴾ إِنَّهَا شَجَرَةٞ تَخۡرُجُ فِيٓ أَصۡلِ ٱلۡجَحِيمِ ﴿٦٤﴾ طَلۡعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ ﴿٦٥﴾ فَإِنَّهُمۡ لَأٓكِلُونَ مِنۡهَا فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ ﴿٦٦﴾ ثُمَّ إِنَّ لَهُمۡ عَلَيۡهَا لَشَوۡبٗا مِّنۡ حَمِيمٖ ﴿٦٧﴾ ثُمَّ إِنَّ مَرۡجِعَهُمۡ لَإِلَى ٱلۡجَحِيمِ ﴿٦٨﴾ إِنَّهُمۡ أَلۡفَوۡاْ ءَابَآءَهُمۡ ضَآلِّينَ ﴿٦٩﴾ فَهُمۡ عَلَىٰٓ ءَاثَٰرِهِمۡ يُهۡرَعُونَ ﴿٧٠﴾ وَلَقَدۡ ضَلَّ قَبۡلَهُمۡ أَكۡثَرُ ٱلۡأَوَّلِينَ ﴿٧١﴾ وَلَقَدۡ أَرۡسَلۡنَا فِيهِم مُّنذِرِينَ ﴿٧٢﴾ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ ﴿٧٣﴾ إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ ﴿٧٤﴾", "w": [["أذلك خير نزلاً", "ذلك المذكور لأهل الجنة خير نُزُلاً، وهو ما يُعدّ للنازل من قِرى."], ["أم شجرة الزقوم", "المُعدّة لأهل النار، وهي من أخبث الشجر طعماً ومرارة."], ["إنا جعلناها فتنة للظالمين", "امتحاناً واختباراً لهم في الدنيا وعذاباً لهم في الآخرة."], ["تخرج في أصل الجحيم", "في قعر الجحيم وأغصانها في دركاتها."], ["طلعها كأنه رؤوس الشياطين", "ما يطلع من ثمرها أولاً كالحيّات القبيحة المنظر."], ["لشوباً من حميم", "بعد أكلها يُسقون ماءً حميماً، فذلك الشوب أي الخلط."], ["إنهم ألفَوا آباءهم", "وجدوا آباءهم."], ["فهم على آثارهم يُهرعون", "يسرعون مندفعين إلى اتباعهم بدون فكر ولا رويّة."], ["ولقد أرسلنا فيهم منذرين", "رسلاً منذرين لهم من العذاب."], ["فانظر كيف كان عاقبة المنذَرين", "كانت عذاباً أليماً لإصرارهم على الكفر."], ["إلا عباد الله المخلَصين", "فإنهم نجوا من العذاب ولم يهلكوا."]], "m": "لما ذكر تعالى ما أعدّه لأهل الإيمان من النعيم المقيم قال: أذلك خير نزلاً، والنزل ما يُعدّ من قِرى للضيف، أم شجرة الزقوم؟ أي ثمرها، وهو ثمر سمج مرّ قبيح المنظر. ثم أخبر أنه جعلها فتنة للظالمين من كفار قريش، إذ قالوا لما سمعوا بها: كيف تنبت الشجرة في النار والنار تحرق الشجر؟ فكذّبوا بها فكانت فتنة لهم. ثم وصفها بأنها تخرج في قعر الجحيم وتمتد فروعها في دركات النار، طلعها في قبح منظره كأنه رؤوس الشياطين، لأن العرب تضرب المثل بالشيطان في القبح. فإنهم لآكلون منها لشدة جوعهم فمالئون منها بطونهم، ثم إنهم لما يأكلون يعطشون فيُسقون من حميم يُخلط به ما أكلوا، ثم إن مردّهم بعد ذلك إلى الجحيم. إنهم وجدوا آباءهم ضالين عن الهدى، فهم يهرولون وراءهم يتبعونهم في الشرك والضلال، وليس هؤلاء أول من ضل، فقد ضل قبلهم أكثر الأولين، ولقد أرسلنا فيهم رسلاً ينذرونهم فلم يؤمنوا فأهلكناهم، فانظر كيف كانت عاقبتهم هلاكاً ودماراً، إلا عباد الله الذين استخلصهم لعبادته فآمنوا وأطاعوا فنجّاهم. وفي الآية تهديد ووعيد لكفار قريش بما لا مزيد عليه.", "h": ["بيان أحسن الأساليب في الدعوة، وهو الترهيب والترغيب.", "تقرير البعث والجزاء بأسلوب العرض للأحداث التي تتم في القيامة.", "التنديد بالاتباع في الضلال للآباء والأجداد وأهل البلاد.", "إهلاك الله تعالى للظالمين وإنجاؤه للمؤمنين عند الأخذ بالذنوب في الدنيا والآخرة."], "k": "«فهم على آثارهم يُهرعون»… كم عادةٍ أتبعها لأني وجدت الناس عليها، دون أن أسأل: أهي حق؟"}, {"lbl": "الآيات ٧٥ – ٨٢", "q": "وَلَقَدۡ نَادَىٰنَا نُوحٞ فَلَنِعۡمَ ٱلۡمُجِيبُونَ ﴿٧٥﴾ وَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ ﴿٧٦﴾ وَجَعَلۡنَا ذُرِّيَّتَهُۥ هُمُ ٱلۡبَاقِينَ ﴿٧٧﴾ وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ ﴿٧٨﴾ سَلَٰمٌ عَلَىٰ نُوحٖ فِي ٱلۡعَٰلَمِينَ ﴿٧٩﴾ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿٨٠﴾ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ﴿٨١﴾ ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ ﴿٨٢﴾", "w": [["ولقد نادانا نوح", "قال: إني مغلوب فانتصر."], ["فلنعم المجيبون", "له، إذ نجّيناه وأهلكنا الكافرين."], ["وجعلنا ذريته هم الباقين", "إذ عامة الناس كانوا من ذريته: سام وحام ويافث."], ["وتركنا عليه في الآخرين", "أبقينا عليه ثناءً حسناً عند سائر الأمم والشعوب."], ["سلام على نوح في العالمين", "سلام منا على نوح في العالمين."], ["إنا كذلك نجزي المحسنين", "كما جزينا نوحاً بالذكر الحسن نجزي المحسنين."], ["ثم أغرقنا الآخرين", "كفار قومه المشركين بعد إنجائه والمؤمنين."]], "m": "على إثر ذكره تعالى إهلاك المنذَرين وإنجاء المؤمنين ذكر مثالاً لذلك: نوح وقومه، أنذرهم فلما جاء العذاب نادى ربه فقال: رب انصرني بما كذّبون، وقال: إني مغلوب فانتصر، فلنعم المجيبون نحن له، ونجّيناه وأهله إلا امرأته وولده كنعان، من الكرب العظيم وهو عذاب الغرق. وجعلنا ذريته هم الباقين إلى يوم القيامة جزاءً على دعوته وإخلاصه وصدقه، إذ كل الناس اليوم من أولاده الثلاثة: سام أبو العرب والروم وفارس، وحام أبو السودان، ويافث أبو الترك والخزر ويأجوج ومأجوج. وتركنا عليه في أجيال البشرية التي أتت بعده الذكر الحسن: سلام على نوح في العالمين. إنا كذلك نجزي المحسنين، فلإيمانه وصبره وتقواه وصدقه ونصحه وإخلاصه جزيناه، وفي هذا بشرى للمؤمنين ودعوة إلى الإيمان بالترغيب فيه، إنه من عبادنا المؤمنين. ثم أغرقنا الآخرين من قومه لكفرهم وشركهم وتكذيبهم بعد أن أنجينا المؤمنين.", "h": ["بيان إكرام الله لأوليائه، وإهانته لأعدائه.", "إجابة دعاء الصالحين لا سيما عندما يُظلمون.", "فضل الإحسان وحسن عاقبة أهله.", "فضل الإيمان وكرامة أهله عند الله في الدنيا والآخرة.", "قول «سلام على نوح في العالمين» إذا قاله المؤمن حين يمسي أو يصبح يحفظه الله تعالى من لسعة العقرب، وأصحّ منه قول: «أعوذ بكلمات الله التامات من شر ما خلق» لصحة الحديث فيه."], "k": "«إنه من عبادنا المؤمنين»… بقي ذكر نوح في العالمين لصدقه؛ فما الذي سيبقى من ذكري؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (325, 37, 83, 113, 'سورة الصافات ٨٣ – ١١٣', 'الصافات: إبراهيم ﵇ القلب السليم والذبيح', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 325) = $j$[{"lbl": "الآيات ٨٣ – ٩٨", "q": "۞وَإِنَّ مِن شِيعَتِهِۦ لَإِبۡرَٰهِيمَ ﴿٨٣﴾ إِذۡ جَآءَ رَبَّهُۥ بِقَلۡبٖ سَلِيمٍ ﴿٨٤﴾ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَاذَا تَعۡبُدُونَ ﴿٨٥﴾ أَئِفۡكًا ءَالِهَةٗ دُونَ ٱللَّهِ تُرِيدُونَ ﴿٨٦﴾ فَمَا ظَنُّكُم بِرَبِّ ٱلۡعَٰلَمِينَ ﴿٨٧﴾ فَنَظَرَ نَظۡرَةٗ فِي ٱلنُّجُومِ ﴿٨٨﴾ فَقَالَ إِنِّي سَقِيمٞ ﴿٨٩﴾ فَتَوَلَّوۡاْ عَنۡهُ مُدۡبِرِينَ ﴿٩٠﴾ فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمۡ فَقَالَ أَلَا تَأۡكُلُونَ ﴿٩١﴾ مَا لَكُمۡ لَا تَنطِقُونَ ﴿٩٢﴾ فَرَاغَ عَلَيۡهِمۡ ضَرۡبَۢا بِٱلۡيَمِينِ ﴿٩٣﴾ فَأَقۡبَلُوٓاْ إِلَيۡهِ يَزِفُّونَ ﴿٩٤﴾ قَالَ أَتَعۡبُدُونَ مَا تَنۡحِتُونَ ﴿٩٥﴾ وَٱللَّهُ خَلَقَكُمۡ وَمَا تَعۡمَلُونَ ﴿٩٦﴾ قَالُواْ ٱبۡنُواْ لَهُۥ بُنۡيَٰنٗا فَأَلۡقُوهُ فِي ٱلۡجَحِيمِ ﴿٩٧﴾ فَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَسۡفَلِينَ ﴿٩٨﴾", "w": [["وإن من شيعته لإبراهيم", "وإن من أشياع نوح على ملته ومنهجه إبراهيم."], ["إذ جاء ربه بقلب سليم", "أتى ربه بقلب سليم من الشرك والشك والالتفات إلى غير الرب سبحانه."], ["ماذا تعبدون", "حين قال لأبيه وقومه منكراً عليهم عبادة الأصنام."], ["أئفكاً آلهة دون الله تريدون", "أكذباً هو أسوأ الكذب تريدون آلهة غير الله؟"], ["فما ظنكم برب العالمين", "أترون أنه لا يسخط عليكم وقد عبدتم غيره وهو ربكم ورب العالمين؟"], ["فنظر نظرة في النجوم", "إيهاماً لهم، إذ كانوا يؤلّهون الكواكب."], ["فقال إني سقيم", "عليل، ذو سقم وهو المرض والعلة."], ["فتولّوا عنه مدبرين", "رجعوا إلى ما هم فيه وتركوه."], ["فراغ إلى آلهتهم", "مال إليها خفية."], ["فراغ عليهم ضرباً باليمين", "بقوة يمينه فكسرها بفأس."], ["فأقبلوا إليه يزفّون", "يمشون بقوة وسرعة."], ["ما تنحتون", "من الحجارة والأخشاب والمعادن كالذهب والفضة."], ["وما تعملون", "وخلق ما تعملونه."], ["فجعلناهم الأسفلين", "المقهورين الخائبين في كيدهم."]], "m": "لما ذكر تعالى قصة نوح ذكر قصة إبراهيم ﵇، وهي أكبر موعظة لكفار قريش لأنهم ينتمون إليه ويدّعون أنهم على ملته، فقال: وإن من أشياع نوح على ملته إبراهيمَ خليلَ الرحمن، إذ جاء ربه بقلب سليم من الشرك والشك والالتفات إلى غير الله، حين قال لأبيه وقومه منكراً: ماذا تعبدون؟ فلو كان في قلبه أدنى التفاتة إلى غيره طمعاً أو خوفاً ما أمكنه أن يقول ما قال. أكذباً تريدون آلهة جعلتموها بألسنتكم آلهة وهي أحجار؟ فما ظنكم برب العالمين وقد عبدتم الكذب دونه، أترون أنه لا يعاقبكم؟ ثم إن أهل البلد عزموا على الخروج إلى عيد لهم خارج البلد، فعرضوا عليه الخروج فنظر في النجوم موهماً لهم أنه رأى ما دلّه على أنه سيصاب بسقم، وكانوا منجّمين، فاعتذر بقوله: إني سقيم، فتركوه خوفاً من العدوى أو قبولاً لعذره. فلما خلا له المكان راغ إلى آلهتهم وأمامها الأطعمة التي يتركها المشركون لتباركها ثم يأكلونها، فقال ساخراً: ألا تأكلون؟ ما لكم لا تنطقون؟ ثم انهال عليها ضرباً بفأسه بيده اليمنى فجعلها قطعاً متناثرة. فلما رجعوا من عيدهم ووجدوها مكسّرة أحضروه مسرعين وأخذوا يحاكمونه، فقال: أتعبدون ما تنحتون بأيديكم من حجر وخشب وفضة وذهب، والله خلقكم وما تعملون، فلِمَ لا تعبدونه؟ فلما غلبهم بالحجة أمروا بإحراقه: ابنوا له بنياناً واملؤوه حطباً وأضرموا فيه النار ثم ألقوه في جحيمه. فأرادوا به كيداً فجعلناهم الأسفلين المغلوبين، إذ قال تعالى للنار: كوني برداً وسلاماً على إبراهيم، فخرج منها ولم يُحرق سوى الكتاف الذي في يديه ورجليه، وخيّب الله سعي المشركين وأذلّهم.", "h": ["أصل الدين واحد، فالإسلام هو دين الله الذي تعبّد به آدم فمن بعده إلى محمد ﷺ.", "كمال إبراهيم ﵇ في سلامة قلبه من الالتفات إلى غير الله تعالى، حتى إن جبريل ﵇ عرض له وهو في طريقه إلى الجحيم الذي أعدّه له قومه فقال: هل لك حاجة يا إبراهيم؟ فقال: أما إليك فلا.", "من أقبح الكذب ادعاء أن غير الله يُعبد مع الله تبركاً به أو طلباً لشفاعته.", "وجوب تغيير المنكر عند القدرة عليه.", "بيان ابتلاء إبراهيم ﵇ وأنه أُلقي في النار فصبر، ولذا أكرمه ربه بما سيأتي في السياق بيانه."], "k": "«إذ جاء ربه بقلب سليم»… هل في قلبي التفاتة إلى غير الله؛ طمعٌ في أحد أو خوفٌ منه؟"}, {"lbl": "الآيات ٩٩ – ١١٣", "q": "وَقَالَ إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي سَيَهۡدِينِ ﴿٩٩﴾ رَبِّ هَبۡ لِي مِنَ ٱلصَّـٰلِحِينَ ﴿١٠٠﴾ فَبَشَّرۡنَٰهُ بِغُلَٰمٍ حَلِيمٖ ﴿١٠١﴾ فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَـٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّـٰبِرِينَ ﴿١٠٢﴾ فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ ﴿١٠٣﴾ وَنَٰدَيۡنَٰهُ أَن يَـٰٓإِبۡرَٰهِيمُ ﴿١٠٤﴾ قَدۡ صَدَّقۡتَ ٱلرُّءۡيَآۚ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿١٠٥﴾ إِنَّ هَٰذَا لَهُوَ ٱلۡبَلَـٰٓؤُاْ ٱلۡمُبِينُ ﴿١٠٦﴾ وَفَدَيۡنَٰهُ بِذِبۡحٍ عَظِيمٖ ﴿١٠٧﴾ وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ ﴿١٠٨﴾ سَلَٰمٌ عَلَىٰٓ إِبۡرَٰهِيمَ ﴿١٠٩﴾ كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿١١٠﴾ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ﴿١١١﴾ وَبَشَّرۡنَٰهُ بِإِسۡحَٰقَ نَبِيّٗا مِّنَ ٱلصَّـٰلِحِينَ ﴿١١٢﴾ وَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ ﴿١١٣﴾", "w": [["إني ذاهب إلى ربي سيهدين", "إني مهاجر إلى ربي سيهديني."], ["رب هب لي من الصالحين", "ولداً من الصالحين."], ["بغلام حليم", "ذي حلم وصبر كثير يولد له."], ["فلما بلغ معه السعي", "بلغ من العمر ما أصبح يقدر فيه على العمل معه."], ["فانظر ماذا ترى", "من الرأي الرشد."], ["من الصابرين", "على الذبح الذي أُمرت به."], ["فلما أسلما", "خضعا لأمر الله، الولد والوالد، وانقادا له."], ["وتلّه للجبين", "صرعه على جبينه بأن وضع جبينه على الأرض، وللإنسان جبينان أيمن وأيسر والجبهة بينهما."], ["قد صدّقت الرؤيا", "بما عزمت عليه وفعلته من إضجاعه على الأرض وإمرار السكين على حلقه."], ["إن هذا لهو البلاء المبين", "الأمر بالذبح اختبار بيّن."], ["وفديناه بذبح عظيم", "كبش كبير."], ["وتركنا عليه في الآخرين", "أبقينا عليه ثناءً وذكراً حسناً."], ["وباركنا عليه وعلى إسحاق", "بتكثير ذريتهما."]], "m": "ما زال السياق في قصة إبراهيم الخليل ﵇: بعد أن نجّاه الله من النار قرّر الهجرة وقال: إني ذاهب إلى حيث أذن لي ربي، حيث أتمكن من عبادته، فذهب إلى بلاد الشام ونزل أولاً بحرّان، سيهدين أي يثبّتني بدوام هدايته. ودعا ربه: رب هب لي من الصالحين، فاستجاب له: سافر مع زوجته سارة حتى انتهى إلى مصر، فوهب طاغية مصر جارية لسارة تسمى هاجر، فوهبتها سارة لزوجها فتسرّاها فولدت له إسماعيل، وهو قوله: فبشرناه بغلام حليم. وأخذ سارةَ ما يأخذ النساء من الغيرة، فأمر الله إبراهيم أن يأخذ هاجر وطفلها إلى مكة إبعاداً لها عن سارة ليقل تألّمها. وهناك رأى إبراهيم رؤياه، ورؤيا الأنبياء وحي، فلما بلغ إسماعيل سبع سنين فأكثر قال: يا بني إني أرى في المنام أني أذبحك فانظر ماذا ترى، استشاره ليرى رأيه، فقال: يا أبت افعل ما تؤمر، ستجدني إن شاء الله من الصابرين. فخرج به من حول البيت إلى منى حتى جاوز مكان الجمرات الثلاث، وتلّه للجبين، وأخذ المدية ووضعها على رقبته، فإذا بكبش أملح والهاتف يقول: اترك ذاك وخذ هذا، فترك الولد وذبح الكبش، وهو قوله: وفديناه بذبح عظيم. وناديناه أن يا إبراهيم قد صدّقت الرؤيا، إنا كذلك نجزي المحسنين، إن هذا لهو الاختبار البيّن، وبذلك تأهّل للخُلّة. وأبقينا عليه ثناءً عاطراً فيمن جاء بعده: سلام على إبراهيم، كذلك نجزي المحسنين على إيمانهم وهجرتهم وصبرهم وطاعتهم، إنه من عبادنا المؤمنين. وبشرناه بإسحاق نبياً من الصالحين، وذلك يوم جاءه الضيف من الملائكة في طريقهم إلى قرى قوم لوط، بعد أن بلغ من العمر عتياً وامرأته سارة كذلك، فعجباً لمن يقول إن الذبيح إسحاق وليس إسماعيل! وباركنا عليه وعلى إسحاق بتكثير ذريتهما حتى إن عامة الأنبياء من بعدهما من ذريتهما، ومن ذريتهما محسن مؤمن صالح، وظالم لنفسه بالشرك والمعاصي.", "h": ["فضل الهجرة في سبيل الله، وأن أول هجرة كانت في الأرض هي هجرة إبراهيم ﵇ من العراق إلى الشام.", "بيان أن الذبيح هو إسماعيل ﵇ وليس إسحاق كما يقول البعض وكما يدّعي اليهود.", "وجوب بر الوالدين وطاعتهما في المعروف.", "فضل إبراهيم ﵇ وعلوّ مقامه وكرامته عند ربه.", "فضل الإحسان وجزاء المحسنين."], "k": "«يا أبتِ افعل ما تؤمر»… أسلما معاً لأمر الله؛ فما الذي يصعب عليّ أن أسلّمه له؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 325;
insert into public.tdb_cards(topic, i, body) select 325, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٣ – ٩٨", "q": "۞وَإِنَّ مِن شِيعَتِهِۦ لَإِبۡرَٰهِيمَ ﴿٨٣﴾ إِذۡ جَآءَ رَبَّهُۥ بِقَلۡبٖ سَلِيمٍ ﴿٨٤﴾ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَاذَا تَعۡبُدُونَ ﴿٨٥﴾ أَئِفۡكًا ءَالِهَةٗ دُونَ ٱللَّهِ تُرِيدُونَ ﴿٨٦﴾ فَمَا ظَنُّكُم بِرَبِّ ٱلۡعَٰلَمِينَ ﴿٨٧﴾ فَنَظَرَ نَظۡرَةٗ فِي ٱلنُّجُومِ ﴿٨٨﴾ فَقَالَ إِنِّي سَقِيمٞ ﴿٨٩﴾ فَتَوَلَّوۡاْ عَنۡهُ مُدۡبِرِينَ ﴿٩٠﴾ فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمۡ فَقَالَ أَلَا تَأۡكُلُونَ ﴿٩١﴾ مَا لَكُمۡ لَا تَنطِقُونَ ﴿٩٢﴾ فَرَاغَ عَلَيۡهِمۡ ضَرۡبَۢا بِٱلۡيَمِينِ ﴿٩٣﴾ فَأَقۡبَلُوٓاْ إِلَيۡهِ يَزِفُّونَ ﴿٩٤﴾ قَالَ أَتَعۡبُدُونَ مَا تَنۡحِتُونَ ﴿٩٥﴾ وَٱللَّهُ خَلَقَكُمۡ وَمَا تَعۡمَلُونَ ﴿٩٦﴾ قَالُواْ ٱبۡنُواْ لَهُۥ بُنۡيَٰنٗا فَأَلۡقُوهُ فِي ٱلۡجَحِيمِ ﴿٩٧﴾ فَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَسۡفَلِينَ ﴿٩٨﴾", "w": [["وإن من شيعته لإبراهيم", "وإن من أشياع نوح على ملته ومنهجه إبراهيم."], ["إذ جاء ربه بقلب سليم", "أتى ربه بقلب سليم من الشرك والشك والالتفات إلى غير الرب سبحانه."], ["ماذا تعبدون", "حين قال لأبيه وقومه منكراً عليهم عبادة الأصنام."], ["أئفكاً آلهة دون الله تريدون", "أكذباً هو أسوأ الكذب تريدون آلهة غير الله؟"], ["فما ظنكم برب العالمين", "أترون أنه لا يسخط عليكم وقد عبدتم غيره وهو ربكم ورب العالمين؟"], ["فنظر نظرة في النجوم", "إيهاماً لهم، إذ كانوا يؤلّهون الكواكب."], ["فقال إني سقيم", "عليل، ذو سقم وهو المرض والعلة."], ["فتولّوا عنه مدبرين", "رجعوا إلى ما هم فيه وتركوه."], ["فراغ إلى آلهتهم", "مال إليها خفية."], ["فراغ عليهم ضرباً باليمين", "بقوة يمينه فكسرها بفأس."], ["فأقبلوا إليه يزفّون", "يمشون بقوة وسرعة."], ["ما تنحتون", "من الحجارة والأخشاب والمعادن كالذهب والفضة."], ["وما تعملون", "وخلق ما تعملونه."], ["فجعلناهم الأسفلين", "المقهورين الخائبين في كيدهم."]], "m": "لما ذكر تعالى قصة نوح ذكر قصة إبراهيم ﵇، وهي أكبر موعظة لكفار قريش لأنهم ينتمون إليه ويدّعون أنهم على ملته، فقال: وإن من أشياع نوح على ملته إبراهيمَ خليلَ الرحمن، إذ جاء ربه بقلب سليم من الشرك والشك والالتفات إلى غير الله، حين قال لأبيه وقومه منكراً: ماذا تعبدون؟ فلو كان في قلبه أدنى التفاتة إلى غيره طمعاً أو خوفاً ما أمكنه أن يقول ما قال. أكذباً تريدون آلهة جعلتموها بألسنتكم آلهة وهي أحجار؟ فما ظنكم برب العالمين وقد عبدتم الكذب دونه، أترون أنه لا يعاقبكم؟ ثم إن أهل البلد عزموا على الخروج إلى عيد لهم خارج البلد، فعرضوا عليه الخروج فنظر في النجوم موهماً لهم أنه رأى ما دلّه على أنه سيصاب بسقم، وكانوا منجّمين، فاعتذر بقوله: إني سقيم، فتركوه خوفاً من العدوى أو قبولاً لعذره. فلما خلا له المكان راغ إلى آلهتهم وأمامها الأطعمة التي يتركها المشركون لتباركها ثم يأكلونها، فقال ساخراً: ألا تأكلون؟ ما لكم لا تنطقون؟ ثم انهال عليها ضرباً بفأسه بيده اليمنى فجعلها قطعاً متناثرة. فلما رجعوا من عيدهم ووجدوها مكسّرة أحضروه مسرعين وأخذوا يحاكمونه، فقال: أتعبدون ما تنحتون بأيديكم من حجر وخشب وفضة وذهب، والله خلقكم وما تعملون، فلِمَ لا تعبدونه؟ فلما غلبهم بالحجة أمروا بإحراقه: ابنوا له بنياناً واملؤوه حطباً وأضرموا فيه النار ثم ألقوه في جحيمه. فأرادوا به كيداً فجعلناهم الأسفلين المغلوبين، إذ قال تعالى للنار: كوني برداً وسلاماً على إبراهيم، فخرج منها ولم يُحرق سوى الكتاف الذي في يديه ورجليه، وخيّب الله سعي المشركين وأذلّهم.", "h": ["أصل الدين واحد، فالإسلام هو دين الله الذي تعبّد به آدم فمن بعده إلى محمد ﷺ.", "كمال إبراهيم ﵇ في سلامة قلبه من الالتفات إلى غير الله تعالى، حتى إن جبريل ﵇ عرض له وهو في طريقه إلى الجحيم الذي أعدّه له قومه فقال: هل لك حاجة يا إبراهيم؟ فقال: أما إليك فلا.", "من أقبح الكذب ادعاء أن غير الله يُعبد مع الله تبركاً به أو طلباً لشفاعته.", "وجوب تغيير المنكر عند القدرة عليه.", "بيان ابتلاء إبراهيم ﵇ وأنه أُلقي في النار فصبر، ولذا أكرمه ربه بما سيأتي في السياق بيانه."], "k": "«إذ جاء ربه بقلب سليم»… هل في قلبي التفاتة إلى غير الله؛ طمعٌ في أحد أو خوفٌ منه؟"}, {"lbl": "الآيات ٩٩ – ١١٣", "q": "وَقَالَ إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي سَيَهۡدِينِ ﴿٩٩﴾ رَبِّ هَبۡ لِي مِنَ ٱلصَّـٰلِحِينَ ﴿١٠٠﴾ فَبَشَّرۡنَٰهُ بِغُلَٰمٍ حَلِيمٖ ﴿١٠١﴾ فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَـٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّـٰبِرِينَ ﴿١٠٢﴾ فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ ﴿١٠٣﴾ وَنَٰدَيۡنَٰهُ أَن يَـٰٓإِبۡرَٰهِيمُ ﴿١٠٤﴾ قَدۡ صَدَّقۡتَ ٱلرُّءۡيَآۚ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿١٠٥﴾ إِنَّ هَٰذَا لَهُوَ ٱلۡبَلَـٰٓؤُاْ ٱلۡمُبِينُ ﴿١٠٦﴾ وَفَدَيۡنَٰهُ بِذِبۡحٍ عَظِيمٖ ﴿١٠٧﴾ وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ ﴿١٠٨﴾ سَلَٰمٌ عَلَىٰٓ إِبۡرَٰهِيمَ ﴿١٠٩﴾ كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿١١٠﴾ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ﴿١١١﴾ وَبَشَّرۡنَٰهُ بِإِسۡحَٰقَ نَبِيّٗا مِّنَ ٱلصَّـٰلِحِينَ ﴿١١٢﴾ وَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ ﴿١١٣﴾", "w": [["إني ذاهب إلى ربي سيهدين", "إني مهاجر إلى ربي سيهديني."], ["رب هب لي من الصالحين", "ولداً من الصالحين."], ["بغلام حليم", "ذي حلم وصبر كثير يولد له."], ["فلما بلغ معه السعي", "بلغ من العمر ما أصبح يقدر فيه على العمل معه."], ["فانظر ماذا ترى", "من الرأي الرشد."], ["من الصابرين", "على الذبح الذي أُمرت به."], ["فلما أسلما", "خضعا لأمر الله، الولد والوالد، وانقادا له."], ["وتلّه للجبين", "صرعه على جبينه بأن وضع جبينه على الأرض، وللإنسان جبينان أيمن وأيسر والجبهة بينهما."], ["قد صدّقت الرؤيا", "بما عزمت عليه وفعلته من إضجاعه على الأرض وإمرار السكين على حلقه."], ["إن هذا لهو البلاء المبين", "الأمر بالذبح اختبار بيّن."], ["وفديناه بذبح عظيم", "كبش كبير."], ["وتركنا عليه في الآخرين", "أبقينا عليه ثناءً وذكراً حسناً."], ["وباركنا عليه وعلى إسحاق", "بتكثير ذريتهما."]], "m": "ما زال السياق في قصة إبراهيم الخليل ﵇: بعد أن نجّاه الله من النار قرّر الهجرة وقال: إني ذاهب إلى حيث أذن لي ربي، حيث أتمكن من عبادته، فذهب إلى بلاد الشام ونزل أولاً بحرّان، سيهدين أي يثبّتني بدوام هدايته. ودعا ربه: رب هب لي من الصالحين، فاستجاب له: سافر مع زوجته سارة حتى انتهى إلى مصر، فوهب طاغية مصر جارية لسارة تسمى هاجر، فوهبتها سارة لزوجها فتسرّاها فولدت له إسماعيل، وهو قوله: فبشرناه بغلام حليم. وأخذ سارةَ ما يأخذ النساء من الغيرة، فأمر الله إبراهيم أن يأخذ هاجر وطفلها إلى مكة إبعاداً لها عن سارة ليقل تألّمها. وهناك رأى إبراهيم رؤياه، ورؤيا الأنبياء وحي، فلما بلغ إسماعيل سبع سنين فأكثر قال: يا بني إني أرى في المنام أني أذبحك فانظر ماذا ترى، استشاره ليرى رأيه، فقال: يا أبت افعل ما تؤمر، ستجدني إن شاء الله من الصابرين. فخرج به من حول البيت إلى منى حتى جاوز مكان الجمرات الثلاث، وتلّه للجبين، وأخذ المدية ووضعها على رقبته، فإذا بكبش أملح والهاتف يقول: اترك ذاك وخذ هذا، فترك الولد وذبح الكبش، وهو قوله: وفديناه بذبح عظيم. وناديناه أن يا إبراهيم قد صدّقت الرؤيا، إنا كذلك نجزي المحسنين، إن هذا لهو الاختبار البيّن، وبذلك تأهّل للخُلّة. وأبقينا عليه ثناءً عاطراً فيمن جاء بعده: سلام على إبراهيم، كذلك نجزي المحسنين على إيمانهم وهجرتهم وصبرهم وطاعتهم، إنه من عبادنا المؤمنين. وبشرناه بإسحاق نبياً من الصالحين، وذلك يوم جاءه الضيف من الملائكة في طريقهم إلى قرى قوم لوط، بعد أن بلغ من العمر عتياً وامرأته سارة كذلك، فعجباً لمن يقول إن الذبيح إسحاق وليس إسماعيل! وباركنا عليه وعلى إسحاق بتكثير ذريتهما حتى إن عامة الأنبياء من بعدهما من ذريتهما، ومن ذريتهما محسن مؤمن صالح، وظالم لنفسه بالشرك والمعاصي.", "h": ["فضل الهجرة في سبيل الله، وأن أول هجرة كانت في الأرض هي هجرة إبراهيم ﵇ من العراق إلى الشام.", "بيان أن الذبيح هو إسماعيل ﵇ وليس إسحاق كما يقول البعض وكما يدّعي اليهود.", "وجوب بر الوالدين وطاعتهما في المعروف.", "فضل إبراهيم ﵇ وعلوّ مقامه وكرامته عند ربه.", "فضل الإحسان وجزاء المحسنين."], "k": "«يا أبتِ افعل ما تؤمر»… أسلما معاً لأمر الله؛ فما الذي يصعب عليّ أن أسلّمه له؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (326, 37, 114, 138, 'سورة الصافات ١١٤ – ١٣٨', 'الصافات: موسى وهارون وإلياس ولوط ﵈', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 326) = $j$[{"lbl": "الآيات ١١٤ – ١٢٢", "q": "وَلَقَدۡ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَٰرُونَ ﴿١١٤﴾ وَنَجَّيۡنَٰهُمَا وَقَوۡمَهُمَا مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ ﴿١١٥﴾ وَنَصَرۡنَٰهُمۡ فَكَانُواْ هُمُ ٱلۡغَٰلِبِينَ ﴿١١٦﴾ وَءَاتَيۡنَٰهُمَا ٱلۡكِتَٰبَ ٱلۡمُسۡتَبِينَ ﴿١١٧﴾ وَهَدَيۡنَٰهُمَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ ﴿١١٨﴾ وَتَرَكۡنَا عَلَيۡهِمَا فِي ٱلۡأٓخِرِينَ ﴿١١٩﴾ سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ ﴿١٢٠﴾ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿١٢١﴾ إِنَّهُمَا مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ﴿١٢٢﴾", "w": [["ولقد مننّا على موسى وهارون", "بالنبوة والرسالة."], ["ونجّيناهما وقومهما", "بني إسرائيل."], ["من الكرب العظيم", "استعباد فرعون إياهم واضطهاده لهم."], ["ونصرناهم", "على فرعون وجنوده."], ["الكتاب المستبين", "التوراة الموضِّحة الأحكام والشرائع."], ["وهديناهما الصراط المستقيم", "الإسلام لله رب العالمين."], ["وتركنا عليهما في الآخرين", "أبقينا عليهما في الآخرين ثناءً حسناً."], ["إنا كذلك", "كما جزيناهما نجزي المحسنين من عبادنا المؤمنين."], ["إنهما من عبادنا المؤمنين", "جزيناهما بما جزيناهما به لإيمانهما."]], "m": "ما زال السياق في ذكر إفضال الله على من يشاء من عباده، فبعد ذكر إنعامه على إبراهيم وولده إسحاق ذكر من ذريتهما المحسنين موسى وهارون: ولقد مننّا عليهما بالنبوة والرسالة، ونجّيناهما وقومهما بني إسرائيل من الكرب العظيم الذي هو استعباد فرعون والأقباط لهم واضطهادهم زمناً طويلاً، ونصرناهم على فرعون وملئه فكانوا هم الغالبين، وآتيناهما التوراة الواضحة الأحكام البيّنة الشرائع لا خفاء فيها ولا غموض، وهديناهما الدين الصحيح الذي هو الإسلام دين الله الذي بعث به كافة رسله، وأبقينا عليهما الذكر الحسن فيمن بعدهما: سلام على موسى وهارون. إنا كذلك نجزي المحسنين، إنهما من عبادنا المؤمنين؛ وفيه بيان علة ما وهبهما من الإنعام، وهو الإيمان المقتضي للإسلام.", "h": ["بيان إكرام الله تعالى لرسوليه موسى وهارون ﵉.", "إنعام الله تعالى على بني إسرائيل بإنجائهم من آل فرعون ونصرته لهم عليهم.", "بيان أن الإسلام دين سائر الأنبياء وليس خاصاً بأمة الإسلام.", "بيان فضل الإحسان والإيمان."], "k": "«ونجّيناهما وقومهما من الكرب العظيم»… الذي نجّاهم من كرب طويل قادر على كربي؛ فهل ألجأ إليه؟"}, {"lbl": "الآيات ١٢٣ – ١٣٢", "q": "وَإِنَّ إِلۡيَاسَ لَمِنَ ٱلۡمُرۡسَلِينَ ﴿١٢٣﴾ إِذۡ قَالَ لِقَوۡمِهِۦٓ أَلَا تَتَّقُونَ ﴿١٢٤﴾ أَتَدۡعُونَ بَعۡلٗا وَتَذَرُونَ أَحۡسَنَ ٱلۡخَٰلِقِينَ ﴿١٢٥﴾ ٱللَّهَ رَبَّكُمۡ وَرَبَّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ ﴿١٢٦﴾ فَكَذَّبُوهُ فَإِنَّهُمۡ لَمُحۡضَرُونَ ﴿١٢٧﴾ إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ ﴿١٢٨﴾ وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ ﴿١٢٩﴾ سَلَٰمٌ عَلَىٰٓ إِلۡ يَاسِينَ ﴿١٣٠﴾ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿١٣١﴾ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ﴿١٣٢﴾", "w": [["وإن إلياس لمن المرسلين", "إلياس أحد أنبياء بني إسرائيل من سبط هارون، أرسله الله إلى أهل مدينة بعلبك بالشام."], ["أتدعون بعلاً", "صنماً يسمى بعلاً."], ["وتذرون أحسن الخالقين", "وتتركون عبادة الله أحسن الخالقين."], ["فإنهم لمحضرون", "في النار."], ["إلا عباد الله المخلَصين", "فإنهم نجوا من النار."], ["وتركنا عليه في الآخرين", "أبقينا عليه في الآخرين ذكراً حسناً."], ["سلام على إل ياسين", "سلام منا على إلياس."]], "m": "في ذكر إنعام الله على بعض أنبيائه: وإن إلياس من سبط هارون ﵇ لمن المرسلين، إذ قال لقومه أهل بعلبك وما حولها: ألا تتقون الله بعبادته وترك عبادة غيره؟ أتدعون بعلاً، صنماً كبيراً لهم، فتعبدونه بدعائه والعكوف عليه والذبح والنذر له، وتتركون عبادة الله أحسن الخالقين، ربكم ورب آبائكم الأولين؟ فكذّبوه في أنه لا إله إلا الله، فماتوا وهم كافرون فهم من المحضرين في جهنم، إلا عباد الله الموحّدين فإنهم في الجنة. وأبقينا له ذكراً حسناً فيمن جاء بعده: سلام على إل ياسين. إنا كذلك نجزي المحسنين كما جزينا إلياس لإحسانه في طاعتنا، إنه من عبادنا المؤمنين، استحق تكريمنا والجزاء الحسن لإيمانه.", "h": ["تقرير التوحيد، والتنديد بالشرك.", "هلاك المشركين ونجاة الموحدين يوم القيامة.", "فضل الإحسان ومجازاة أهله بحسن الجزاء.", "فضل الإيمان وأنه سبب كل خير وكمال."], "k": "«أتدعون بعلاً وتذرون أحسن الخالقين»… ما «البعل» الذي قد أُقبل عليه اليوم وأترك ربي؟"}, {"lbl": "الآيات ١٣٣ – ١٣٨", "q": "وَإِنَّ لُوطٗا لَّمِنَ ٱلۡمُرۡسَلِينَ ﴿١٣٣﴾ إِذۡ نَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ ﴿١٣٤﴾ إِلَّا عَجُوزٗا فِي ٱلۡغَٰبِرِينَ ﴿١٣٥﴾ ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ ﴿١٣٦﴾ وَإِنَّكُمۡ لَتَمُرُّونَ عَلَيۡهِم مُّصۡبِحِينَ ﴿١٣٧﴾ وَبِٱلَّيۡلِۚ أَفَلَا تَعۡقِلُونَ ﴿١٣٨﴾", "w": [["وإن لوطاً لمن المرسلين", "لوط هو ابن هاران أخي إبراهيم الخليل، من جملة المرسلين."], ["إذ نجّيناه وأهله أجمعين", "من عذاب مطر السوء."], ["إلا عجوزاً في الغابرين", "إلا امرأته الكافرة هلكت في الباقين في العذاب."], ["ثم دمّرنا الآخرين", "أهلكنا من عدا لوطاً والمؤمنين معه."], ["وإنكم لتمرّون عليهم", "في أسفاركم إلى فلسطين وغزة ومصر بالليل والنهار."], ["أفلا تعقلون", "يا أهل مكة ما حلّ بهم فتعتبرون فتؤمنون."]], "m": "ما زال السياق في ذكر إنعام الله على من اصطفى من عباده: وإن لوطاً ابن أخي إبراهيم ﵉ لمن جملة رسلنا، اذكر إنعامنا عليه إذ نجّيناه وأهله أجمعين إلا امرأته، إذ كانت مع الكافرين فبقيت معهم فهلكت بهلاكهم، ثم دمّرنا من عدا لوطاً ومن آمن به. وإنكم يا أهل مكة لتمرّون عليهم في أسفاركم للتجارة إلى الشام وفلسطين مصبحين وبالليل، تمرّون بالبحر الميت، مكان الهالكين من قوم لوط، صار بعد الخسف بحراً ميتاً لا حياة فيه البتة. أفلا تعقلون؟ توبيخ لهم على عدم التفكر، إذ لو فكّروا لعلموا أن الله أهلكهم لتكذيبهم رسولهم، وقد كذّب هؤلاء، فأيّ مانع يمنع من وقوع العذاب بهم كما وقع بقوم لوط؟", "h": ["تقرير نبوة لوط ﵇ ورسالته.", "بيان العبرة في إنجاء لوط والمؤمنين معه وإهلاك الكافرين المكذبين به.", "بيان أن لا شفاعة تنفع ولو كان الشافع أقرب قريب إلا بعد أن يأذن الله للشافع.", "وجوب التفكر والتعقل في الأحداث الكونية للاهتداء بذلك إلى معرفة سنن الله تعالى في الكون والحياة."], "k": "«وإنكم لتمرّون عليهم… أفلا تعقلون»… كم مررتُ على عبرة ولم أقف عندها؟"}]$j$::jsonb then 0 else 1 end;
