insert into public.tdb_cards(topic, i, body) select 326, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١٤ – ١٢٢", "q": "وَلَقَدۡ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَٰرُونَ ﴿١١٤﴾ وَنَجَّيۡنَٰهُمَا وَقَوۡمَهُمَا مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ ﴿١١٥﴾ وَنَصَرۡنَٰهُمۡ فَكَانُواْ هُمُ ٱلۡغَٰلِبِينَ ﴿١١٦﴾ وَءَاتَيۡنَٰهُمَا ٱلۡكِتَٰبَ ٱلۡمُسۡتَبِينَ ﴿١١٧﴾ وَهَدَيۡنَٰهُمَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ ﴿١١٨﴾ وَتَرَكۡنَا عَلَيۡهِمَا فِي ٱلۡأٓخِرِينَ ﴿١١٩﴾ سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ ﴿١٢٠﴾ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿١٢١﴾ إِنَّهُمَا مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ﴿١٢٢﴾", "w": [["ولقد مننّا على موسى وهارون", "بالنبوة والرسالة."], ["ونجّيناهما وقومهما", "بني إسرائيل."], ["من الكرب العظيم", "استعباد فرعون إياهم واضطهاده لهم."], ["ونصرناهم", "على فرعون وجنوده."], ["الكتاب المستبين", "التوراة الموضِّحة الأحكام والشرائع."], ["وهديناهما الصراط المستقيم", "الإسلام لله رب العالمين."], ["وتركنا عليهما في الآخرين", "أبقينا عليهما في الآخرين ثناءً حسناً."], ["إنا كذلك", "كما جزيناهما نجزي المحسنين من عبادنا المؤمنين."], ["إنهما من عبادنا المؤمنين", "جزيناهما بما جزيناهما به لإيمانهما."]], "m": "ما زال السياق في ذكر إفضال الله على من يشاء من عباده، فبعد ذكر إنعامه على إبراهيم وولده إسحاق ذكر من ذريتهما المحسنين موسى وهارون: ولقد مننّا عليهما بالنبوة والرسالة، ونجّيناهما وقومهما بني إسرائيل من الكرب العظيم الذي هو استعباد فرعون والأقباط لهم واضطهادهم زمناً طويلاً، ونصرناهم على فرعون وملئه فكانوا هم الغالبين، وآتيناهما التوراة الواضحة الأحكام البيّنة الشرائع لا خفاء فيها ولا غموض، وهديناهما الدين الصحيح الذي هو الإسلام دين الله الذي بعث به كافة رسله، وأبقينا عليهما الذكر الحسن فيمن بعدهما: سلام على موسى وهارون. إنا كذلك نجزي المحسنين، إنهما من عبادنا المؤمنين؛ وفيه بيان علة ما وهبهما من الإنعام، وهو الإيمان المقتضي للإسلام.", "h": ["بيان إكرام الله تعالى لرسوليه موسى وهارون ﵉.", "إنعام الله تعالى على بني إسرائيل بإنجائهم من آل فرعون ونصرته لهم عليهم.", "بيان أن الإسلام دين سائر الأنبياء وليس خاصاً بأمة الإسلام.", "بيان فضل الإحسان والإيمان."], "k": "«ونجّيناهما وقومهما من الكرب العظيم»… الذي نجّاهم من كرب طويل قادر على كربي؛ فهل ألجأ إليه؟"}, {"lbl": "الآيات ١٢٣ – ١٣٢", "q": "وَإِنَّ إِلۡيَاسَ لَمِنَ ٱلۡمُرۡسَلِينَ ﴿١٢٣﴾ إِذۡ قَالَ لِقَوۡمِهِۦٓ أَلَا تَتَّقُونَ ﴿١٢٤﴾ أَتَدۡعُونَ بَعۡلٗا وَتَذَرُونَ أَحۡسَنَ ٱلۡخَٰلِقِينَ ﴿١٢٥﴾ ٱللَّهَ رَبَّكُمۡ وَرَبَّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ ﴿١٢٦﴾ فَكَذَّبُوهُ فَإِنَّهُمۡ لَمُحۡضَرُونَ ﴿١٢٧﴾ إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ ﴿١٢٨﴾ وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ ﴿١٢٩﴾ سَلَٰمٌ عَلَىٰٓ إِلۡ يَاسِينَ ﴿١٣٠﴾ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿١٣١﴾ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ﴿١٣٢﴾", "w": [["وإن إلياس لمن المرسلين", "إلياس أحد أنبياء بني إسرائيل من سبط هارون، أرسله الله إلى أهل مدينة بعلبك بالشام."], ["أتدعون بعلاً", "صنماً يسمى بعلاً."], ["وتذرون أحسن الخالقين", "وتتركون عبادة الله أحسن الخالقين."], ["فإنهم لمحضرون", "في النار."], ["إلا عباد الله المخلَصين", "فإنهم نجوا من النار."], ["وتركنا عليه في الآخرين", "أبقينا عليه في الآخرين ذكراً حسناً."], ["سلام على إل ياسين", "سلام منا على إلياس."]], "m": "في ذكر إنعام الله على بعض أنبيائه: وإن إلياس من سبط هارون ﵇ لمن المرسلين، إذ قال لقومه أهل بعلبك وما حولها: ألا تتقون الله بعبادته وترك عبادة غيره؟ أتدعون بعلاً، صنماً كبيراً لهم، فتعبدونه بدعائه والعكوف عليه والذبح والنذر له، وتتركون عبادة الله أحسن الخالقين، ربكم ورب آبائكم الأولين؟ فكذّبوه في أنه لا إله إلا الله، فماتوا وهم كافرون فهم من المحضرين في جهنم، إلا عباد الله الموحّدين فإنهم في الجنة. وأبقينا له ذكراً حسناً فيمن جاء بعده: سلام على إل ياسين. إنا كذلك نجزي المحسنين كما جزينا إلياس لإحسانه في طاعتنا، إنه من عبادنا المؤمنين، استحق تكريمنا والجزاء الحسن لإيمانه.", "h": ["تقرير التوحيد، والتنديد بالشرك.", "هلاك المشركين ونجاة الموحدين يوم القيامة.", "فضل الإحسان ومجازاة أهله بحسن الجزاء.", "فضل الإيمان وأنه سبب كل خير وكمال."], "k": "«أتدعون بعلاً وتذرون أحسن الخالقين»… ما «البعل» الذي قد أُقبل عليه اليوم وأترك ربي؟"}, {"lbl": "الآيات ١٣٣ – ١٣٨", "q": "وَإِنَّ لُوطٗا لَّمِنَ ٱلۡمُرۡسَلِينَ ﴿١٣٣﴾ إِذۡ نَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ ﴿١٣٤﴾ إِلَّا عَجُوزٗا فِي ٱلۡغَٰبِرِينَ ﴿١٣٥﴾ ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ ﴿١٣٦﴾ وَإِنَّكُمۡ لَتَمُرُّونَ عَلَيۡهِم مُّصۡبِحِينَ ﴿١٣٧﴾ وَبِٱلَّيۡلِۚ أَفَلَا تَعۡقِلُونَ ﴿١٣٨﴾", "w": [["وإن لوطاً لمن المرسلين", "لوط هو ابن هاران أخي إبراهيم الخليل، من جملة المرسلين."], ["إذ نجّيناه وأهله أجمعين", "من عذاب مطر السوء."], ["إلا عجوزاً في الغابرين", "إلا امرأته الكافرة هلكت في الباقين في العذاب."], ["ثم دمّرنا الآخرين", "أهلكنا من عدا لوطاً والمؤمنين معه."], ["وإنكم لتمرّون عليهم", "في أسفاركم إلى فلسطين وغزة ومصر بالليل والنهار."], ["أفلا تعقلون", "يا أهل مكة ما حلّ بهم فتعتبرون فتؤمنون."]], "m": "ما زال السياق في ذكر إنعام الله على من اصطفى من عباده: وإن لوطاً ابن أخي إبراهيم ﵉ لمن جملة رسلنا، اذكر إنعامنا عليه إذ نجّيناه وأهله أجمعين إلا امرأته، إذ كانت مع الكافرين فبقيت معهم فهلكت بهلاكهم، ثم دمّرنا من عدا لوطاً ومن آمن به. وإنكم يا أهل مكة لتمرّون عليهم في أسفاركم للتجارة إلى الشام وفلسطين مصبحين وبالليل، تمرّون بالبحر الميت، مكان الهالكين من قوم لوط، صار بعد الخسف بحراً ميتاً لا حياة فيه البتة. أفلا تعقلون؟ توبيخ لهم على عدم التفكر، إذ لو فكّروا لعلموا أن الله أهلكهم لتكذيبهم رسولهم، وقد كذّب هؤلاء، فأيّ مانع يمنع من وقوع العذاب بهم كما وقع بقوم لوط؟", "h": ["تقرير نبوة لوط ﵇ ورسالته.", "بيان العبرة في إنجاء لوط والمؤمنين معه وإهلاك الكافرين المكذبين به.", "بيان أن لا شفاعة تنفع ولو كان الشافع أقرب قريب إلا بعد أن يأذن الله للشافع.", "وجوب التفكر والتعقل في الأحداث الكونية للاهتداء بذلك إلى معرفة سنن الله تعالى في الكون والحياة."], "k": "«وإنكم لتمرّون عليهم… أفلا تعقلون»… كم مررتُ على عبرة ولم أقف عندها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (327, 37, 139, 160, 'سورة الصافات ١٣٩ – ١٦٠', 'الصافات: يونس ﵇ وإبطال فرية البنات', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 327) = $j$[{"lbl": "الآيات ١٣٩ – ١٤٨", "q": "وَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ ﴿١٣٩﴾ إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ﴿١٤٠﴾ فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ ﴿١٤١﴾ فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ ﴿١٤٢﴾ فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ ﴿١٤٣﴾ لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ﴿١٤٤﴾ ۞فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمٞ ﴿١٤٥﴾ وَأَنۢبَتۡنَا عَلَيۡهِ شَجَرَةٗ مِّن يَقۡطِينٖ ﴿١٤٦﴾ وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ يَزِيدُونَ ﴿١٤٧﴾ فَـَٔامَنُواْ فَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ ﴿١٤٨﴾", "w": [["وإن يونس لمن المرسلين", "يونس بن متّى الملقّب بذي النون من جملة المرسلين."], ["إذ أبق إلى الفلك المشحون", "هرب إلى السفينة المملوءة بالركاب."], ["فساهم فكان من المدحَضين", "اقترع مع ركاب السفينة فكان من المغلوبين."], ["فالتقمه الحوت وهو مُليم", "ابتلعه الحوت وهو آتٍ بما يُلام عليه."], ["للبث في بطنه إلى يوم يُبعثون", "لكان بطن الحوت قبراً له إلى يوم القيامة."], ["فنبذناه بالعراء", "ألقيناه من بطن الحوت بوجه الأرض."], ["وهو سقيم", "عليل كالفرخ المنتوف الريش."], ["شجرة من يقطين", "الدُّبّاء: القرع."], ["فآمنوا فمتّعناهم إلى حين", "آمن قومه عند معاينة أمارات العذاب فأبقاهم الله إلى آجالهم."]], "m": "ما زال السياق في ذكر من أنعم الله عليهم: وإن عبدنا يونس بن متّى ذا النون لمن المرسلين، إذ هرب من قومه لما لم يؤمنوا به وواعدهم العذاب فتأخر عنهم، فاستعجل فهرب من مدينتهم نينوى من أرض الموصل بالعراق، فوصل الميناء فوجد سفينة فركب، وكانت حمولتها أكبر من طاقتها فوقفت في عرض البحر، فرأى ربّانها أنه لا بد من تقليل الشحنة وإلا غرق الجميع، فاقترعوا فكان يونس من المغلوبين، فرموه في البحر فالتقمه الحوت وهو فاعل ما يُلام عليه من فراره من دعوة قومه لما ضاق صدره. فلولا أنه كان من المسبّحين المكثرين من الصلاة والذكر والدعاء قبل البلاء لصار بطن الحوت قبراً له إلى يوم القيامة، ولما كان يُلهم قوله: لا إله إلا أنت سبحانك إني كنت من الظالمين، ولما استُجيب له؛ ولذا قال رسول الله ﷺ: «تعرّف إلى الله في الرخاء يعرفك في الشدة». فنبذناه بوجه الأرض العارية من الشجر وكل ظل، وهو كالفرخ المنتوف قد نضج لحمه من حرارة جوف الحوت، وأنبت عليه شجرة من قرع تظلّله بأوراقها الناعمة، حتى تماثل للشفاء وعاد إلى قومه فوجدهم مؤمنين لتوبة أحدثوها عند ظهور أمارات العذاب. وأرسلناه إلى أهل نينوى وكانوا مائة ألف أو يزيدون، فآمنوا بالله رباً وبالإسلام ديناً وبيونس نبياً ورسولاً، فكشفنا عنهم العذاب الذي أظلّهم، ومتّعناهم بالحياة إلى نهاية آجالهم.", "h": ["تقرير نبوة يونس ﵇ ورسالته، وضمن ذلك تقرير رسالة محمد ﷺ.", "مشروعية الركوب في السفن البحرية.", "مشروعية الاقتراع لفضّ النزاع في قسمة الأشياء ونحوها.", "فضل الصلاة والذكر والدعاء والتسبيح وعظيم نفعها عند الوقوع في البلاء.", "تقرير مبدأ «تعرّف إلى الله في الرخاء يعرفك في الشدة».", "بركة أكل اليقطين أي الدُّبّاء القرع، إذ كان النبي ﷺ يأكلها ويلتقطها من حافة القصعة.", "فضل قوم يونس إذ آمنوا كلهم، ولم تؤمن أمة بكاملها إلا هم."], "k": "«فلولا أنه كان من المسبّحين»… ما رصيدي من الذكر في الرخاء ليشفع لي يوم الشدة؟"}, {"lbl": "الآيات ١٤٩ – ١٦٠", "q": "فَٱسۡتَفۡتِهِمۡ أَلِرَبِّكَ ٱلۡبَنَاتُ وَلَهُمُ ٱلۡبَنُونَ ﴿١٤٩﴾ أَمۡ خَلَقۡنَا ٱلۡمَلَـٰٓئِكَةَ إِنَٰثٗا وَهُمۡ شَٰهِدُونَ ﴿١٥٠﴾ أَلَآ إِنَّهُم مِّنۡ إِفۡكِهِمۡ لَيَقُولُونَ ﴿١٥١﴾ وَلَدَ ٱللَّهُ وَإِنَّهُمۡ لَكَٰذِبُونَ ﴿١٥٢﴾ أَصۡطَفَى ٱلۡبَنَاتِ عَلَى ٱلۡبَنِينَ ﴿١٥٣﴾ مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ ﴿١٥٤﴾ أَفَلَا تَذَكَّرُونَ ﴿١٥٥﴾ أَمۡ لَكُمۡ سُلۡطَٰنٞ مُّبِينٞ ﴿١٥٦﴾ فَأۡتُواْ بِكِتَٰبِكُمۡ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٥٧﴾ وَجَعَلُواْ بَيۡنَهُۥ وَبَيۡنَ ٱلۡجِنَّةِ نَسَبٗاۚ وَلَقَدۡ عَلِمَتِ ٱلۡجِنَّةُ إِنَّهُمۡ لَمُحۡضَرُونَ ﴿١٥٨﴾ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ ﴿١٥٩﴾ إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ ﴿١٦٠﴾", "w": [["فاستفتهم", "استخبر كفار مكة توبيخاً لهم وتقريعاً."], ["ولهم البنون", "فيختصّون بالأفضل الأشرف."], ["ليقولون ولد الله", "لقولهم: الملائكة بنات الله."], ["أصطفى البنات", "أختار البنات على البنين؟"], ["أفلا تذكّرون", "أن الله تعالى منزّه عن الصاحبة والولد."], ["أم لكم سلطان مبين", "ألكم حجة واضحة على صحة ما تدّعون؟"], ["فأتوا بكتابكم", "الذي تحتجّون بما فيه، ومن أين لكم ذلك؟"], ["وجعلوا بينه وبين الجِنّة نسباً", "إذ قالوا: الملائكة بنات الله."], ["ولقد علمت الجِنّة إنهم لمحضرون", "في العذاب."], ["سبحان الله عما يصفون", "تنزيهاً لله عما يصفونه به من كون الملائكة بنات له."], ["إلا عباد الله المخلَصين", "فإنهم ينزّهون ربهم ولا يصفونه بالنقائص."]], "m": "بعد تقرير البعث والتوحيد والنبوة أراد تعالى إبطال فرية من أسوأ الفرى التي عرفتها الجزيرة، وهي قول بعضهم: إن الله أصهر إلى الجن فأنجب الملائكة وهم بنات الله، وهذا من إيحاء الشيطان لإغواء الإنسان. فقال لرسوله: استخبرهم موبّخاً: ألربك البنات ولهم البنون؟ أما تخجلون أن تنسبوا لكم الأسنى وهو البنون، وتجعلوا لله الأدنى وهو البنات؟ أم خلقنا الملائكة إناثاً وهم شاهدون؟ لم يشهدوا خلقهم فلِمَ يكذبون؟ ألا إنهم من كذبهم الذي اعتادوه ليقولون ولد الله وإنهم لكاذبون. أاختار البنات على البنين؟ ما لكم كيف تحكمون هذا الحكم الفاسد؟ أفلا تذكّرون أن الله منزّه عن الصاحبة والولد؟ أم لكم حجة قوية؟ والحجة القوية تكون بوحي من الله في كتاب أنزله، فأتوا بكتابكم إن كنتم صادقين، ومن أين لكم الكتاب وقد كفرتم بالقرآن الذي نزل لهدايتكم؟ وجعلوا بين الله وبين الجن نسباً بقولهم: أصهر الله إلى الجن فتزوّج سَرَوات الجن، إذ سألهم أبو بكر: من أمهات الملائكة؟ فقالوا: سروات الجن. ولقد علمت الجن إنهم لمحضرون في العذاب، فكيف يكون لهم نسب ويعذّبهم الله بالنار؟ فالنسيب يكرم نسيبه ولا يعذّبه. فنزّه الله نفسه: سبحان الله عما يصفون، إلا عباد الله المخلَصين فإنهم لا يصفون ربهم بصفات العباد العجزة المفتقرين إلى الزوجة والولد، ولا يكونون من المحضرين في النار.", "h": ["إبطال فرية بني مَلحان من العرب الذين زيّن لهم الشيطان فكرة الملائكة بنات الله، ووجود نسب بين الله تعالى وبين الجن.", "مشروعية دحض الباطل بأقوى الحجج وأصحّ البراهين.", "الحجة الأقوى ما كانت من وحي الله في كتاب من كتبه التي أوحى بها إلى رسله."], "k": "«سبحان الله عما يصفون»… هل أُنزّه ربي في ظني به كما أنزّهه بلساني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 327;
insert into public.tdb_cards(topic, i, body) select 327, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٣٩ – ١٤٨", "q": "وَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ ﴿١٣٩﴾ إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ﴿١٤٠﴾ فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ ﴿١٤١﴾ فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ ﴿١٤٢﴾ فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ ﴿١٤٣﴾ لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ﴿١٤٤﴾ ۞فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمٞ ﴿١٤٥﴾ وَأَنۢبَتۡنَا عَلَيۡهِ شَجَرَةٗ مِّن يَقۡطِينٖ ﴿١٤٦﴾ وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ يَزِيدُونَ ﴿١٤٧﴾ فَـَٔامَنُواْ فَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ ﴿١٤٨﴾", "w": [["وإن يونس لمن المرسلين", "يونس بن متّى الملقّب بذي النون من جملة المرسلين."], ["إذ أبق إلى الفلك المشحون", "هرب إلى السفينة المملوءة بالركاب."], ["فساهم فكان من المدحَضين", "اقترع مع ركاب السفينة فكان من المغلوبين."], ["فالتقمه الحوت وهو مُليم", "ابتلعه الحوت وهو آتٍ بما يُلام عليه."], ["للبث في بطنه إلى يوم يُبعثون", "لكان بطن الحوت قبراً له إلى يوم القيامة."], ["فنبذناه بالعراء", "ألقيناه من بطن الحوت بوجه الأرض."], ["وهو سقيم", "عليل كالفرخ المنتوف الريش."], ["شجرة من يقطين", "الدُّبّاء: القرع."], ["فآمنوا فمتّعناهم إلى حين", "آمن قومه عند معاينة أمارات العذاب فأبقاهم الله إلى آجالهم."]], "m": "ما زال السياق في ذكر من أنعم الله عليهم: وإن عبدنا يونس بن متّى ذا النون لمن المرسلين، إذ هرب من قومه لما لم يؤمنوا به وواعدهم العذاب فتأخر عنهم، فاستعجل فهرب من مدينتهم نينوى من أرض الموصل بالعراق، فوصل الميناء فوجد سفينة فركب، وكانت حمولتها أكبر من طاقتها فوقفت في عرض البحر، فرأى ربّانها أنه لا بد من تقليل الشحنة وإلا غرق الجميع، فاقترعوا فكان يونس من المغلوبين، فرموه في البحر فالتقمه الحوت وهو فاعل ما يُلام عليه من فراره من دعوة قومه لما ضاق صدره. فلولا أنه كان من المسبّحين المكثرين من الصلاة والذكر والدعاء قبل البلاء لصار بطن الحوت قبراً له إلى يوم القيامة، ولما كان يُلهم قوله: لا إله إلا أنت سبحانك إني كنت من الظالمين، ولما استُجيب له؛ ولذا قال رسول الله ﷺ: «تعرّف إلى الله في الرخاء يعرفك في الشدة». فنبذناه بوجه الأرض العارية من الشجر وكل ظل، وهو كالفرخ المنتوف قد نضج لحمه من حرارة جوف الحوت، وأنبت عليه شجرة من قرع تظلّله بأوراقها الناعمة، حتى تماثل للشفاء وعاد إلى قومه فوجدهم مؤمنين لتوبة أحدثوها عند ظهور أمارات العذاب. وأرسلناه إلى أهل نينوى وكانوا مائة ألف أو يزيدون، فآمنوا بالله رباً وبالإسلام ديناً وبيونس نبياً ورسولاً، فكشفنا عنهم العذاب الذي أظلّهم، ومتّعناهم بالحياة إلى نهاية آجالهم.", "h": ["تقرير نبوة يونس ﵇ ورسالته، وضمن ذلك تقرير رسالة محمد ﷺ.", "مشروعية الركوب في السفن البحرية.", "مشروعية الاقتراع لفضّ النزاع في قسمة الأشياء ونحوها.", "فضل الصلاة والذكر والدعاء والتسبيح وعظيم نفعها عند الوقوع في البلاء.", "تقرير مبدأ «تعرّف إلى الله في الرخاء يعرفك في الشدة».", "بركة أكل اليقطين أي الدُّبّاء القرع، إذ كان النبي ﷺ يأكلها ويلتقطها من حافة القصعة.", "فضل قوم يونس إذ آمنوا كلهم، ولم تؤمن أمة بكاملها إلا هم."], "k": "«فلولا أنه كان من المسبّحين»… ما رصيدي من الذكر في الرخاء ليشفع لي يوم الشدة؟"}, {"lbl": "الآيات ١٤٩ – ١٦٠", "q": "فَٱسۡتَفۡتِهِمۡ أَلِرَبِّكَ ٱلۡبَنَاتُ وَلَهُمُ ٱلۡبَنُونَ ﴿١٤٩﴾ أَمۡ خَلَقۡنَا ٱلۡمَلَـٰٓئِكَةَ إِنَٰثٗا وَهُمۡ شَٰهِدُونَ ﴿١٥٠﴾ أَلَآ إِنَّهُم مِّنۡ إِفۡكِهِمۡ لَيَقُولُونَ ﴿١٥١﴾ وَلَدَ ٱللَّهُ وَإِنَّهُمۡ لَكَٰذِبُونَ ﴿١٥٢﴾ أَصۡطَفَى ٱلۡبَنَاتِ عَلَى ٱلۡبَنِينَ ﴿١٥٣﴾ مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ ﴿١٥٤﴾ أَفَلَا تَذَكَّرُونَ ﴿١٥٥﴾ أَمۡ لَكُمۡ سُلۡطَٰنٞ مُّبِينٞ ﴿١٥٦﴾ فَأۡتُواْ بِكِتَٰبِكُمۡ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٥٧﴾ وَجَعَلُواْ بَيۡنَهُۥ وَبَيۡنَ ٱلۡجِنَّةِ نَسَبٗاۚ وَلَقَدۡ عَلِمَتِ ٱلۡجِنَّةُ إِنَّهُمۡ لَمُحۡضَرُونَ ﴿١٥٨﴾ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ ﴿١٥٩﴾ إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ ﴿١٦٠﴾", "w": [["فاستفتهم", "استخبر كفار مكة توبيخاً لهم وتقريعاً."], ["ولهم البنون", "فيختصّون بالأفضل الأشرف."], ["ليقولون ولد الله", "لقولهم: الملائكة بنات الله."], ["أصطفى البنات", "أختار البنات على البنين؟"], ["أفلا تذكّرون", "أن الله تعالى منزّه عن الصاحبة والولد."], ["أم لكم سلطان مبين", "ألكم حجة واضحة على صحة ما تدّعون؟"], ["فأتوا بكتابكم", "الذي تحتجّون بما فيه، ومن أين لكم ذلك؟"], ["وجعلوا بينه وبين الجِنّة نسباً", "إذ قالوا: الملائكة بنات الله."], ["ولقد علمت الجِنّة إنهم لمحضرون", "في العذاب."], ["سبحان الله عما يصفون", "تنزيهاً لله عما يصفونه به من كون الملائكة بنات له."], ["إلا عباد الله المخلَصين", "فإنهم ينزّهون ربهم ولا يصفونه بالنقائص."]], "m": "بعد تقرير البعث والتوحيد والنبوة أراد تعالى إبطال فرية من أسوأ الفرى التي عرفتها الجزيرة، وهي قول بعضهم: إن الله أصهر إلى الجن فأنجب الملائكة وهم بنات الله، وهذا من إيحاء الشيطان لإغواء الإنسان. فقال لرسوله: استخبرهم موبّخاً: ألربك البنات ولهم البنون؟ أما تخجلون أن تنسبوا لكم الأسنى وهو البنون، وتجعلوا لله الأدنى وهو البنات؟ أم خلقنا الملائكة إناثاً وهم شاهدون؟ لم يشهدوا خلقهم فلِمَ يكذبون؟ ألا إنهم من كذبهم الذي اعتادوه ليقولون ولد الله وإنهم لكاذبون. أاختار البنات على البنين؟ ما لكم كيف تحكمون هذا الحكم الفاسد؟ أفلا تذكّرون أن الله منزّه عن الصاحبة والولد؟ أم لكم حجة قوية؟ والحجة القوية تكون بوحي من الله في كتاب أنزله، فأتوا بكتابكم إن كنتم صادقين، ومن أين لكم الكتاب وقد كفرتم بالقرآن الذي نزل لهدايتكم؟ وجعلوا بين الله وبين الجن نسباً بقولهم: أصهر الله إلى الجن فتزوّج سَرَوات الجن، إذ سألهم أبو بكر: من أمهات الملائكة؟ فقالوا: سروات الجن. ولقد علمت الجن إنهم لمحضرون في العذاب، فكيف يكون لهم نسب ويعذّبهم الله بالنار؟ فالنسيب يكرم نسيبه ولا يعذّبه. فنزّه الله نفسه: سبحان الله عما يصفون، إلا عباد الله المخلَصين فإنهم لا يصفون ربهم بصفات العباد العجزة المفتقرين إلى الزوجة والولد، ولا يكونون من المحضرين في النار.", "h": ["إبطال فرية بني مَلحان من العرب الذين زيّن لهم الشيطان فكرة الملائكة بنات الله، ووجود نسب بين الله تعالى وبين الجن.", "مشروعية دحض الباطل بأقوى الحجج وأصحّ البراهين.", "الحجة الأقوى ما كانت من وحي الله في كتاب من كتبه التي أوحى بها إلى رسله."], "k": "«سبحان الله عما يصفون»… هل أُنزّه ربي في ظني به كما أنزّهه بلساني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (328, 37, 161, 182, 'سورة الصافات ١٦١ – ١٨٢', 'الصافات: وإن جندنا لهم الغالبون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 328) = $j$[{"lbl": "الآيات ١٦١ – ١٧٠", "q": "فَإِنَّكُمۡ وَمَا تَعۡبُدُونَ ﴿١٦١﴾ مَآ أَنتُمۡ عَلَيۡهِ بِفَٰتِنِينَ ﴿١٦٢﴾ إِلَّا مَنۡ هُوَ صَالِ ٱلۡجَحِيمِ ﴿١٦٣﴾ وَمَامِنَّآ إِلَّا لَهُۥ مَقَامٞ مَّعۡلُومٞ ﴿١٦٤﴾ وَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ ﴿١٦٥﴾ وَإِنَّا لَنَحۡنُ ٱلۡمُسَبِّحُونَ ﴿١٦٦﴾ وَإِن كَانُواْ لَيَقُولُونَ ﴿١٦٧﴾ لَوۡ أَنَّ عِندَنَا ذِكۡرٗا مِّنَ ٱلۡأَوَّلِينَ ﴿١٦٨﴾ لَكُنَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ ﴿١٦٩﴾ فَكَفَرُواْ بِهِۦۖ فَسَوۡفَ يَعۡلَمُونَ ﴿١٧٠﴾", "w": [["وما تعبدون", "من الأصنام."], ["إلا من هو صالِ الجحيم", "مقدَّر له عذاب النار."], ["إلا له مقام معلوم", "مكان في السماء يعبد الله فيه لا يتعدّاه."], ["وإنا لنحن الصافّون", "أقدامنا في الصلاة."], ["وإنا لنحن المسبّحون", "المنزّهون الله تعالى عما لا يليق به."], ["وإن كانوا ليقولون", "كفار مكة."], ["لو أن عندنا ذكراً", "كتاباً من كتب الأمم السابقة."], ["فكفروا به", "بالكتاب الذي جاءهم وهو القرآن."], ["فسوف يعلمون", "عاقبة كفرهم إن لم يتوبوا فيؤمنوا ويوحّدوا."]], "m": "ما زال السياق في إبطال باطل المشركين: فإنكم أيها المشركون وما تعبدون من أصنام ما أنتم بمضلّين أحداً إلا من هو صالِ الجحيم، كتبنا عليه ذلك في كتاب المقادير، فهو لا بد عامل بما يوجب له النار، فهذا قد يفتتن بكم فيضل بضلالكم. وقوله: وما منا إلا له مقام معلوم، وإنا لنحن الصافّون، وإنا لنحن المسبّحون، قول جبريل للنبي ﷺ؛ أخبر بأن الملائكة تصف في السماء للصلاة كما يصف المؤمنون، وأنهم يسبّحون الله الليل والنهار، وقد أخبر النبي ﷺ أنه ما من موضع شبر في السماء إلا عليه ملك ساجد أو قائم. وإن كان مشركو العرب ليقولون: لو أن عندنا كتاباً من كتب الأولين كالتوراة والإنجيل لكنا عباد الله المخلَصين نعبده ونوحّده. فردّ تعالى على هذا التمني الكاذب: فكفروا بالكتاب الذي جاءهم وهو القرآن، فسوف يعلمون عاقبة تكذيبهم إن لم يتوبوا، وهو هلاكهم وخسرانهم.", "h": ["تقرير عقيدة القضاء والقدر، إذ من كتب الله عليه النار فسوف يصلاها.", "تقرير عبودية الملائكة وطاعتهم لله، وأنهم لا يتجاوزون ما حدّ الله تعالى لهم.", "فضل الصفوف في الصلاة وفضل تسويتها.", "بيان كذب المشركين إذ كانوا يدّعون أنهم لو أُنزل عليهم كتاب كما أُنزل على من قبلهم لكانوا عباد الله المخلَصين.", "تهديد الله تعالى للمشركين على كذبهم بقوله: فسوف يعلمون."], "k": "«لو أن عندنا ذكراً… لكنا عباد الله المخلَصين»… الذكر عندي الآن؛ فما عذري؟"}, {"lbl": "الآيات ١٧١ – ١٨٢", "q": "وَلَقَدۡ سَبَقَتۡ كَلِمَتُنَا لِعِبَادِنَا ٱلۡمُرۡسَلِينَ ﴿١٧١﴾ إِنَّهُمۡ لَهُمُ ٱلۡمَنصُورُونَ ﴿١٧٢﴾ وَإِنَّ جُندَنَا لَهُمُ ٱلۡغَٰلِبُونَ ﴿١٧٣﴾ فَتَوَلَّ عَنۡهُمۡ حَتَّىٰ حِينٖ ﴿١٧٤﴾ وَأَبۡصِرۡهُمۡ فَسَوۡفَ يُبۡصِرُونَ ﴿١٧٥﴾ أَفَبِعَذَابِنَا يَسۡتَعۡجِلُونَ ﴿١٧٦﴾ فَإِذَا نَزَلَ بِسَاحَتِهِمۡ فَسَآءَ صَبَاحُ ٱلۡمُنذَرِينَ ﴿١٧٧﴾ وَتَوَلَّ عَنۡهُمۡ حَتَّىٰ حِينٖ ﴿١٧٨﴾ وَأَبۡصِرۡ فَسَوۡفَ يُبۡصِرُونَ ﴿١٧٩﴾ سُبۡحَٰنَ رَبِّكَ رَبِّ ٱلۡعِزَّةِ عَمَّا يَصِفُونَ ﴿١٨٠﴾ وَسَلَٰمٌ عَلَى ٱلۡمُرۡسَلِينَ ﴿١٨١﴾ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٨٢﴾", "w": [["سبقت كلمتنا", "هي قوله تعالى: لأغلبنّ أنا ورسلي."], ["وإن جندنا لهم الغالبون", "للكافرين بالحجة والنصرة."], ["فتولَّ عنهم حتى حين", "أعرض عنهم حتى تؤمر فيهم بالقتال."], ["وأبصرهم", "أنظِرهم."], ["وتولَّ عنهم", "أعرض عنهم."], ["سبحان ربك", "تنزيهاً لربك يا محمد."], ["عما يصفون", "عما يصفه به هؤلاء المشركون من الصاحبة والولد."], ["وسلام على المرسلين", "أمَنَة من الله لهم في الدنيا والآخرة."], ["والحمد لله رب العالمين", "الثناء بالجميل خالص لله رب الثقلين على نصر أوليائه وإهلاك أعدائه."]], "m": "لما ختم السياق بتهديد الكافرين أخبر تعالى رسوله بما يطمئنه على نصره: ولقد سبقت كلمتنا لعبادنا المرسلين: إنهم لهم المنصورون، وإن جندنا لهم الغالبون بالحجة والبرهان وبالرمح والسنان. وأمره أن يُعرض عن المشركين حتى حين يأمره فيهم بأمر أو ينزل بهم بأساً، وأن يُنظرهم فسوف يبصرون ما ينزل بهم من عذاب الله في الدنيا والآخرة. ثم أنكر عليهم استعجالهم العذاب الدال على سفههم، إذ ما يستعجل العذاب إلا أحمق جاهل، فإذا نزل بفناء دارهم فبئس صباحهم صباحَ هلاكهم ودمارهم. ثم أمره مرة أخرى أن يتولّى عنهم وينتظر ما يحلّ بهم، وفي الآية من التهديد ما لا يُقدَر قدره. وأخيراً نزّه تعالى نفسه عما يصفه به المشركون، وسلّم على المرسلين، وحمد نفسه: سبحان ربك يا محمد رب العزة ومالكها، يُعزّ بها من يشاء ويُذلّ من يشاء، عما يصفون من الصاحبة والولد والشريك، وسلام منا على المرسلين وأنت منهم، والحمد لله رب العالمين على نصره أولياءه وإهلاكه أعداءه.", "h": ["تقرير النبوة المحمدية.", "وعد الله تعالى لرسوله بالنصر، وقد أنجزه ما وعده، والحمد لله.", "استحباب ختم الدعاء أو الكلام بقراءة: «سبحان ربك رب العزة عما يصفون وسلام على المرسلين والحمد لله رب العالمين» لورود ذلك في السنة."], "k": "«سبحان ربك رب العزة عما يصفون»… أختم بها مجلسي؛ فهل يسبقها قلب حاضر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 328;
