insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (329, 38, 1, 20, 'سورة ص ١ – ٢٠', 'ص: بل الذين كفروا في عزة وشقاق', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 329) = $j$[{"lbl": "الآيات ١ – ١١", "q": "صٓۚ وَٱلۡقُرۡءَانِ ذِي ٱلذِّكۡرِ ﴿١﴾ بَلِ ٱلَّذِينَ كَفَرُواْ فِي عِزَّةٖ وَشِقَاقٖ ﴿٢﴾ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ فَنَادَواْ وَّلَاتَ حِينَ مَنَاصٖ ﴿٣﴾ وَعَجِبُوٓاْ أَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا سَٰحِرٞ كَذَّابٌ ﴿٤﴾ أَجَعَلَ ٱلۡأٓلِهَةَ إِلَٰهٗا وَٰحِدًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عُجَابٞ ﴿٥﴾ وَٱنطَلَقَ ٱلۡمَلَأُ مِنۡهُمۡ أَنِ ٱمۡشُواْ وَٱصۡبِرُواْ عَلَىٰٓ ءَالِهَتِكُمۡۖ إِنَّ هَٰذَا لَشَيۡءٞ يُرَادُ ﴿٦﴾ مَا سَمِعۡنَا بِهَٰذَا فِي ٱلۡمِلَّةِ ٱلۡأٓخِرَةِ إِنۡ هَٰذَآ إِلَّا ٱخۡتِلَٰقٌ ﴿٧﴾ أَءُنزِلَ عَلَيۡهِ ٱلذِّكۡرُ مِنۢ بَيۡنِنَاۚ بَلۡ هُمۡ فِي شَكّٖ مِّن ذِكۡرِيۚ بَل لَّمَّا يَذُوقُواْ عَذَابِ ﴿٨﴾ أَمۡ عِندَهُمۡ خَزَآئِنُ رَحۡمَةِ رَبِّكَ ٱلۡعَزِيزِ ٱلۡوَهَّابِ ﴿٩﴾ أَمۡ لَهُم مُّلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ فَلۡيَرۡتَقُواْ فِي ٱلۡأَسۡبَٰبِ ﴿١٠﴾ جُندٞ مَّا هُنَالِكَ مَهۡزُومٞ مِّنَ ٱلۡأَحۡزَابِ ﴿١١﴾", "w": [["ص", "أحد الحروف المقطعة، يُكتب «ص» ويُقرأ «صاد»، الله أعلم بمراده به."], ["والقرآن ذي الذكر", "أقسم بالقرآن ذي الذكر، إذ به يُذكر الله تعالى، ما الأمر كما يقول الكافرون من أن النبي ساحر وشاعر وكاذب."], ["في عزة وشقاق", "أهل مكة في عزة نفس وشقاق وعداوة مع النبي والمؤمنين، وإلا فهم يعلمون براءته مما قالوا فيه."], ["من قرن", "كثيراً من الأمم الماضية أهلكناهم."], ["فنادوا ولات حين مناص", "صرخوا واستغاثوا وليس الوقت وقت مهرب ولا نجاة."], ["ساحر كذّاب", "لما يظهره من الخوارق، ولما يُسنده إلى الله من الإرسال والإنزال."], ["أجعل الآلهة إلهاً واحداً", "لما قال لهم: قولوا لا إله إلا الله، قالوا: كيف يسع الخلائق إله واحد؟"], ["لشيء عُجاب", "أمر عجيب."], ["وانطلق الملأ منهم أن امشوا", "خرجوا من بيت أبي طالب حيث كانوا مجتمعين بالنبي ﷺ وسمعوا منه: قولوا لا إله إلا الله."], ["في الملة الآخرة", "ملة عيسى ﵇."], ["إلا اختلاق", "كذب مختلَق."], ["أأُنزل عليه الذكر من بيننا", "كيف يكون ذلك وليس هو بأكبر منا ولا أشرف؟"], ["بل لمّا يذوقوا عذاب", "لم يذوقوا عذابي، إذ لو ذاقوه لما كذّبوا بل آمنوا."], ["أم عندهم خزائن رحمة ربك", "من النبوة وغيرها فيعطوا منها من شاؤوا ويحرموا من شاؤوا."], ["فليرتقوا في الأسباب", "الموصلة إلى السماء فيمنعوا الوحي النازل على نبينا محمد ﷺ، وأنّى لهم ذلك."], ["جند ما هنالك مهزوم", "جند حقير في تكذيبهم لك، مهزوم أمامك في بدر."], ["من الأحزاب", "من الأمم الماضية التي تحزّبت على رسلها فأهلكها الله."]], "m": "أما «ص» فأحد حروف الهجاء، ومذهب السلف فيه أن يقال: الله أعلم بمراده به، إذ هو من المتشابه الذي يجب الإيمان به ويوكَل معناه إلى من أنزله. والقرآن ذي الذكر قسم، وجوابه محذوف تقديره: ما الأمر كما يقول المشركون من أن النبي ﷺ ساحر وشاعر وكاذب، بل هم في عزة نفس وكبرياء وعداوة مع النبي والمؤمنين، فحملهم ذلك على ما قالوا، وإلا فهم يعلمون يقيناً أنه أبعد الناس عن السحر والشعر والكذب والجنون. وكم أهلكنا قبلهم من الأمم بتكذيبها لرسلها، فلما جاءهم العذاب نادوا مستغيثين وليست الساعة ساعة نجاة، فلِمَ لا يعتبر مشركو مكة؟ لم يعتبروا، بل عجبوا أن جاءهم منذر منهم، وقالوا: ساحر كذّاب، أجعل الآلهة إلهاً واحداً؟ كيف يسع العباد إله واحد؟ لأنهم قاسوا الغائب وهو الله على الشاهد وهو الإنسان الضعيف فوقعوا في أفحش خطأ. وذلك لما اجتمعوا بالرسول ﷺ في منزل عمه أبي طالب لمفاوضته، فلما قال لهم: قولوا لا إله إلا الله، قاموا يمشون ويقولون: امشوا واصبروا على عبادة آلهتكم، إن هذه الدعوة لشيء كبير يُراد منا إمضاؤه لصالح غيرنا، ما سمعنا بالتوحيد في الدين الأخير الذي جاء به عيسى ﵇، ما هذا إلا كذب اختلقه، أأُنزل عليه القرآن من بيننا وليس بأكبرنا سناً ولا أشرفنا نسباً؟ بل لم يكن بهم جهل بصدقه، وإنما حملهم على ذلك شكّهم في القرآن، ثم إنهم لم يذوقوا عذاب الله، ولو ذاقوه ما كذّبوا، وسوف يذوقونه ولا ينفعهم يومئذ إيمان. أم عندهم خزائن رحمة ربك العزيز الوهّاب فيعطوا النبوة من شاؤوا ويمنعوها من شاؤوا؟ لا، فلِمَ ينكرون هبة الله لمحمد؟ أم لهم ملك السماوات والأرض وما بينهما؟ فليرتقوا في الأسباب سبباً بعد سبب حتى ينتهوا إلى السماء السابعة فيمنعوا الوحي، ومن أين لهم ذلك وهم الضعفاء؟ إنهم جند حقير من جملة أحزاب الباطل، مهزوم هنالك ببدر ويوم الفتح بإذن الله.", "h": ["لله تعالى أن يُقسم بما يشاء، بخلاف العبد لا يُقسم إلا بربه تعالى.", "بيان ما كان عليه المشركون من كبرياء وعداء للنبي ﷺ.", "بيان جهل المشركين في استنكارهم لـ«لا إله إلا الله محمد رسول الله».", "تحدّي الرب تعالى للمشركين إظهاراً لعجزهم، ودعوته لهم إلى النزول إلى الحق وقبوله.", "إخبار القرآن بالغيب وصدقه في ذلك.", "ذمّ كلمة الأحزاب ومدلولها، إذ لا تأتي الأحزاب بخير."], "k": "«بل الذين كفروا في عزة وشقاق»… كم مرة ردّني الكِبر عن حقٍّ أعرفه؟"}, {"lbl": "الآيات ١٢ – ٢٠", "q": "كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ ﴿١٢﴾ وَثَمُودُ وَقَوۡمُ لُوطٖ وَأَصۡحَٰبُ لۡـَٔيۡكَةِۚ أُوْلَـٰٓئِكَ ٱلۡأَحۡزَابُ ﴿١٣﴾ إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ ﴿١٤﴾ وَمَا يَنظُرُ هَـٰٓؤُلَآءِ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ مَّا لَهَا مِن فَوَاقٖ ﴿١٥﴾ وَقَالُواْ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبۡلَ يَوۡمِ ٱلۡحِسَابِ ﴿١٦﴾ ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ ﴿١٧﴾ إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ ﴿١٨﴾ وَٱلطَّيۡرَ مَحۡشُورَةٗۖ كُلّٞ لَّهُۥٓ أَوَّابٞ ﴿١٩﴾ وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَيۡنَٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ ﴿٢٠﴾", "w": [["كذّبت قبلهم", "قبل هؤلاء المشركين من قريش."], ["وفرعون ذو الأوتاد", "صاحب أوتاد أربعة يشدّ إليها من أراد تعذيبه."], ["وأصحاب الأيكة", "الغيضة، وهم قوم شعيب."], ["إن كلٌّ إلا كذّب الرسل", "ما كل واحد منهم إلا كذّب الرسل ولم يصدّقهم."], ["فحقّ عقاب", "وجبت عقوبتي عليهم."], ["صيحة واحدة", "نفخة إسرافيل في الصور."], ["ما لها من فواق", "ليس لها من فتور ولا انقطاع حتى تهلك كل شيء."], ["عجّل لنا قِطّنا", "صكّ أعمالنا لنرى ما أعددت لنا، إذ القِطّ الكتاب."], ["ذا الأيد", "القوة والشدة في طاعة الله."], ["إنه أوّاب", "رجّاع إلى الله في كل أموره."], ["بالعشيّ والإشراق", "بالمساء بعد العصر إلى الغروب، والإشراق من طلوع الشمس إلى ارتفاع الضحى."], ["والطير محشورة", "والطيور مجموعة."], ["وآتيناه الحكمة وفصل الخطاب", "الحكمة: الإصابة في الأمور والسداد فيها، وفصل الخطاب: الفقه في القضاء، ومنه البيّنة على المدّعي واليمين على من أنكر."]], "m": "السياق في تسلية النبي ﷺ وتهديد المشركين لعلهم يتوبون: كذّبت قبل قومك يا محمد قوم نوح وعاد وفرعون صاحب الأوتاد التي كان يشدّ إليها من أراد تعذيبه كأعواد المشانق، وثمود وقوم لوط وأصحاب الأيكة قوم شعيب، أولئك الطوائف الكافرة الهالكة، ما كل واحدة منها إلا كذّبت الرسل فوجب عقابي لهم فعاقبتهم. وما ينتظر هؤلاء إلا صيحة واحدة ما لها من فتور حتى يهلك كل شيء ولا يبقى إلا وجه الله ذو الجلال والإكرام. ولما نزل «فأما من أوتي كتابه بيمينه» من سورة الحاقة قال غلاة الكافرين كأبي جهل استهزاءً: ربنا عجّل لنا كتابنا لنرى ما فيه قبل يوم الحساب، وهم لا يؤمنون ببعث ولا جزاء. فقال تعالى لرسوله: اصبر على ما يقولون واذكر عبدنا داود ذا القوة في دين الله، إنه رجّاع إلى الله، اذكره لتتأسّى به في صبره وقوته في الحق. ثم بيّن إنعامه على داود لتعظم الرغبة في الاقتداء به: إنا سخّرنا الجبال معه إذا سبّح في المساء والضحى ردّدت تسبيحه كرامة له، وسخّرنا الطير مجموعة تردّد التسبيح معه، كلٌّ له أوّاب يسبّح الله، وقوّينا ملكه بمنحه كل أسباب القوة المادية والروحية، وآتيناه الحكمة وهي النبوة والإصابة في الأمور قولاً وفعلاً، وفصل الخطاب وهو حسن القضاء والبصيرة فيه والبيان الشافي في كلامه. فبه اقتدِ يا رسولنا.", "h": ["تسلية الرسول ﷺ وحمله على الصبر على أذى قريش وتكذيبها وعنادها.", "تهديد قريش إذا أصرّت على التكذيب بأشدّ أنواع العقوبات.", "بيان استهزاء المشركين واستخفافهم بأخبار الله تعالى وشرائعه.", "مشروعية الأسوة والاقتداء بالصالحين.", "بيان آية تسخير الله تعالى الجبال والطير لداود تسبّح الله تعالى معه.", "حسن صوت داود في قراءته وتسبيحه.", "مشروعية صلاة الإشراق والضحى."], "k": "«اصبر على ما يقولون واذكر عبدنا داود… إنه أوّاب»… الصبر يقوى بالرجوع إلى الله؛ فهل أرجع إليه كلما ضاق صدري؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 329;
insert into public.tdb_cards(topic, i, body) select 329, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١١", "q": "صٓۚ وَٱلۡقُرۡءَانِ ذِي ٱلذِّكۡرِ ﴿١﴾ بَلِ ٱلَّذِينَ كَفَرُواْ فِي عِزَّةٖ وَشِقَاقٖ ﴿٢﴾ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ فَنَادَواْ وَّلَاتَ حِينَ مَنَاصٖ ﴿٣﴾ وَعَجِبُوٓاْ أَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا سَٰحِرٞ كَذَّابٌ ﴿٤﴾ أَجَعَلَ ٱلۡأٓلِهَةَ إِلَٰهٗا وَٰحِدًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عُجَابٞ ﴿٥﴾ وَٱنطَلَقَ ٱلۡمَلَأُ مِنۡهُمۡ أَنِ ٱمۡشُواْ وَٱصۡبِرُواْ عَلَىٰٓ ءَالِهَتِكُمۡۖ إِنَّ هَٰذَا لَشَيۡءٞ يُرَادُ ﴿٦﴾ مَا سَمِعۡنَا بِهَٰذَا فِي ٱلۡمِلَّةِ ٱلۡأٓخِرَةِ إِنۡ هَٰذَآ إِلَّا ٱخۡتِلَٰقٌ ﴿٧﴾ أَءُنزِلَ عَلَيۡهِ ٱلذِّكۡرُ مِنۢ بَيۡنِنَاۚ بَلۡ هُمۡ فِي شَكّٖ مِّن ذِكۡرِيۚ بَل لَّمَّا يَذُوقُواْ عَذَابِ ﴿٨﴾ أَمۡ عِندَهُمۡ خَزَآئِنُ رَحۡمَةِ رَبِّكَ ٱلۡعَزِيزِ ٱلۡوَهَّابِ ﴿٩﴾ أَمۡ لَهُم مُّلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ فَلۡيَرۡتَقُواْ فِي ٱلۡأَسۡبَٰبِ ﴿١٠﴾ جُندٞ مَّا هُنَالِكَ مَهۡزُومٞ مِّنَ ٱلۡأَحۡزَابِ ﴿١١﴾", "w": [["ص", "أحد الحروف المقطعة، يُكتب «ص» ويُقرأ «صاد»، الله أعلم بمراده به."], ["والقرآن ذي الذكر", "أقسم بالقرآن ذي الذكر، إذ به يُذكر الله تعالى، ما الأمر كما يقول الكافرون من أن النبي ساحر وشاعر وكاذب."], ["في عزة وشقاق", "أهل مكة في عزة نفس وشقاق وعداوة مع النبي والمؤمنين، وإلا فهم يعلمون براءته مما قالوا فيه."], ["من قرن", "كثيراً من الأمم الماضية أهلكناهم."], ["فنادوا ولات حين مناص", "صرخوا واستغاثوا وليس الوقت وقت مهرب ولا نجاة."], ["ساحر كذّاب", "لما يظهره من الخوارق، ولما يُسنده إلى الله من الإرسال والإنزال."], ["أجعل الآلهة إلهاً واحداً", "لما قال لهم: قولوا لا إله إلا الله، قالوا: كيف يسع الخلائق إله واحد؟"], ["لشيء عُجاب", "أمر عجيب."], ["وانطلق الملأ منهم أن امشوا", "خرجوا من بيت أبي طالب حيث كانوا مجتمعين بالنبي ﷺ وسمعوا منه: قولوا لا إله إلا الله."], ["في الملة الآخرة", "ملة عيسى ﵇."], ["إلا اختلاق", "كذب مختلَق."], ["أأُنزل عليه الذكر من بيننا", "كيف يكون ذلك وليس هو بأكبر منا ولا أشرف؟"], ["بل لمّا يذوقوا عذاب", "لم يذوقوا عذابي، إذ لو ذاقوه لما كذّبوا بل آمنوا."], ["أم عندهم خزائن رحمة ربك", "من النبوة وغيرها فيعطوا منها من شاؤوا ويحرموا من شاؤوا."], ["فليرتقوا في الأسباب", "الموصلة إلى السماء فيمنعوا الوحي النازل على نبينا محمد ﷺ، وأنّى لهم ذلك."], ["جند ما هنالك مهزوم", "جند حقير في تكذيبهم لك، مهزوم أمامك في بدر."], ["من الأحزاب", "من الأمم الماضية التي تحزّبت على رسلها فأهلكها الله."]], "m": "أما «ص» فأحد حروف الهجاء، ومذهب السلف فيه أن يقال: الله أعلم بمراده به، إذ هو من المتشابه الذي يجب الإيمان به ويوكَل معناه إلى من أنزله. والقرآن ذي الذكر قسم، وجوابه محذوف تقديره: ما الأمر كما يقول المشركون من أن النبي ﷺ ساحر وشاعر وكاذب، بل هم في عزة نفس وكبرياء وعداوة مع النبي والمؤمنين، فحملهم ذلك على ما قالوا، وإلا فهم يعلمون يقيناً أنه أبعد الناس عن السحر والشعر والكذب والجنون. وكم أهلكنا قبلهم من الأمم بتكذيبها لرسلها، فلما جاءهم العذاب نادوا مستغيثين وليست الساعة ساعة نجاة، فلِمَ لا يعتبر مشركو مكة؟ لم يعتبروا، بل عجبوا أن جاءهم منذر منهم، وقالوا: ساحر كذّاب، أجعل الآلهة إلهاً واحداً؟ كيف يسع العباد إله واحد؟ لأنهم قاسوا الغائب وهو الله على الشاهد وهو الإنسان الضعيف فوقعوا في أفحش خطأ. وذلك لما اجتمعوا بالرسول ﷺ في منزل عمه أبي طالب لمفاوضته، فلما قال لهم: قولوا لا إله إلا الله، قاموا يمشون ويقولون: امشوا واصبروا على عبادة آلهتكم، إن هذه الدعوة لشيء كبير يُراد منا إمضاؤه لصالح غيرنا، ما سمعنا بالتوحيد في الدين الأخير الذي جاء به عيسى ﵇، ما هذا إلا كذب اختلقه، أأُنزل عليه القرآن من بيننا وليس بأكبرنا سناً ولا أشرفنا نسباً؟ بل لم يكن بهم جهل بصدقه، وإنما حملهم على ذلك شكّهم في القرآن، ثم إنهم لم يذوقوا عذاب الله، ولو ذاقوه ما كذّبوا، وسوف يذوقونه ولا ينفعهم يومئذ إيمان. أم عندهم خزائن رحمة ربك العزيز الوهّاب فيعطوا النبوة من شاؤوا ويمنعوها من شاؤوا؟ لا، فلِمَ ينكرون هبة الله لمحمد؟ أم لهم ملك السماوات والأرض وما بينهما؟ فليرتقوا في الأسباب سبباً بعد سبب حتى ينتهوا إلى السماء السابعة فيمنعوا الوحي، ومن أين لهم ذلك وهم الضعفاء؟ إنهم جند حقير من جملة أحزاب الباطل، مهزوم هنالك ببدر ويوم الفتح بإذن الله.", "h": ["لله تعالى أن يُقسم بما يشاء، بخلاف العبد لا يُقسم إلا بربه تعالى.", "بيان ما كان عليه المشركون من كبرياء وعداء للنبي ﷺ.", "بيان جهل المشركين في استنكارهم لـ«لا إله إلا الله محمد رسول الله».", "تحدّي الرب تعالى للمشركين إظهاراً لعجزهم، ودعوته لهم إلى النزول إلى الحق وقبوله.", "إخبار القرآن بالغيب وصدقه في ذلك.", "ذمّ كلمة الأحزاب ومدلولها، إذ لا تأتي الأحزاب بخير."], "k": "«بل الذين كفروا في عزة وشقاق»… كم مرة ردّني الكِبر عن حقٍّ أعرفه؟"}, {"lbl": "الآيات ١٢ – ٢٠", "q": "كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ ﴿١٢﴾ وَثَمُودُ وَقَوۡمُ لُوطٖ وَأَصۡحَٰبُ لۡـَٔيۡكَةِۚ أُوْلَـٰٓئِكَ ٱلۡأَحۡزَابُ ﴿١٣﴾ إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ ﴿١٤﴾ وَمَا يَنظُرُ هَـٰٓؤُلَآءِ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ مَّا لَهَا مِن فَوَاقٖ ﴿١٥﴾ وَقَالُواْ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبۡلَ يَوۡمِ ٱلۡحِسَابِ ﴿١٦﴾ ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ ﴿١٧﴾ إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ ﴿١٨﴾ وَٱلطَّيۡرَ مَحۡشُورَةٗۖ كُلّٞ لَّهُۥٓ أَوَّابٞ ﴿١٩﴾ وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَيۡنَٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ ﴿٢٠﴾", "w": [["كذّبت قبلهم", "قبل هؤلاء المشركين من قريش."], ["وفرعون ذو الأوتاد", "صاحب أوتاد أربعة يشدّ إليها من أراد تعذيبه."], ["وأصحاب الأيكة", "الغيضة، وهم قوم شعيب."], ["إن كلٌّ إلا كذّب الرسل", "ما كل واحد منهم إلا كذّب الرسل ولم يصدّقهم."], ["فحقّ عقاب", "وجبت عقوبتي عليهم."], ["صيحة واحدة", "نفخة إسرافيل في الصور."], ["ما لها من فواق", "ليس لها من فتور ولا انقطاع حتى تهلك كل شيء."], ["عجّل لنا قِطّنا", "صكّ أعمالنا لنرى ما أعددت لنا، إذ القِطّ الكتاب."], ["ذا الأيد", "القوة والشدة في طاعة الله."], ["إنه أوّاب", "رجّاع إلى الله في كل أموره."], ["بالعشيّ والإشراق", "بالمساء بعد العصر إلى الغروب، والإشراق من طلوع الشمس إلى ارتفاع الضحى."], ["والطير محشورة", "والطيور مجموعة."], ["وآتيناه الحكمة وفصل الخطاب", "الحكمة: الإصابة في الأمور والسداد فيها، وفصل الخطاب: الفقه في القضاء، ومنه البيّنة على المدّعي واليمين على من أنكر."]], "m": "السياق في تسلية النبي ﷺ وتهديد المشركين لعلهم يتوبون: كذّبت قبل قومك يا محمد قوم نوح وعاد وفرعون صاحب الأوتاد التي كان يشدّ إليها من أراد تعذيبه كأعواد المشانق، وثمود وقوم لوط وأصحاب الأيكة قوم شعيب، أولئك الطوائف الكافرة الهالكة، ما كل واحدة منها إلا كذّبت الرسل فوجب عقابي لهم فعاقبتهم. وما ينتظر هؤلاء إلا صيحة واحدة ما لها من فتور حتى يهلك كل شيء ولا يبقى إلا وجه الله ذو الجلال والإكرام. ولما نزل «فأما من أوتي كتابه بيمينه» من سورة الحاقة قال غلاة الكافرين كأبي جهل استهزاءً: ربنا عجّل لنا كتابنا لنرى ما فيه قبل يوم الحساب، وهم لا يؤمنون ببعث ولا جزاء. فقال تعالى لرسوله: اصبر على ما يقولون واذكر عبدنا داود ذا القوة في دين الله، إنه رجّاع إلى الله، اذكره لتتأسّى به في صبره وقوته في الحق. ثم بيّن إنعامه على داود لتعظم الرغبة في الاقتداء به: إنا سخّرنا الجبال معه إذا سبّح في المساء والضحى ردّدت تسبيحه كرامة له، وسخّرنا الطير مجموعة تردّد التسبيح معه، كلٌّ له أوّاب يسبّح الله، وقوّينا ملكه بمنحه كل أسباب القوة المادية والروحية، وآتيناه الحكمة وهي النبوة والإصابة في الأمور قولاً وفعلاً، وفصل الخطاب وهو حسن القضاء والبصيرة فيه والبيان الشافي في كلامه. فبه اقتدِ يا رسولنا.", "h": ["تسلية الرسول ﷺ وحمله على الصبر على أذى قريش وتكذيبها وعنادها.", "تهديد قريش إذا أصرّت على التكذيب بأشدّ أنواع العقوبات.", "بيان استهزاء المشركين واستخفافهم بأخبار الله تعالى وشرائعه.", "مشروعية الأسوة والاقتداء بالصالحين.", "بيان آية تسخير الله تعالى الجبال والطير لداود تسبّح الله تعالى معه.", "حسن صوت داود في قراءته وتسبيحه.", "مشروعية صلاة الإشراق والضحى."], "k": "«اصبر على ما يقولون واذكر عبدنا داود… إنه أوّاب»… الصبر يقوى بالرجوع إلى الله؛ فهل أرجع إليه كلما ضاق صدري؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (330, 38, 21, 29, 'سورة ص ٢١ – ٢٩', 'ص: نبأ الخصم ويا داود إنا جعلناك خليفة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 330) = $j$[{"lbl": "الآيات ٢١ – ٢٥", "q": "۞وَهَلۡ أَتَىٰكَ نَبَؤُاْ ٱلۡخَصۡمِ إِذۡ تَسَوَّرُواْ ٱلۡمِحۡرَابَ ﴿٢١﴾ إِذۡ دَخَلُواْ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنۡهُمۡۖ قَالُواْ لَا تَخَفۡۖ خَصۡمَانِ بَغَىٰ بَعۡضُنَا عَلَىٰ بَعۡضٖ فَٱحۡكُم بَيۡنَنَا بِٱلۡحَقِّ وَلَا تُشۡطِطۡ وَٱهۡدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ ﴿٢٢﴾ إِنَّ هَٰذَآ أَخِي لَهُۥ تِسۡعٞ وَتِسۡعُونَ نَعۡجَةٗ وَلِيَ نَعۡجَةٞ وَٰحِدَةٞ فَقَالَ أَكۡفِلۡنِيهَا وَعَزَّنِي فِي ٱلۡخِطَابِ ﴿٢٣﴾ قَالَ لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِيرٗا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَقَلِيلٞ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّـٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩ ﴿٢٤﴾ فَغَفَرۡنَا لَهُۥ ذَٰلِكَۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابٖ ﴿٢٥﴾", "w": [["هل أتاك", "الاستفهام للتعجب، أي حمل المخاطب على التعجب."], ["نبأ الخصم", "خبر الخصم الغريب في بابه العجيب في واقعه."], ["إذ تسوّروا المحراب", "محراب مسجده، إذ مُنعوا من الدخول من الباب فقصدوا سوره ونزلوا من أعلاه."], ["بغى بعضنا على بعض", "تعدّى بعضنا على بعض."], ["ولا تُشطط", "احكم بالعدل ولا تجر في حكمك."], ["واهدنا إلى سواء الصراط", "أرشدنا إلى العدل في قضيتنا ولا تمل بنا إلى غير الحق."], ["إن هذا أخي", "على ديني في الإسلام."], ["أكفِلنيها", "اجعلني كافلها، بمعنى تنازل لي عنها وملّكنيها."], ["وعزّني في الخطاب", "غلبني في الكلام الجدلي فأخذها مني."], ["بسؤال نعجتك", "بطلبه نعجتك وضمّها إلى نعاجه."], ["من الخلطاء", "الشركاء يظلم بعضهم بعضاً."], ["وظنّ داود أنما فتنّاه", "أيقن داود أنما اختبره ربه."], ["وخرّ راكعاً وأناب", "سقط ساجداً على الأرض ورجع تائباً إلى ربه."], ["وحسن مآب", "حسن مرجع عندنا، وهي الجنة والدرجات العلا فيها."]], "m": "ما زال السياق في تسلية الرسول ﷺ وحمله على الصبر: ذلك أن داود ﵇ ذكر مرة في نفسه ما أكرم الله به إبراهيم وإسحاق ويعقوب من حسن الثناء الباقي لهم، فتمنى مثله، فقيل له: إنهم امتُحنوا فصبروا، فسأل أن يُبتلى كما ابتُلوا ويُعطى كما أُعطوا إن هو صبر، فاختبره الله بإرسال ملكين في صورة رجلين، تسوّرا عليه سور المحراب ولم يدخلا من الباب لأن الحرس منعهما، إذ كان لداود وقت ينقطع فيه للعبادة. فلما دخلا عليه فزع منهما، فقالا: لا تخف، نحن خصمان بغى بعضنا على بعض، فاحكم بيننا بالعدل ولا تجر، وأرشدنا إلى وسط الطريق. فقال أحدهما وهو المظلوم: إن هذا أخي في الإسلام له تسع وتسعون نعجة ولي نعجة واحدة، فقال: ملّكنيها أضمّها إلى نعاجي، وغلبني في الجدال وأخذها مني. فقال داود على الفور وبدون أن يسمع من الخصم الثاني: لقد ظلمك بسؤال نعجتك إلى نعاجه، وإن كثيراً من الشركاء ليبغي بعضهم على بعض إلا الذين آمنوا وعملوا الصالحات فإنهم يسلمون من مثل هذه الاعتداءات، وقليل ما هم. وهنا طار الملكان وعرجا إلى السماء، فعلم أنما فتنه ربه كما رغب، وأنه لم يصبر حيث قضى قبل أن يسمع من الخصم الثاني، فكانت زلة صغيرة أرته أن ما ناله إبراهيم وإسحاق ويعقوب من الكمال كان نتيجة ابتلاء عظيم. فاستغفر ربه وخرّ راكعاً يبكي ويطلب العفو، وأناب إلى ربه، فغفرنا له ذلك وإن له عندنا لقربة وحسن مرجع، وهو الدرجات العلا في دار الأبرار.", "h": ["فائدة عرض مثل هذا القصص تقوية قلب الرسول ﷺ وتثبيت فؤاده وحمله على الصبر.", "تقرير نبوة النبي ﷺ، إذ مثل هذا القصص لا يتأتّى له قصّه إلا بوحي إلهي.", "تقرير جواز تشكّل الملائكة في صورة بني آدم.", "حرمة إصدار القاضي أو الحاكم الحكم قبل أن يسمع الدعوى من الخصمين معاً، إذ هذا محل الفتنة التي كانت لداود ﵇.", "وجوب التوبة عند الوقوع في الذنب.", "مشروعية السجود عند قراءة هذه الآية: «وخرّ راكعاً وأناب»."], "k": "«لقد ظلمك»… حكم قبل أن يسمع الطرف الآخر فاستغفر؛ كم مرة حكمتُ على أحد قبل أن أسمعه؟"}, {"lbl": "الآيات ٢٦ – ٢٩", "q": "يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةٗ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدُۢ بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ ﴿٢٦﴾ وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا بَٰطِلٗاۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُواْۚ فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِنَ ٱلنَّارِ ﴿٢٧﴾ أَمۡ نَجۡعَلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ كَٱلۡمُفۡسِدِينَ فِي ٱلۡأَرۡضِ أَمۡ نَجۡعَلُ ٱلۡمُتَّقِينَ كَٱلۡفُجَّارِ ﴿٢٨﴾ كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكٞ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿٢٩﴾", "w": [["إنا جعلناك خليفة", "خلفت من سبقك تدبّر أمر الناس بإذننا."], ["ولا تتبع الهوى", "هوى النفس، وهو ما تميل إليه مما تشتهيه."], ["فيُضلّك عن سبيل الله", "عن الطريق الموصل إلى رضوانه."], ["بما نسوا يوم الحساب", "بنسيانهم يوم القيامة فلم يتقوا الله تعالى."], ["باطلاً", "عبثاً لغير حكمة مقصودة من ذلك الخلق."], ["ذلك ظن الذين كفروا", "ظنّ أن السماوات والأرض وما بينهما خُلقت عبثاً."], ["فويل للذين كفروا من النار", "من وادٍ في النار بعيد غوره كريه ريحه لا يطاق."], ["مبارك", "لا تفارقه البركة، يجدها قارئه والعامل به والحاكم بما فيه."], ["وليتذكّر أولو الألباب", "ليتعظ به أصحاب العقول الراجحة."]], "m": "ما زال السياق في قصة داود: وقلنا له بعد توبته: يا داود إنا جعلناك خليفة في الأرض خلفت من قبلك من الأنبياء تدبّر أمر الناس، فاحكم بينهم بالعدل الموافق لشرع الله، ولا تتبع ما تهواه نفسك دون شرع الله فيُضلّك عن سبيله؛ ذلك أن الأحكام إذا طابقت الشريعة انتظمت بها مصالح العباد، وإذا كانت على وفق الهوى ومقاصد الحاكم أفضت إلى الهرج والمرج، وفي ذلك هلاك الحاكم والمحكومين. إن الذين يضلّون عن سبيل الله القائم على الإيمان والتقوى وإقامة الشرع والعدل لهم عذاب شديد في الدنيا والآخرة بسبب نسيانهم يوم القيامة فتركوا العمل له. وما خلقنا السماء والأرض وما بينهما عبثاً، بل لحكمة هي أن يُعبد الله بذكره وشكره المتمثّل في الإيمان والتقوى، ذلك ظن الذين كفروا، فويل لهم من وادٍ في جهنم بعيد الغور. أم نجعل الذين آمنوا وعملوا الصالحات كالمفسدين في الأرض بالشرك والمعاصي، أم نجعل المتقين كالفجّار؟ وهذا ردّ لما زعمه المشركون من أنهم يُعطَون في الآخرة مثل ما يُعطى المؤمنون، فحاشا لله أعدل العادلين أن يسوّي بينهم، بل ينعّم الأولين ويعذّب الآخرين. هذا كتاب مبارك أنزلناه ليتدبّروا آياته بعقولهم فيحصلوا على هداية القلوب، وليتعظ به أولو العقول السليمة. والبركة لا تفارق القرآن: فمن قرأه متدبراً عرف الهدى، ومن قرأه تقرّباً فاز بالقرب، ومن قرأه حاكماً عدل في حكمه.", "h": ["وجوب الحكم بالعدل على كل من حكم، ولا عدل في غير الشرع الإلهي.", "حرمة اتباع الهوى لما يفضي بالعبد إلى الهلاك والخسار.", "تقرير البعث والجزاء.", "إبطال ظن من يظن أن الحياة الدنيا خُلقت عبثاً وباطلاً.", "تنزيه الرب تعالى عن العبث والظلم.", "فضيلة العقول لمن استعملها في التدبر والتذكر.", "بركة القرآن لا تفارقه أبداً، وما طلبها أحد إلا وجدها."], "k": "«كتاب أنزلناه إليك مبارك ليدّبّروا آياته»… هل أقرأ لأتدبّر، أم لأنتهي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 330;
insert into public.tdb_cards(topic, i, body) select 330, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢١ – ٢٥", "q": "۞وَهَلۡ أَتَىٰكَ نَبَؤُاْ ٱلۡخَصۡمِ إِذۡ تَسَوَّرُواْ ٱلۡمِحۡرَابَ ﴿٢١﴾ إِذۡ دَخَلُواْ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنۡهُمۡۖ قَالُواْ لَا تَخَفۡۖ خَصۡمَانِ بَغَىٰ بَعۡضُنَا عَلَىٰ بَعۡضٖ فَٱحۡكُم بَيۡنَنَا بِٱلۡحَقِّ وَلَا تُشۡطِطۡ وَٱهۡدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ ﴿٢٢﴾ إِنَّ هَٰذَآ أَخِي لَهُۥ تِسۡعٞ وَتِسۡعُونَ نَعۡجَةٗ وَلِيَ نَعۡجَةٞ وَٰحِدَةٞ فَقَالَ أَكۡفِلۡنِيهَا وَعَزَّنِي فِي ٱلۡخِطَابِ ﴿٢٣﴾ قَالَ لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِيرٗا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَقَلِيلٞ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّـٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩ ﴿٢٤﴾ فَغَفَرۡنَا لَهُۥ ذَٰلِكَۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابٖ ﴿٢٥﴾", "w": [["هل أتاك", "الاستفهام للتعجب، أي حمل المخاطب على التعجب."], ["نبأ الخصم", "خبر الخصم الغريب في بابه العجيب في واقعه."], ["إذ تسوّروا المحراب", "محراب مسجده، إذ مُنعوا من الدخول من الباب فقصدوا سوره ونزلوا من أعلاه."], ["بغى بعضنا على بعض", "تعدّى بعضنا على بعض."], ["ولا تُشطط", "احكم بالعدل ولا تجر في حكمك."], ["واهدنا إلى سواء الصراط", "أرشدنا إلى العدل في قضيتنا ولا تمل بنا إلى غير الحق."], ["إن هذا أخي", "على ديني في الإسلام."], ["أكفِلنيها", "اجعلني كافلها، بمعنى تنازل لي عنها وملّكنيها."], ["وعزّني في الخطاب", "غلبني في الكلام الجدلي فأخذها مني."], ["بسؤال نعجتك", "بطلبه نعجتك وضمّها إلى نعاجه."], ["من الخلطاء", "الشركاء يظلم بعضهم بعضاً."], ["وظنّ داود أنما فتنّاه", "أيقن داود أنما اختبره ربه."], ["وخرّ راكعاً وأناب", "سقط ساجداً على الأرض ورجع تائباً إلى ربه."], ["وحسن مآب", "حسن مرجع عندنا، وهي الجنة والدرجات العلا فيها."]], "m": "ما زال السياق في تسلية الرسول ﷺ وحمله على الصبر: ذلك أن داود ﵇ ذكر مرة في نفسه ما أكرم الله به إبراهيم وإسحاق ويعقوب من حسن الثناء الباقي لهم، فتمنى مثله، فقيل له: إنهم امتُحنوا فصبروا، فسأل أن يُبتلى كما ابتُلوا ويُعطى كما أُعطوا إن هو صبر، فاختبره الله بإرسال ملكين في صورة رجلين، تسوّرا عليه سور المحراب ولم يدخلا من الباب لأن الحرس منعهما، إذ كان لداود وقت ينقطع فيه للعبادة. فلما دخلا عليه فزع منهما، فقالا: لا تخف، نحن خصمان بغى بعضنا على بعض، فاحكم بيننا بالعدل ولا تجر، وأرشدنا إلى وسط الطريق. فقال أحدهما وهو المظلوم: إن هذا أخي في الإسلام له تسع وتسعون نعجة ولي نعجة واحدة، فقال: ملّكنيها أضمّها إلى نعاجي، وغلبني في الجدال وأخذها مني. فقال داود على الفور وبدون أن يسمع من الخصم الثاني: لقد ظلمك بسؤال نعجتك إلى نعاجه، وإن كثيراً من الشركاء ليبغي بعضهم على بعض إلا الذين آمنوا وعملوا الصالحات فإنهم يسلمون من مثل هذه الاعتداءات، وقليل ما هم. وهنا طار الملكان وعرجا إلى السماء، فعلم أنما فتنه ربه كما رغب، وأنه لم يصبر حيث قضى قبل أن يسمع من الخصم الثاني، فكانت زلة صغيرة أرته أن ما ناله إبراهيم وإسحاق ويعقوب من الكمال كان نتيجة ابتلاء عظيم. فاستغفر ربه وخرّ راكعاً يبكي ويطلب العفو، وأناب إلى ربه، فغفرنا له ذلك وإن له عندنا لقربة وحسن مرجع، وهو الدرجات العلا في دار الأبرار.", "h": ["فائدة عرض مثل هذا القصص تقوية قلب الرسول ﷺ وتثبيت فؤاده وحمله على الصبر.", "تقرير نبوة النبي ﷺ، إذ مثل هذا القصص لا يتأتّى له قصّه إلا بوحي إلهي.", "تقرير جواز تشكّل الملائكة في صورة بني آدم.", "حرمة إصدار القاضي أو الحاكم الحكم قبل أن يسمع الدعوى من الخصمين معاً، إذ هذا محل الفتنة التي كانت لداود ﵇.", "وجوب التوبة عند الوقوع في الذنب.", "مشروعية السجود عند قراءة هذه الآية: «وخرّ راكعاً وأناب»."], "k": "«لقد ظلمك»… حكم قبل أن يسمع الطرف الآخر فاستغفر؛ كم مرة حكمتُ على أحد قبل أن أسمعه؟"}, {"lbl": "الآيات ٢٦ – ٢٩", "q": "يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةٗ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدُۢ بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ ﴿٢٦﴾ وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا بَٰطِلٗاۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُواْۚ فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِنَ ٱلنَّارِ ﴿٢٧﴾ أَمۡ نَجۡعَلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ كَٱلۡمُفۡسِدِينَ فِي ٱلۡأَرۡضِ أَمۡ نَجۡعَلُ ٱلۡمُتَّقِينَ كَٱلۡفُجَّارِ ﴿٢٨﴾ كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكٞ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿٢٩﴾", "w": [["إنا جعلناك خليفة", "خلفت من سبقك تدبّر أمر الناس بإذننا."], ["ولا تتبع الهوى", "هوى النفس، وهو ما تميل إليه مما تشتهيه."], ["فيُضلّك عن سبيل الله", "عن الطريق الموصل إلى رضوانه."], ["بما نسوا يوم الحساب", "بنسيانهم يوم القيامة فلم يتقوا الله تعالى."], ["باطلاً", "عبثاً لغير حكمة مقصودة من ذلك الخلق."], ["ذلك ظن الذين كفروا", "ظنّ أن السماوات والأرض وما بينهما خُلقت عبثاً."], ["فويل للذين كفروا من النار", "من وادٍ في النار بعيد غوره كريه ريحه لا يطاق."], ["مبارك", "لا تفارقه البركة، يجدها قارئه والعامل به والحاكم بما فيه."], ["وليتذكّر أولو الألباب", "ليتعظ به أصحاب العقول الراجحة."]], "m": "ما زال السياق في قصة داود: وقلنا له بعد توبته: يا داود إنا جعلناك خليفة في الأرض خلفت من قبلك من الأنبياء تدبّر أمر الناس، فاحكم بينهم بالعدل الموافق لشرع الله، ولا تتبع ما تهواه نفسك دون شرع الله فيُضلّك عن سبيله؛ ذلك أن الأحكام إذا طابقت الشريعة انتظمت بها مصالح العباد، وإذا كانت على وفق الهوى ومقاصد الحاكم أفضت إلى الهرج والمرج، وفي ذلك هلاك الحاكم والمحكومين. إن الذين يضلّون عن سبيل الله القائم على الإيمان والتقوى وإقامة الشرع والعدل لهم عذاب شديد في الدنيا والآخرة بسبب نسيانهم يوم القيامة فتركوا العمل له. وما خلقنا السماء والأرض وما بينهما عبثاً، بل لحكمة هي أن يُعبد الله بذكره وشكره المتمثّل في الإيمان والتقوى، ذلك ظن الذين كفروا، فويل لهم من وادٍ في جهنم بعيد الغور. أم نجعل الذين آمنوا وعملوا الصالحات كالمفسدين في الأرض بالشرك والمعاصي، أم نجعل المتقين كالفجّار؟ وهذا ردّ لما زعمه المشركون من أنهم يُعطَون في الآخرة مثل ما يُعطى المؤمنون، فحاشا لله أعدل العادلين أن يسوّي بينهم، بل ينعّم الأولين ويعذّب الآخرين. هذا كتاب مبارك أنزلناه ليتدبّروا آياته بعقولهم فيحصلوا على هداية القلوب، وليتعظ به أولو العقول السليمة. والبركة لا تفارق القرآن: فمن قرأه متدبراً عرف الهدى، ومن قرأه تقرّباً فاز بالقرب، ومن قرأه حاكماً عدل في حكمه.", "h": ["وجوب الحكم بالعدل على كل من حكم، ولا عدل في غير الشرع الإلهي.", "حرمة اتباع الهوى لما يفضي بالعبد إلى الهلاك والخسار.", "تقرير البعث والجزاء.", "إبطال ظن من يظن أن الحياة الدنيا خُلقت عبثاً وباطلاً.", "تنزيه الرب تعالى عن العبث والظلم.", "فضيلة العقول لمن استعملها في التدبر والتذكر.", "بركة القرآن لا تفارقه أبداً، وما طلبها أحد إلا وجدها."], "k": "«كتاب أنزلناه إليك مبارك ليدّبّروا آياته»… هل أقرأ لأتدبّر، أم لأنتهي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (331, 38, 30, 40, 'سورة ص ٣٠ – ٤٠', 'ص: سليمان ﵇ نعم العبد إنه أوّاب', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 331) = $j$[{"lbl": "الآيات ٣٠ – ٣٣", "q": "وَوَهَبۡنَا لِدَاوُۥدَ سُلَيۡمَٰنَۚ نِعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٌ ﴿٣٠﴾ إِذۡ عُرِضَ عَلَيۡهِ بِٱلۡعَشِيِّ ٱلصَّـٰفِنَٰتُ ٱلۡجِيَادُ ﴿٣١﴾ فَقَالَ إِنِّيٓ أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ ﴿٣٢﴾ رُدُّوهَا عَلَيَّۖ فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ ﴿٣٣﴾", "w": [["ووهبنا لداود سليمان", "ومن جملة هباتنا لداود الأوّاب أن وهبنا له سليمان ابنه."], ["نعم العبد إنه أوّاب", "سليمان رجّاع إلى ربه بالتوبة والإنابة."], ["الصافنات الجياد", "الخيل القائمة على ثلاث، السوابق."], ["حبّ الخير عن ذكر ربي", "حب الخيل عن صلاة العصر لانشغاله باستعراضها."], ["حتى توارت بالحجاب", "استترت الشمس في الأفق وتغطّت عن أعين الناظرين."], ["ردّوها عليّ", "ردّوا الخيل التي استعرضتها آنفاً."], ["فطفق مسحاً بالسوق", "أخذ يمسح بسوق تلك الخيل وأعناقها."]], "m": "ما زال السياق في ذكر إفضال الله على داود، فذكر أنه وهبه سليمان، وأثنى عليه بأنه نعم العبد لله، وعلّل ذلك بأنه أوّاب كثير الرجوع إلى الله بذكره واستغفاره عند الغفلة والنسيان العارض للعبد. وأشار إلى ذلك بقوله: إذ عُرض عليه بالعشيّ الصافنات الجياد، الخيل القوية التي إذا وقفت تأبى أن تقف على أربع بل تقف على ثلاث وترفع الرابعة، السريعة العدو، وكان استعراضاً منه لها إعداداً لغزو أراده، فانشغل بذلك عن صلاة العصر فلم يشعر إلا وقد غربت الشمس واستترت بالأفق. فندم لذلك وقال: إني أحببت حب الخيل عن ذكر ربي، وصلّى العصر، ثم عاد إلى إكمال الاستعراض فردّها رجاله عليه فجعل يمسح بيده سوقها وأعناقها حتى أكمل استعراضها. هذا وجه الأوبة التي وُصف بها سليمان ﵇ في قوله: إنه أوّاب.", "h": ["الولد الصالح هبة إلهية لوالده، فليشكر الله تعالى من وُهب ذلك.", "الثناء على العبد بالتوبة الفورية التي تعقب الذنب مباشرة.", "جواز استعراض الحاكم القائد قواته تفقّداً لها.", "إطلاق لفظ الخير على الخيل فيه تقرير أن الخيل إذا رُبطت في سبيل الله كان طعامها وشرابها حسنات لمن ربطها في سبيل الله.", "ربط الطائرات النفاثة في الحظائر اليوم والمدرّعات وإعدادها للقتال في سبيل الله حلّ محلّ ربط الجياد من الخيل في سبيل الله."], "k": "«إني أحببت حب الخير عن ذكر ربي»… ما الذي يشغلني عن الصلاة حتى يفوت وقتها؟ وهل أندم كما ندم؟"}, {"lbl": "الآيات ٣٤ – ٤٠", "q": "وَلَقَدۡ فَتَنَّا سُلَيۡمَٰنَ وَأَلۡقَيۡنَا عَلَىٰ كُرۡسِيِّهِۦ جَسَدٗا ثُمَّ أَنَابَ ﴿٣٤﴾ قَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكٗا لَّا يَنۢبَغِي لِأَحَدٖ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ﴿٣٥﴾ فَسَخَّرۡنَا لَهُ ٱلرِّيحَ تَجۡرِي بِأَمۡرِهِۦ رُخَآءً حَيۡثُ أَصَابَ ﴿٣٦﴾ وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٖ وَغَوَّاصٖ ﴿٣٧﴾ وَءَاخَرِينَ مُقَرَّنِينَ فِي ٱلۡأَصۡفَادِ ﴿٣٨﴾ هَٰذَا عَطَآؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِسَابٖ ﴿٣٩﴾ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابٖ ﴿٤٠﴾", "w": [["ولقد فتنّا سليمان", "ابتليناه."], ["وألقينا على كرسيّه جسداً", "شِقّ ولد ميت لا روح فيه."], ["ثم أناب", "رجع إلى ربه وتاب إليه من عدم استثنائه في يمينه."], ["وهب لي ملكاً لا ينبغي لأحد من بعدي", "أعطني ملكاً لا يكون لسواي من الناس."], ["فسخّرنا له الريح", "استجبنا له فسخّرنا له الريح تجري بأمره."], ["رُخاءً حيث أصاب", "ليّنة حيث أراد."], ["كل بنّاء وغوّاص", "وسخّرنا له الشياطين من الجن، منهم البنّاء ومنهم الغوّاص."], ["مقرّنين في الأصفاد", "مشدودين أيديهم إلى أعناقهم في السجون المظلمة إذا تمرّدوا وعصوا أمراً من أوامره."], ["هذا عطاؤنا", "وقلنا له: هذا عطاؤنا."], ["فامنن أو أمسك", "أعطِ من شئت ما شئت وامنع كذلك."], ["وإن له عندنا لزلفى", "لقربة يوم القيامة."], ["وحسن مآب", "مرجع في الجنة في الدرجات العلا."]], "m": "ما زال السياق في ذكر إنعام الله على آل داود: أخبر أنه ابتلى سليمان كما ابتلى أباه، وتاب سليمان كما تاب داود، ولم يُسقط ذلك من علوّ منزلتهما. وذلك كما أخبر رسول الله ﷺ في الصحيح أنه قال: لأطوفنّ الليلة على مائة جارية تلد كل جارية ولداً يصبح فارساً يقاتل في سبيل الله، ولم يقل: إن شاء الله، فعوقب لعدم استثنائه فلم تلد إلا واحدة جاءت بولد مشلول، فلما وضعته أتوا به إلى سليمان ووضعوه على كرسيّه، وهو قوله: وألقينا على كرسيّه جسداً. ثم أناب سليمان إلى ربه فاستغفر وتاب فتاب الله عليه، وقال: رب اغفر لي وهب لي ملكاً لا يكون مثله لسواي من الناس، وتوسّل إلى الله بقوله: إنك أنت الوهّاب. فاستجاب له فسخّر له الريح تجري بأمره ليّنة حيث أراد، تحمل بساطه أو سفينته الهوائية، وسخّر له شياطين الجن: منهم البنّاء للدور والمصانع، ومنهم الغوّاص في أعماق البحر لاستخراج اللآلئ، ومن عصاه وتمرّد جمع يديه إلى عنقه بصفد ووضعه تحت الأرض. وقلنا له: هذا عطاؤنا فأعطِ ما شئت لمن شئت وامنع ما شئت بغير حساب منا عليك، وفوق هذا إن له عندنا يوم القيامة لقربة وحسن مرجع.", "h": ["بيان عاقبة ترك الاستثناء؛ إذ عدم الاستثناء في قول سليمان «لأطوفنّ الليلة على مائة جارية» عوقب به فلم تلد امرأة من المائة إلا واحدة ولدت طفلاً مشلولاً، وعوقب به نبينا ﷺ فانقطع عنه الوحي نصف شهر وأكربه ذلك، لأنه لم يستثن عندما سُئل عن ثلاث مسائل وقال: غداً أجيبكم.", "مشروعية التوبة من كل ذنب صغيراً كان أو كبيراً.", "مشروعية التوسل إلى الله تعالى بأسمائه الحسنى.", "بيان إنعام الله تعالى على عبده سليمان.", "بيان تسخير الله تعالى لسليمان الريح والجن، وهذا لم يكن لأحد غيره من الناس."], "k": "«ثم أناب»… عثرة صغيرة فرجع فوراً؛ فكم أؤخّر توبتي؟ وهل أقول «إن شاء الله» بقلبي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 331;
