insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (332, 38, 41, 54, 'سورة ص ٤١ – ٥٤', 'ص: أيوب ﵇ إنا وجدناه صابراً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 332) = $j$[{"lbl": "الآيات ٤١ – ٤٤", "q": "وَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ ﴿٤١﴾ ٱرۡكُضۡ بِرِجۡلِكَۖ هَٰذَا مُغۡتَسَلُۢ بَارِدٞ وَشَرَابٞ ﴿٤٢﴾ وَوَهَبۡنَا لَهُۥٓ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنَّا وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ ﴿٤٣﴾ وَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ ﴿٤٤﴾", "w": [["واذكر عبدنا أيوب", "اذكر يا نبينا محمد عبدنا أيوب بن عيصو بن إسحاق."], ["بنُصب وعذاب", "بضرّ وألم شديد، نُسب للشيطان لكونه سبباً، وتأدّباً مع الله."], ["اركض برجلك", "اضرب برجلك الأرض تنبع عين ماء."], ["هذا مغتسل بارد وشراب", "وقلنا له: هذا ماء بارد تغتسل منه وتشرب فتُشفى."], ["ضِغثاً", "حزمة من حشيش يابس."], ["ولا تحنث", "بترك ضربها."], ["نعم العبد", "أيوب ﵇."], ["إنه أوّاب", "رجّاع إلى الله تعالى."]], "m": "واذكر يا نبينا عبدنا أيوب بن عيصو بن إسحاق بن إبراهيم الخليل ﵈ إذ نادى ربه قائلاً: أني مسّني الشيطان بنُصب وعذاب، أي ألم شديد، وذلك بعد مرض شديد طويل، وقال في ضراعة أخرى في سورة الأنبياء: ربّ أني مسّني الضر وأنت أرحم الراحمين. فلما أراد الله كشف الضر عنه قال له: اضرب برجلك الأرض ينبع منها ماء فاشرب منه واغتسل تُشفَ، ففعل فشُفي. ووهبنا له أهله ومثلهم معهم، عوّضه الله عما فقد من أهل وولد، رحمة منا وعبرة لأولي القلوب الحيّة، يعلمون بها أن الله قد يبتلي أحب عباده إليه ليرفعه درجات ما كان ليصل إليها دون الابتلاء في ذات الله والصبر عليه. وقلنا له: خذ بيدك حزمة من حشيش يابس فيها مائة عود فاضرب بها امرأتك ضربة واحدة، وكان قد حلف أن يضربها مائة جلدة لما حصل منها من تقصير في يوم من أيام حياتهما، فأفتاه ربه بذلك. إنا اختبرناه بالمرض وفقد الأهل والمال والولد فوجدناه صابراً، نعم العبد إنه أوّاب رجّاع إلى ربه في كل أمره.", "h": ["تقرير نبوة محمد ﷺ من طريق هذا القصص الذي لا يتأتّى إلا بالوحي الإلهي.", "قد يبتلي الله تعالى من يحبه من عباده ليزيد في علوّ مقامه ورفعة شأنه.", "فضل الصبر وعاقبته الحميدة في الدنيا والآخرة.", "مشروعية الفتيا، وهي خاصة بأهل الفقه والعلم.", "وجوب الكفارة على من حنث في يمينه."], "k": "«إنا وجدناه صابراً»… حين يطول بلائي، أشكو إلى الله أم أشكو الله إلى الناس؟"}, {"lbl": "الآيات ٤٥ – ٥٤", "q": "وَٱذۡكُرۡ عِبَٰدَنَآ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَ أُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ ﴿٤٥﴾ إِنَّآ أَخۡلَصۡنَٰهُم بِخَالِصَةٖ ذِكۡرَى ٱلدَّارِ ﴿٤٦﴾ وَإِنَّهُمۡ عِندَنَا لَمِنَ ٱلۡمُصۡطَفَيۡنَ ٱلۡأَخۡيَارِ ﴿٤٧﴾ وَٱذۡكُرۡ إِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلّٞ مِّنَ ٱلۡأَخۡيَارِ ﴿٤٨﴾ هَٰذَا ذِكۡرٞۚ وَإِنَّ لِلۡمُتَّقِينَ لَحُسۡنَ مَـَٔابٖ ﴿٤٩﴾ جَنَّـٰتِ عَدۡنٖ مُّفَتَّحَةٗ لَّهُمُ ٱلۡأَبۡوَٰبُ ﴿٥٠﴾ مُتَّكِـِٔينَ فِيهَا يَدۡعُونَ فِيهَا بِفَٰكِهَةٖ كَثِيرَةٖ وَشَرَابٖ ﴿٥١﴾ ۞وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ أَتۡرَابٌ ﴿٥٢﴾ هَٰذَا مَا تُوعَدُونَ لِيَوۡمِ ٱلۡحِسَابِ ﴿٥٣﴾ إِنَّ هَٰذَا لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ ﴿٥٤﴾", "w": [["واذكر عبادنا", "اذكر صبرهم على ما أصابهم فإن لك فيهم أسوة."], ["أولي الأيدي", "أصحاب القوى في العبادة."], ["والأبصار", "البصائر في الدين بمعرفة الأسرار والحِكَم."], ["بخالصة", "هي ذكر الدار الآخرة والعمل لها."], ["لمن المصطفين الأخيار", "من المختارين الأخيار، جمع خيّر."], ["هذا ذكر", "لهم بالثناء الحسن الجميل هنا في الدنيا."], ["وإن للمتقين", "هم وغيرهم من سائر المؤمنين والمؤمنات."], ["لحسن مآب", "مرجع عندما يرجعون إلى ربهم بالوفاة."], ["يدعون فيها بفاكهة", "يطالبون فيها بفاكهة، وذكر الفاكهة دون الطعام إيذاناً بأن طعامهم وشرابهم لمجرد التلذذ لا للتغذية."], ["قاصرات الطرف", "حابسات العيون على الأزواج فلا ينظرن إلى غيرهم."], ["أتراب", "أسنانهن متساوية، وهي ثلاث وثلاثون سنة."], ["ما له من نفاد", "ليس له انقطاع أبداً."]], "m": "ما زال السياق في ذكر الأنبياء وما أُكرموا به على صبرهم ليكون ذلك مثبّتاً للنبي ﷺ على دعوته والصبر عليها، فقال: واذكر يا نبينا عبادنا لتتأسّى بهم: إبراهيم وولده إسحاق وحفيده يعقوب، أصحاب القوى في العبادة والطاعة، وأبصار القلوب بالفقه في الدين ومعرفة أسرار الشرع. إنا خصصناهم بخاصة امتازوا بها هي ذكر الدار الآخرة بالعمل لها والدعوة إليها بالإيمان والتقوى، وإنهم عندنا لمن المختارين الأخيار المطبوعين على الخير. واذكر للائتساء إسماعيل واليسع وذا الكفل، وكلٌّ من الأخيار. هذا ذكر لهم بالثناء الحسن في الدنيا، وإن للمتقين جميعاً لحسن مرجع حين يرجعون إلى الله بعد الموت: جنات إقامة مفتّحة لهم الأبواب، متكئين فيها على الأرائك، يطالبون فيها بفاكهة كثيرة وشراب، ولم يذكر الطعام إشارة إلى أن مآكلهم ومشاربهم لمجرد التلذذ، وعندهم نساء حابسات أطرافهن على أزواجهن، في سن واحدة. ويقال لهم: هذا ما توعدون ليوم الحساب، إن هذا لرزقنا ما له من انقطاع ولا فناء.", "h": ["فضيلة القوة في العبادة والبصيرة في الدين، وفي الحديث: «المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف وفي كلٍّ خير».", "فضل ذكر الدار الآخرة وتذكّرها دائماً لأنها تساعد على الطاعة.", "فضل التقوى وأهلها وبيان ما أُعدّ لهم يوم الحساب.", "نعيم الآخرة لا ينفد، كأهلها لا يموتون ولا يهرمون.", "فضيلة الائتساء بالصالحين والاقتداء في الخير بهم."], "k": "«إنا أخلصناهم بخالصة ذكرى الدار»… كم مرة أتذكّر الآخرة في يومي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 332;
