خاصة بأهل الفقه والعلم.", "وجوب الكفارة على من حنث في يمينه."], "k": "«إنا وجدناه صابراً»… حين يطول بلائي، أشكو إلى الله أم أشكو الله إلى الناس؟"}, {"lbl": "الآيات ٤٥ – ٥٤", "q": "وَٱذۡكُرۡ عِبَٰدَنَآ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَ أُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ ﴿٤٥﴾ إِنَّآ أَخۡلَصۡنَٰهُم بِخَالِصَةٖ ذِكۡرَى ٱلدَّارِ ﴿٤٦﴾ وَإِنَّهُمۡ عِندَنَا لَمِنَ ٱلۡمُصۡطَفَيۡنَ ٱلۡأَخۡيَارِ ﴿٤٧﴾ وَٱذۡكُرۡ إِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلّٞ مِّنَ ٱلۡأَخۡيَارِ ﴿٤٨﴾ هَٰذَا ذِكۡرٞۚ وَإِنَّ لِلۡمُتَّقِينَ لَحُسۡنَ مَـَٔابٖ ﴿٤٩﴾ جَنَّـٰتِ عَدۡنٖ مُّفَتَّحَةٗ لَّهُمُ ٱلۡأَبۡوَٰبُ ﴿٥٠﴾ مُتَّكِـِٔينَ فِيهَا يَدۡعُونَ فِيهَا بِفَٰكِهَةٖ كَثِيرَةٖ وَشَرَابٖ ﴿٥١﴾ ۞وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ أَتۡرَابٌ ﴿٥٢﴾ هَٰذَا مَا تُوعَدُونَ لِيَوۡمِ ٱلۡحِسَابِ ﴿٥٣﴾ إِنَّ هَٰذَا لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ ﴿٥٤﴾", "w": [["واذكر عبادنا", "اذكر صبرهم على ما أصابهم فإن لك فيهم أسوة."], ["أولي الأيدي", "أصحاب القوى في العبادة."], ["والأبصار", "البصائر في الدين بمعرفة الأسرار والحِكَم."], ["بخالصة", "هي ذكر الدار الآخرة والعمل لها."], ["لمن المصطفين الأخيار", "من المختارين الأخيار، جمع خيّر."], ["هذا ذكر", "لهم بالثناء الحسن الجميل هنا في الدنيا."], ["وإن للمتقين", "هم وغيرهم من سائر المؤمنين والمؤمنات."], ["لحسن مآب", "مرجع عندما يرجعون إلى ربهم بالوفاة."], ["يدعون فيها بفاكهة", "يطالبون فيها بفاكهة، وذكر الفاكهة دون الطعام إيذاناً بأن طعامهم وشرابهم لمجرد التلذذ لا للتغذية."], ["قاصرات الطرف", "حابسات العيون على الأزواج فلا ينظرن إلى غيرهم."], ["أتراب", "أسنانهن متساوية، وهي ثلاث وثلاثون سنة."], ["ما له من نفاد", "ليس له انقطاع أبداً."]], "m": "ما زال السياق في ذكر الأنبياء وما أُكرموا به على صبرهم ليكون ذلك مثبّتاً للنبي ﷺ على دعوته والصبر عليها، فقال: واذكر يا نبينا عبادنا لتتأسّى بهم: إبراهيم وولده إسحاق وحفيده يعقوب، أصحاب القوى في العبادة والطاعة، وأبصار القلوب بالفقه في الدين ومعرفة أسرار الشرع. إنا خصصناهم بخاصة امتازوا بها هي ذكر الدار الآخرة بالعمل لها والدعوة إليها بالإيمان والتقوى، وإنهم عندنا لمن المختارين الأخيار المطبوعين على الخير. واذكر للائتساء إسماعيل واليسع وذا الكفل، وكلٌّ من الأخيار. هذا ذكر لهم بالثناء الحسن في الدنيا، وإن للمتقين جميعاً لحسن مرجع حين يرجعون إلى الله بعد الموت: جنات إقامة مفتّحة لهم الأبواب، متكئين فيها على الأرائك، يطالبون فيها بفاكهة كثيرة وشراب، ولم يذكر الطعام إشارة إلى أن مآكلهم ومشاربهم لمجرد التلذذ، وعندهم نساء حابسات أطرافهن على أزواجهن، في سن واحدة. ويقال لهم: هذا ما توعدون ليوم الحساب، إن هذا لرزقنا ما له من انقطاع ولا فناء.", "h": ["فضيلة القوة في العبادة والبصيرة في الدين، وفي الحديث: «المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف وفي كلٍّ خير».", "فضل ذكر الدار الآخرة وتذكّرها دائماً لأنها تساعد على الطاعة.", "فضل التقوى وأهلها وبيان ما أُعدّ لهم يوم الحساب.", "نعيم الآخرة لا ينفد، كأهلها لا يموتون ولا يهرمون.", "فضيلة الائتساء بالصالحين والاقتداء في الخير بهم."], "k": "«إنا أخلصناهم بخالصة ذكرى الدار»… كم مرة أتذكّر الآخرة في يومي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (333, 38, 55, 88, 'سورة ص ٥٥ – ٨٨', 'ص: خصام أهل النار وخصومة الملأ الأعلى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 333) = $j$[{"lbl": "الآيات ٥٥ – ٦٤", "q": "هَٰذَاۚ وَإِنَّ لِلطَّـٰغِينَ لَشَرَّ مَـَٔابٖ ﴿٥٥﴾ جَهَنَّمَ يَصۡلَوۡنَهَا فَبِئۡسَ ٱلۡمِهَادُ ﴿٥٦﴾ هَٰذَا فَلۡيَذُوقُوهُ حَمِيمٞ وَغَسَّاقٞ ﴿٥٧﴾ وَءَاخَرُ مِن شَكۡلِهِۦٓ أَزۡوَٰجٌ ﴿٥٨﴾ هَٰذَا فَوۡجٞ مُّقۡتَحِمٞ مَّعَكُمۡ لَا مَرۡحَبَۢا بِهِمۡۚ إِنَّهُمۡ صَالُواْ ٱلنَّارِ ﴿٥٩﴾ قَالُواْ بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ ﴿٦٠﴾ قَالُواْ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدۡهُ عَذَابٗا ضِعۡفٗا فِي ٱلنَّارِ ﴿٦١﴾ وَقَالُواْ مَا لَنَا لَا نَرَىٰ رِجَالٗا كُنَّا نَعُدُّهُم مِّنَ ٱلۡأَشۡرَارِ ﴿٦٢﴾ أَتَّخَذۡنَٰهُمۡ سِخۡرِيًّا أَمۡ زَاغَتۡ عَنۡهُمُ ٱلۡأَبۡصَٰرُ ﴿٦٣﴾ إِنَّ ذَٰلِكَ لَحَقّٞ تَخَاصُمُ أَهۡلِ ٱلنَّارِ ﴿٦٤﴾", "w": [["وإن للطاغين", "الذين طغوا في الكفر والشر والفساد."], ["لشرّ مآب", "جهنم يصلونها."], ["فبئس المهاد", "الفراش الذي مهّدوه لأنفسهم في الدنيا بالشرك والمعاصي."], ["حميم", "ماء حار محرق."], ["وغسّاق", "قيح وصديد يسيل من لحوم وفروج الزناة في النار."], ["وآخر من شكله أزواج", "وعذاب آخر كالحميم والغساق أصناف."], ["هذا فوج مقتحم معكم", "يقال لهم عند دخولهم النار."], ["لا مرحباً بهم", "لا سعة عليهم ولا راحة لهم."], ["قالوا بل أنتم", "الأتباع للطاغين: بل أنتم لا مرحباً بكم، أنتم قدّمتموه لنا."], ["من قدّم لنا هذا", "من كان سبباً في عذابنا هذا فزده عذاباً."], ["ما لنا لا نرى رجالاً", "قال الطاغون وهم في النار، يعنون فقراء المسلمين كبلال وعمار وصهيب."], ["أتخذناهم سِخريّاً", "كنا نسخر منهم في الدنيا."], ["أم زاغت عنهم الأبصار", "أمفقودون هم أم زاغت عنهم الأبصار فلم نرهم؟"], ["إن ذلك لحق تخاصم أهل النار", "إن ذلك المذكور لحق ثابت."]], "m": "بعد ذكر نعيم أهل الإيمان والتقوى ناسب ذكر شقاء أهل الكفر والفجور، وهو أسلوب الترغيب والترهيب الذي امتاز به القرآن. هذا ما تقدم من نعيم أهل السعادة، وإن للطاغين، المشركين الظلمة كأبي جهل وعقبة بن أبي معيط والعاص بن وائل، لأسوأ مرجع: جهنم يصلونها، وبئس المهاد مهّدوه لأنفسهم. هذا حميم وغساق فليذوقوه: الماء الحار المحرق، وما سال من جلود الزناة ولحومهم وفروجهم من القيح والصديد، وعذاب آخر من شكله أصناف عديدة. ويقال عند دخولهم النار: هذا فريق مقتحم معكم، فيقول الطاغون: لا مرحباً بهم إنهم داخلو النار محترقون بحرّها. فيردّ الأتباع: بل أنتم لا مرحباً بكم، أنتم قدّمتموه لنا إذ كنتم تأمروننا بالشرك والفجور، فبئس القرار. وقالوا: ربنا من قدّم لنا هذا فضاعف له العذاب في النار. وقال الطغاة: ما لنا لا نرى رجالاً كنا نعدّهم من الأشرار، كنا نسخر منهم في الدنيا، يعنون فقراء المسلمين كبلال وعمار وصهيب وخبيب، أمفقودون هم أم زاغت عنهم أبصارنا؟ إن ذلك الكلام الذي دار بين أهل النار حق وصدق، فاسمعوه أيها المشركون: اليوم آيات تُتلى، وغداً حقائق تُشاهد وغصص تُتجرّع وحسرات تمزّق القلوب.", "h": ["ذمّ الطغيان، وهو مجاوزة الحد في الظلم والكفر، وبيان جزاء أهله يوم القيامة.", "بيان ما يجري من خصام بين أهل النار للعظة والاعتبار.", "شكوى الأتباع ممن اتبعوهم في الضلال ومطالبتهم بمضاعفة العذاب لهم.", "تذكّر أهل النار فقراء المسلمين الذين كانوا يعدّونهم متخلفين ورجعيين لأنهم كانوا لا يأتون الفجور والشرور مثلهم."], "k": "«ما لنا لا نرى رجالاً كنا نعدّهم من الأشرار»… من أحتقره اليوم لفقره أو بساطته قد يكون عند الله خيراً مني."}, {"lbl": "الآيات ٦٥ – ٧٤", "q": "قُلۡ إِنَّمَآ أَنَا۠ مُنذِرٞۖ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ﴿٦٥﴾ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلۡعَزِيزُ ٱلۡغَفَّـٰرُ ﴿٦٦﴾ قُلۡ هُوَ نَبَؤٌاْ عَظِيمٌ ﴿٦٧﴾ أَنتُمۡ عَنۡهُ مُعۡرِضُونَ ﴿٦٨﴾ مَا كَانَ لِيَ مِنۡ عِلۡمِۭ بِٱلۡمَلَإِ ٱلۡأَعۡلَىٰٓ إِذۡ يَخۡتَصِمُونَ ﴿٦٩﴾ إِن يُوحَىٰٓ إِلَيَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٌ ﴿٧٠﴾ إِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرٗا مِّن طِينٖ ﴿٧١﴾ فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ ﴿٧٢﴾ فَسَجَدَ ٱلۡمَلَـٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ ﴿٧٣﴾ إِلَّآ إِبۡلِيسَ ٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ ﴿٧٤﴾", "w": [["قل إنما أنا منذر", "قل يا رسولنا لمشركي قومك: إنما أنا مخوّف من عذاب الله."], ["وما من إله إلا الله الواحد القهار", "وليس هناك من إله قط إلا الله الواحد القهار."], ["العزيز الغفار", "الغالب الذي لا يُمانَع في مراده، الغفّار للتائبين من عباده."], ["قل هو نبأ عظيم", "القرآن نبأ عظيم وخبر جسيم."], ["أنتم عنه معرضون", "لا ترغبون في سماعه ولا في تدبر معانيه."], ["بالملإ الأعلى", "بالملائكة عندما شووروا في خلق آدم."], ["إذ قال ربك للملائكة", "اذكر لهم تدليلاً على أنه يُوحى إليك القرآن."], ["خالق بشراً من طين", "خالق آدم من مادة الطين، وقيل فيه بشر لبُدوّ بشرته."], ["ونفخت فيه من روحي", "الروح جسم لطيف يسري في الجسم سريان النار في الفحم أو الماء في الشجر أو الكهرباء في الأسلاك."], ["إلا إبليس", "لم يسجد."], ["استكبر", "عن السجود لآدم كبراً وحسداً له."]], "m": "بعد ذلك العرض للقصص والجنة والنار وما تقرّر به من التوحيد والنبوة والبعث أمر تعالى رسوله أن يقول لمشركي قريش: إنما أنا منذر مخوّف من عذاب الله الواجب لكل من كفر به وكذّب بآياته ولقائه، وليس من إله قط إلا الله الواحد في ذاته وصفاته وربوبيته وعبادته، القهار لكل قاهر، رب السماوات والأرض وما بينهما، العزيز في الانتقام ممن كفر به، الغفّار لمن أناب إليه. وقل لهم: هو، أي القرآن وما حواه من التوحيد والنبوة والبعث والقصص ووصف الجنة والنار، خبر ذو شأن عظيم أنتم عنه معرضون تأبون سماعه، بدعوى أني افتريته، وهي حجة داحضة؛ إذ ما كان لي من علم بالملأ الأعلى إذ يختصمون حين قال الله للملائكة: إني جاعل في الأرض خليفة، فقالوا: أتجعل فيها من يفسد فيها ويسفك الدماء؟ فكيف عرفتُ هذا وحدّثت به لو لم يكن وحياً؟ إنْ يُوحى إليّ إلا أنما أنا نذير مبين، لم يُوحَ إليّ أن أتسلّط عليكم لأستعبدكم، إنما يُوحى إليّ أني نذير لكم ولغيركم. إذ قال ربك للملائكة: إني خالق بشراً من طين، هو آدم ﵇، فإذا أتممت خلقه ونفخت فيه من روحي فحيي فخرّوا له ساجدين طاعة لأمرنا وتحية لعبدنا، فسجد الملائكة كلهم أجمعون إلا إبليس استكبر عن السجود لزعمه الكاذب أنه خير منه لكونه من النار وآدم من طين، ولحسده حيث فُضّل عليه، وكان بذلك الكبر والحسد من الكافرين، إذ جحد معلوماً من طاعة الله بالضرورة وهو يتلقى الخطاب من الله تعالى.", "h": ["تقرير التوحيد بأدلته.", "تقرير النبوة والوحي بشواهده من نبأ الملأ الأعلى.", "عداوة إبليس لآدم، وأن الحامل عليها الحسد والكبر، وهما من شر صفات العبد.", "تقرير أن من القياس ما هو شر وباطل كقياس إبليس، إذ قاس النار على التراب فرأى أن النار أفضل فهلك بذلك، إذ التراب أفضل: النار تحرق والتراب يُحيي، وشتّان ما بين الموت والحياة."], "k": "«استكبر وكان من الكافرين»… أول معصية كانت كِبراً وحسداً؛ فهل أجد في نفسي شيئاً منهما؟"}, {"lbl": "الآيات ٧٥ – ٨٨", "q": "قَالَ يَـٰٓإِبۡلِيسُ مَا مَنَعَكَ أَن تَسۡجُدَ لِمَا خَلَقۡتُ بِيَدَيَّۖ أَسۡتَكۡبَرۡتَ أَمۡ كُنتَ مِنَ ٱلۡعَالِينَ ﴿٧٥﴾ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ﴿٧٦﴾ قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمٞ ﴿٧٧﴾ وَإِنَّ عَلَيۡكَ لَعۡنَتِيٓ إِلَىٰ يَوۡمِ ٱلدِّينِ ﴿٧٨﴾ قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ﴿٧٩﴾ قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ ﴿٨٠﴾ إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ ﴿٨١﴾ قَالَ فَبِعِزَّتِكَ لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ﴿٨٢﴾ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ ﴿٨٣﴾ قَالَ فَٱلۡحَقُّ وَٱلۡحَقَّ أَقُولُ ﴿٨٤﴾ لَأَمۡلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنۡهُمۡ أَجۡمَعِينَ ﴿٨٥﴾ قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٖ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ ﴿٨٦﴾ إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ﴿٨٧﴾ وَلَتَعۡلَمُنَّ نَبَأَهُۥ بَعۡدَ حِينِۭ ﴿٨٨﴾", "w": [["لما خلقتُ بيديّ", "للذي خلقته بيديّ وهو آدم، فدلّ ذلك على شرفه."], ["أستكبرت أم كنت من العالين", "استكبرت الآن أم كنت من قبل من المتكبرين؟ والاستفهام للتوبيخ والتقريع."], ["فاخرج منها", "من الجنة."], ["فإنك رجيم", "مرجوم مطرود."], ["وإن عليك لعنتي إلى يوم الدين", "طرده من الجنة وألحقه لعنة، وهي الطرد من الرحمة، إلى يوم الجزاء."], ["رب فأنظرني", "أخّر موتي وأبقِني حياً إلى يوم يُبعث الناس."], ["إلى يوم الوقت المعلوم", "إلى النفخة الأولى، نفخة الموت والفناء."], ["إلا عبادك منهم المخلَصين", "الذين استخلصتهم للإيمان بك وعبادتك."], ["ما أسألكم عليه من أجر", "لا أسألكم على البلاغ أجراً تعطونه لي."], ["وما أنا من المتكلّفين", "المتقوّلين القرآن من تلقاء نفسي."], ["إن هو إلا ذكر للعالمين", "ما أتلوه من القرآن إلا ذكر للعالمين."], ["ولتعلمنّ نبأه بعد حين", "ولتعلمنّ أيها المكذبون نبأ القرآن من الوعد والوعيد بعد حين."]], "m": "ما زال السياق فيما دار بين الرب تعالى وعدوه إبليس في الملأ الأعلى: قال تعالى: يا إبليس ما منعك أن تسجد لما خلقت بيديّ وقد أمرتك؟ أستكبرت الآن أم كنت من قبل من المستكبرين؟ توبيخاً له. فقال: أنا خير منه خلقتني من نار وخلقته من طين، فاستعمل القياس الفاسد، إذ النار لم تكن أبداً خيراً من الطين: النار تحرق وغايتها رماد، والطين منه سائر أنواع الغذاء التي بها الحياة من الحبوب والثمار واللحوم، وحسبه أنه أصل الإنسان ومادته. فقال تعالى: فاخرج من الجنة فإنك مطرود، وإن عليك لعنتي إلى يوم الدين. فلما يئس من الرحمة قال: رب أبقِني حياً لا تمتني إلى يوم يُبعثون، ليتمكّن من إغواء بني آدم ولا يذوق الموت، وعلم الله ما أضمره فقال: فإنك من الممهلين إلى يوم الوقت المعلوم، وهو النفخة الأولى حتى يموت مع سائر الخلائق. فلما علم أنه أُنظر قال في وقاحة مقسماً بعزة الله: فبعزتك لأغوينّهم أجمعين إلا عبادك منهم المخلَصين، فاستثنى عباد الله المؤمنين المتقين. فقال تعالى: فالحق أنا، والحق أقول: لأملأنّ جهنم منك وممن تبعك من الإنس والجن أجمعين. وإلى هنا انتهى ما دار من خصومة في الملأ الأعلى، فكيف عرف محمد ﷺ هذا وأخبر به لولا أنه وحي يُوحى إليه؟ ثم قال لرسوله: قل لقومك: ما أسألكم على البلاغ من أجر، وما أنا من الذين يتقوّلون على الله ما لم يقل، إن هو إلا ذكر للعالمين من الإنس والجن يذكرون به فيهتدون، ولتعرفنّ صدق ما أخبر به من وعد ووعيد بعد حين، وقد عرف بعضهم ذلك يوم بدر ويوم الفتح ويوم موته.", "h": ["ذمّ الكبر والحسد وحرمتهما وبيان جزائهما.", "مشروعية القياس إن كان قياساً صحيحاً، وبيان أخطار القياس الفاسد.", "مشروعية القسم بالله وبصفاته وأسمائه.", "بيان أن من كتب الله سعادتهم لا يقوى الشيطان على إغوائهم وإضلالهم.", "لا يجوز أخذ الأجرة على بيان الحق والدين.", "ذمّ التكلّف المفضي إلى الكذب والتقوّل على الله وعلى الرسول والمؤمنين.", "ظهور مصداق ما أخبر به القرآن بعد حين قصير وطويل."], "k": "«إلا عبادك منهم المخلَصين»… عدوّي نفسه استثنى المخلصين؛ فالإخلاص حصني منه."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 333;
insert into public.tdb_cards(topic, i, body) select 333, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٥ – ٦٤", "q": "هَٰذَاۚ وَإِنَّ لِلطَّـٰغِينَ لَشَرَّ مَـَٔابٖ ﴿٥٥﴾ جَهَنَّمَ يَصۡلَوۡنَهَا فَبِئۡسَ ٱلۡمِهَادُ ﴿٥٦﴾ هَٰذَا فَلۡيَذُوقُوهُ حَمِيمٞ وَغَسَّاقٞ ﴿٥٧﴾ وَءَاخَرُ مِن شَكۡلِهِۦٓ أَزۡوَٰجٌ ﴿٥٨﴾ هَٰذَا فَوۡجٞ مُّقۡتَحِمٞ مَّعَكُمۡ لَا مَرۡحَبَۢا بِهِمۡۚ إِنَّهُمۡ صَالُواْ ٱلنَّارِ ﴿٥٩﴾ قَالُواْ بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ ﴿٦٠﴾ قَالُواْ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدۡهُ عَذَابٗا ضِعۡفٗا فِي ٱلنَّارِ ﴿٦١﴾ وَقَالُواْ مَا لَنَا لَا نَرَىٰ رِجَالٗا كُنَّا نَعُدُّهُم مِّنَ ٱلۡأَشۡرَارِ ﴿٦٢﴾ أَتَّخَذۡنَٰهُمۡ سِخۡرِيًّا أَمۡ زَاغَتۡ عَنۡهُمُ ٱلۡأَبۡصَٰرُ ﴿٦٣﴾ إِنَّ ذَٰلِكَ لَحَقّٞ تَخَاصُمُ أَهۡلِ ٱلنَّارِ ﴿٦٤﴾", "w": [["وإن للطاغين", "الذين طغوا في الكفر والشر والفساد."], ["لشرّ مآب", "جهنم يصلونها."], ["فبئس المهاد", "الفراش الذي مهّدوه لأنفسهم في الدنيا بالشرك والمعاصي."], ["حميم", "ماء حار محرق."], ["وغسّاق", "قيح وصديد يسيل من لحوم وفروج الزناة في النار."], ["وآخر من شكله أزواج", "وعذاب آخر كالحميم والغساق أصناف."], ["هذا فوج مقتحم معكم", "يقال لهم عند دخولهم النار."], ["لا مرحباً بهم", "لا سعة عليهم ولا راحة لهم."], ["قالوا بل أنتم", "الأتباع للطاغين: بل أنتم لا مرحباً بكم، أنتم قدّمتموه لنا."], ["من قدّم لنا هذا", "من كان سبباً في عذابنا هذا فزده عذاباً."], ["ما لنا لا نرى رجالاً", "قال الطاغون وهم في النار، يعنون فقراء المسلمين كبلال وعمار وصهيب."], ["أتخذناهم سِخريّاً", "كنا نسخر منهم في الدنيا."], ["أم زاغت عنهم الأبصار", "أمفقودون هم أم زاغت عنهم الأبصار فلم نرهم؟"], ["إن ذلك لحق تخاصم أهل النار", "إن ذلك المذكور لحق ثابت."]], "m": "بعد ذكر نعيم أهل الإيمان والتقوى ناسب ذكر شقاء أهل الكفر والفجور، وهو أسلوب الترغيب والترهيب الذي امتاز به القرآن. هذا ما تقدم من نعيم أهل السعادة، وإن للطاغين، المشركين الظلمة كأبي جهل وعقبة بن أبي معيط والعاص بن وائل، لأسوأ مرجع: جهنم يصلونها، وبئس المهاد مهّدوه لأنفسهم. هذا حميم وغساق فليذوقوه: الماء الحار المحرق، وما سال من جلود الزناة ولحومهم وفروجهم من القيح والصديد، وعذاب آخر من شكله أصناف عديدة. ويقال عند دخولهم النار: هذا فريق مقتحم معكم، فيقول الطاغون: لا مرحباً بهم إنهم داخلو النار محترقون بحرّها. فيردّ الأتباع: بل أنتم لا مرحباً بكم، أنتم قدّمتموه لنا إذ كنتم تأمروننا بالشرك والفجور، فبئس القرار. وقالوا: ربنا من قدّم لنا هذا فضاعف له العذاب في النار. وقال الطغاة: ما لنا لا نرى رجالاً كنا نعدّهم من الأشرار، كنا نسخر منهم في الدنيا، يعنون فقراء المسلمين كبلال وعمار وصهيب وخبيب، أمفقودون هم أم زاغت عنهم أبصارنا؟ إن ذلك الكلام الذي دار بين أهل النار حق وصدق، فاسمعوه أيها المشركون: اليوم آيات تُتلى، وغداً حقائق تُشاهد وغصص تُتجرّع وحسرات تمزّق القلوب.", "h": ["ذمّ الطغيان، وهو مجاوزة الحد في الظلم والكفر، وبيان جزاء أهله يوم القيامة.", "بيان ما يجري من خصام بين أهل النار للعظة والاعتبار.", "شكوى الأتباع ممن اتبعوهم في الضلال ومطالبتهم بمضاعفة العذاب لهم.", "تذكّر أهل النار فقراء المسلمين الذين كانوا يعدّونهم متخلفين ورجعيين لأنهم كانوا لا يأتون الفجور والشرور مثلهم."], "k": "«ما لنا لا نرى رجالاً كنا نعدّهم من الأشرار»… من أحتقره اليوم لفقره أو بساطته قد يكون عند الله خيراً مني."}, {"lbl": "الآيات ٦٥ – ٧٤", "q": "قُلۡ إِنَّمَآ أَنَا۠ مُنذِرٞۖ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ﴿٦٥﴾ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلۡعَزِيزُ ٱلۡغَفَّـٰرُ ﴿٦٦﴾ قُلۡ هُوَ نَبَؤٌاْ عَظِيمٌ ﴿٦٧﴾ أَنتُمۡ عَنۡهُ مُعۡرِضُونَ ﴿٦٨﴾ مَا كَانَ لِيَ مِنۡ عِلۡمِۭ بِٱلۡمَلَإِ ٱلۡأَعۡلَىٰٓ إِذۡ يَخۡتَصِمُونَ ﴿٦٩﴾ إِن يُوحَىٰٓ إِلَيَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٌ ﴿٧٠﴾ إِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرٗا مِّن طِينٖ ﴿٧١﴾ فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ ﴿٧٢﴾ فَسَجَدَ ٱلۡمَلَـٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ ﴿٧٣﴾ إِلَّآ إِبۡلِيسَ ٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ ﴿٧٤﴾", "w": [["قل إنما أنا منذر", "قل يا رسولنا لمشركي قومك: إنما أنا مخوّف من عذاب الله."], ["وما من إله إلا الله الواحد القهار", "وليس هناك من إله قط إلا الله الواحد القهار."], ["العزيز الغفار", "الغالب الذي لا يُمانَع في مراده، الغفّار للتائبين من عباده."], ["قل هو نبأ عظيم", "القرآن نبأ عظيم وخبر جسيم."], ["أنتم عنه معرضون", "لا ترغبون في سماعه ولا في تدبر معانيه."], ["بالملإ الأعلى", "بالملائكة عندما شووروا في خلق آدم."], ["إذ قال ربك للملائكة", "اذكر لهم تدليلاً على أنه يُوحى إليك القرآن."], ["خالق بشراً من طين", "خالق آدم من مادة الطين، وقيل فيه بشر لبُدوّ بشرته."], ["ونفخت فيه من روحي", "الروح جسم لطيف يسري في الجسم سريان النار في الفحم أو الماء في الشجر أو الكهرباء في الأسلاك."], ["إلا إبليس", "لم يسجد."], ["استكبر", "عن السجود لآدم كبراً وحسداً له."]], "m": "بعد ذلك العرض للقصص والجنة والنار وما تقرّر به من التوحيد والنبوة والبعث أمر تعالى رسوله أن يقول لمشركي قريش: إنما أنا منذر مخوّف من عذاب الله الواجب لكل من كفر به وكذّب بآياته ولقائه، وليس من إله قط إلا الله الواحد في ذاته وصفاته وربوبيته وعبادته، القهار لكل قاهر، رب السماوات والأرض وما بينهما، العزيز في الانتقام ممن كفر به، الغفّار لمن أناب إليه. وقل لهم: هو، أي القرآن وما حواه من التوحيد والنبوة والبعث والقصص ووصف الجنة والنار، خبر ذو شأن عظيم أنتم عنه معرضون تأبون سماعه، بدعوى أني افتريته، وهي حجة داحضة؛ إذ ما كان لي من علم بالملأ الأعلى إذ يختصمون حين قال الله للملائكة: إني جاعل في الأرض خليفة، فقالوا: أتجعل فيها من يفسد فيها ويسفك الدماء؟ فكيف عرفتُ هذا وحدّثت به لو لم يكن وحياً؟ إنْ يُوحى إليّ إلا أنما أنا نذير مبين، لم يُوحَ إليّ أن أتسلّط عليكم لأستعبدكم، إنما يُوحى إليّ أني نذير لكم ولغيركم. إذ قال ربك للملائكة: إني خالق بشراً من طين، هو آدم ﵇، فإذا أتممت خلقه ونفخت فيه من روحي فحيي فخرّوا له ساجدين طاعة لأمرنا وتحية لعبدنا، فسجد الملائكة كلهم أجمعون إلا إبليس استكبر عن السجود لزعمه الكاذب أنه خير منه لكونه من النار وآدم من طين، ولحسده حيث فُضّل عليه، وكان بذلك الكبر والحسد من الكافرين، إذ جحد معلوماً من طاعة الله بالضرورة وهو يتلقى الخطاب من الله تعالى.", "h": ["تقرير التوحيد بأدلته.", "تقرير النبوة والوحي بشواهده من نبأ الملأ الأعلى.", "عداوة إبليس لآدم، وأن الحامل عليها الحسد والكبر، وهما من شر صفات العبد.", "تقرير أن من القياس ما هو شر وباطل كقياس إبليس، إذ قاس النار على التراب فرأى أن النار أفضل فهلك بذلك، إذ التراب أفضل: النار تحرق والتراب يُحيي، وشتّان ما بين الموت والحياة."], "k": "«استكبر وكان من الكافرين»… أول معصية كانت كِبراً وحسداً؛ فهل أجد في نفسي شيئاً منهما؟"}, {"lbl": "الآيات ٧٥ – ٨٨", "q": "قَالَ يَـٰٓإِبۡلِيسُ مَا مَنَعَكَ أَن تَسۡجُدَ لِمَا خَلَقۡتُ بِيَدَيَّۖ أَسۡتَكۡبَرۡتَ أَمۡ كُنتَ مِنَ ٱلۡعَالِينَ ﴿٧٥﴾ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ﴿٧٦﴾ قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمٞ ﴿٧٧﴾ وَإِنَّ عَلَيۡكَ لَعۡنَتِيٓ إِلَىٰ يَوۡمِ ٱلدِّينِ ﴿٧٨﴾ قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ﴿٧٩﴾ قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ ﴿٨٠﴾ إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ ﴿٨١﴾ قَالَ فَبِعِزَّتِكَ لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ﴿٨٢﴾ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ ﴿٨٣﴾ قَالَ فَٱلۡحَقُّ وَٱلۡحَقَّ أَقُولُ ﴿٨٤﴾ لَأَمۡلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنۡهُمۡ أَجۡمَعِينَ ﴿٨٥﴾ قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٖ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ ﴿٨٦﴾ إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ﴿٨٧﴾ وَلَتَعۡلَمُنَّ نَبَأَهُۥ بَعۡدَ حِينِۭ ﴿٨٨﴾", "w": [["لما خلقتُ بيديّ", "للذي خلقته بيديّ وهو آدم، فدلّ ذلك على شرفه."], ["أستكبرت أم كنت من العالين", "استكبرت الآن أم كنت من قبل من المتكبرين؟ والاستفهام للتوبيخ والتقريع."], ["فاخرج منها", "من الجنة."], ["فإنك رجيم", "مرجوم مطرود."], ["وإن عليك لعنتي إلى يوم الدين", "طرده من الجنة وألحقه لعنة، وهي الطرد من الرحمة، إلى يوم الجزاء."], ["رب فأنظرني", "أخّر موتي وأبقِني حياً إلى يوم يُبعث الناس."], ["إلى يوم الوقت المعلوم", "إلى النفخة الأولى، نفخة الموت والفناء."], ["إلا عبادك منهم المخلَصين", "الذين استخلصتهم للإيمان بك وعبادتك."], ["ما أسألكم عليه من أجر", "لا أسألكم على البلاغ أجراً تعطونه لي."], ["وما أنا من المتكلّفين", "المتقوّلين القرآن من تلقاء نفسي."], ["إن هو إلا ذكر للعالمين", "ما أتلوه من القرآن إلا ذكر للعالمين."], ["ولتعلمنّ نبأه بعد حين", "ولتعلمنّ أيها المكذبون نبأ القرآن من الوعد والوعيد بعد حين."]], "m": "ما زال السياق فيما دار بين الرب تعالى وعدوه إبليس في الملأ الأعلى: قال تعالى: يا إبليس ما منعك أن تسجد لما خلقت بيديّ وقد أمرتك؟ أستكبرت الآن أم كنت من قبل من المستكبرين؟ توبيخاً له. فقال: أنا خير منه خلقتني من نار وخلقته من طين، فاستعمل القياس الفاسد، إذ النار لم تكن أبداً خيراً من الطين: النار تحرق وغايتها رماد، والطين منه سائر أنواع الغذاء التي بها الحياة من الحبوب والثمار واللحوم، وحسبه أنه أصل الإنسان ومادته. فقال تعالى: فاخرج من الجنة فإنك مطرود، وإن عليك لعنتي إلى يوم الدين. فلما يئس من الرحمة قال: رب أبقِني حياً لا تمتني إلى يوم يُبعثون، ليتمكّن من إغواء بني آدم ولا يذوق الموت، وعلم الله ما أضمره فقال: فإنك من الممهلين إلى يوم الوقت المعلوم، وهو النفخة الأولى حتى يموت مع سائر الخلائق. فلما علم أنه أُنظر قال في وقاحة مقسماً بعزة الله: فبعزتك لأغوينّهم أجمعين إلا عبادك منهم المخلَصين، فاستثنى عباد الله المؤمنين المتقين. فقال تعالى: فالحق أنا، والحق أقول: لأملأنّ جهنم منك وممن تبعك من الإنس والجن أجمعين. وإلى هنا انتهى ما دار من خصومة في الملأ الأعلى، فكيف عرف محمد ﷺ هذا وأخبر به لولا أنه وحي يُوحى إليه؟ ثم قال لرسوله: قل لقومك: ما أسألكم على البلاغ من أجر، وما أنا من الذين يتقوّلون على الله ما لم يقل، إن هو إلا ذكر للعالمين من الإنس والجن يذكرون به فيهتدون، ولتعرفنّ صدق ما أخبر به من وعد ووعيد بعد حين، وقد عرف بعضهم ذلك يوم بدر ويوم الفتح ويوم موته.", "h": ["ذمّ الكبر والحسد وحرمتهما وبيان جزائهما.", "مشروعية القياس إن كان قياساً صحيحاً، وبيان أخطار القياس الفاسد.", "مشروعية القسم بالله وبصفاته وأسمائه.", "بيان أن من كتب الله سعادتهم لا يقوى الشيطان على إغوائهم وإضلالهم.", "لا يجوز أخذ الأجرة على بيان الحق والدين.", "ذمّ التكلّف المفضي إلى الكذب والتقوّل على الله وعلى الرسول والمؤمنين.", "ظهور مصداق ما أخبر به القرآن بعد حين قصير وطويل."], "k": "«إلا عبادك منهم المخلَصين»… عدوّي نفسه استثنى المخلصين؛ فالإخلاص حصني منه."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (334, 39, 1, 9, 'سورة الزمر ١ – ٩', 'الزمر: ألا لله الدين الخالص', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 334) = $j$[{"lbl": "الآيات ١ – ٤", "q": "تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ﴿١﴾ إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ فَٱعۡبُدِ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ ﴿٢﴾ أَلَا لِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ مَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلۡفَىٰٓ إِنَّ ٱللَّهَ يَحۡكُمُ بَيۡنَهُمۡ فِي مَا هُمۡ فِيهِ يَخۡتَلِفُونَۗ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ كَٰذِبٞ كَفَّارٞ ﴿٣﴾ لَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدٗا لَّٱصۡطَفَىٰ مِمَّا يَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ﴿٤﴾", "w": [["تنزيل الكتاب", "القرآن من الله."], ["العزيز الحكيم", "العزيز في ملكه وانتقامه، الحكيم في صنعه وتدبير خلقه."], ["مخلصاً له الدين", "مفرداً إياه بالعبادة فلا تشرك بعبادته أحداً."], ["له الدين الخالص", "له وحده خالص العبادة لا يشاركه في ذلك أحد سواه."], ["أولياء", "شركاء، وهي الأصنام."], ["ليقرّبونا إلى الله زلفى", "تقريباً وتشفع لنا عند الله."], ["من هو كاذب كفّار", "كاذب على الله، كفّار بعبادته غير الله."], ["سبحانه", "تنزيهاً له عن الولد والشريك."], ["هو الله الواحد القهار", "المعبود الحق الواحد الذي لا شريك له في ملكه وسلطانه."]], "m": "يخبر تعالى أن تنزيل القرآن كان منه سبحانه، العزيز في انتقامه من أعدائه، الحكيم في تدبير خلقه، ولم يكن عن غيره بحال. إنا أنزلنا إليك القرآن بالحق في كل ما جاء فيه من العقائد والعبادات والأحكام، فاعبد الله مخلصاً له الدين لا تعبد معه غيره، فإن العبادة لا تصلح لغيره أبداً. ألا لله الدين الخالص، والذين اتخذوا من دونه شركاء يعبدونهم ويقولون: ما نعبدهم إلا ليقرّبونا إلى الله ويشفعوا لنا في قضاء حوائجنا، هؤلاء يحكم الله بينهم وبين المؤمنين الموحّدين يوم القيامة، ويجزي بعدله كلاً بما يستحقه. إن الله لا يهدي من توغّلوا في الفساد فأصبح الكذب على الله وعلى عباده وصفاً لازماً لهم، وبالغوا في الكفر حتى صار وصفاً ثابتاً لهم؛ وهذه سنته في حرمان العبد من الهداية. لو أراد الله أن يتخذ ولداً كما زعم المشركون أن الملائكة بنات الله، وكما قال النصارى: المسيح ابن الله، وقال اليهود: عزير ابن الله، لاصطفى مما يخلق ما يشاء، ولا يتركهم ينسبون إليه الولد افتراءً، ولكنه منزّه عن صفات المحدَثين وافتقار المخلوقين، هو الله الواحد القهار لسائر خلقه، لا إله غيره ولا رب سواه.", "h": ["تقرير النبوة المحمدية.", "تقرير التوحيد.", "بطلان الشرك والتنديد بالمشركين.", "تقرير البعث والجزاء يوم القيامة."], "k": "«ألا لله الدين الخالص»… كم في عملي من شوائب تنتظر أن أخلّصها لله؟"}, {"lbl": "الآيات ٥ – ٧", "q": "خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ يُكَوِّرُ ٱلَّيۡلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِيزُ ٱلۡغَفَّـٰرُ ﴿٥﴾ خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖۚ يَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ ﴿٦﴾ إِن تَكۡفُرُواْ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنكُمۡۖ وَلَا يَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ وَإِن تَشۡكُرُواْ يَرۡضَهُ لَكُمۡۗ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٧﴾", "w": [["خلق السماوات والأرض بالحق", "من أجل أن يُذكر ويُشكر، لا من أجل اللهو والعبث."], ["يكوّر الليل على النهار", "يُدخل أحدهما في الآخر، فإذا جاء الليل ذهب النهار."], ["وسخّر الشمس والقمر", "ذلّلهما فلا يزالان يدوران في فلكيهما إلى نهاية الحياة، وبدورتهما تتم مصالح سكان الأرض."], ["خلقكم من نفس واحدة", "هي آدم ﵇."], ["ثم جعل منها زوجها", "هي حواء، خلقها الله من ضلع آدم الأيسر."], ["ثمانية أزواج", "من الإبل اثنين ومن البقر اثنين ومن الضأن اثنين ومن المعز اثنين."], ["خلقاً من بعد خلق", "أطواراً، طوراً بعد طور: نطفة فعلقة فمضغة."], ["في ظلمات ثلاث", "ظلمة البطن وظلمة الرحم وظلمة المشيمة."], ["ولا تزر وازرة وزر أخرى", "لا تحمل نفس ذات وزر وزر نفس أخرى."], ["بذات الصدور", "ما يخفيه المرء في صدره وما يُسرّه في ضميره."]], "m": "هذه الآيات في تقرير التوحيد بذكر البراهين التي لا تدع للشك مجالاً: خلق السماوات والأرض على غير مثال سابق، وخلقهما بالحق لغايات سامية لا للعبث، ومنها أن يُعبد فيهما فيُذكر ويُشكر. وبرهان ثانٍ: يكوّر الليل على النهار ويكوّر النهار على الليل، يغشى هذا هذا فيستره. وبرهان ثالث: سخّر الشمس والقمر كلٌّ يجري لأجل مسمى إلى قيام الساعة، وفي ذلك من المصالح ما لا يُقدَر قدره، منها معرفة عدد السنين والحساب. ألا هو العزيز في انتقامه من أعدائه، الغفّار لعباده التائبين. خلقكم من نفس واحدة هي آدم، فقد صحّ أنه لما خلقه مسح ظهره فأخرج منه ذريته وأشهدهم على أنفسهم، ولهذا جاء العطف بثمّ: ثم خلق منها زوجها حواء من ضلعه الأيسر. وبرهان آخر: أنزل لكم من الأنعام، الإبل والبقر والضأن والمعز، ذكراً وأنثى فهي ثمانية أزواج، وجائز أن يكون أصلها أُنزل من السماء كما أُنزل آدم وحواء، وجائز أن يكون أنزل الماء فنبت العشب وتكوّنت منه. وبرهان رابع: يخلقكم في بطون أمهاتكم نطفة ثم علقة ثم مضغة ثم عظاماً يكسوها لحماً، في ظلمات ثلاث: البطن والرحم والمشيمة. ذلكم الله ربكم خالقكم ومعبودكم، له الملك لا إله إلا هو، فكيف تُصرفون عن الحق إلى الباطل؟ إن تكفروا فإن الله غني عنكم لا يضرّه كفركم، إلا أنه لرحمته بعباده لا يرضى لهم الكفر لما يسبّبه لهم من شقاء، وإن تشكروا يرضه لكم فيثيبكم أحسن ثواب. ولا تحمل نفس ذنب نفس أخرى، وهذا مظهر من مظاهر عدله، ثم إلى ربكم مرجعكم بعد الموت فيخبركم بأعمالكم خفيّها وجليّها، إنه عليم بما في الصدور فضلاً عما كان ظاهراً. فهذا ربكم الحق فآمنوا به ووحّدوه وأطيعوه تنجوا وتسعدوا، ولا يهلك على الله إلا هالك.", "h": ["بيان آيات الله في الكون وإيرادها أدلة على التوحيد.", "بيان إفضال الله تعالى على العباد في خلقهم ورزقهم.", "بيان أن الكفر أعجب من الإيمان، إذ أدلة الإيمان لا تُعدّ كثرة وأما الكفر فلا دليل عليه البتة، ومع هذا أكثر الناس كافرون.", "بيان غنى الله تعالى عن خلقه وافتقار الخلق إليه.", "بيان عدالة الله تعالى يوم القيامة وتقريرها.", "بيان إحاطة علم الله بالخلق وعلمه بأفعالهم وأحوالهم ظاهراً وباطناً."], "k": "«ولا يرضى لعباده الكفر وإن تشكروا يرضه لكم»… ربي غني عني ومع ذلك يحب لي الخير؛ فهل أشكره؟"}, {"lbl": "الآيتان ٨ – ٩", "q": "۞وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَا رَبَّهُۥ مُنِيبًا إِلَيۡهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعۡمَةٗ مِّنۡهُ نَسِيَ مَا كَانَ يَدۡعُوٓاْ إِلَيۡهِ مِن قَبۡلُ وَجَعَلَ لِلَّهِ أَندَادٗا لِّيُضِلَّ عَن سَبِيلِهِۦۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِيلًا إِنَّكَ مِنۡ أَصۡحَٰبِ ٱلنَّارِ ﴿٨﴾ أَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدٗا وَقَآئِمٗا يَحۡذَرُ ٱلۡأٓخِرَةَ وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ يَسۡتَوِي ٱلَّذِينَ يَعۡلَمُونَ وَٱلَّذِينَ لَا يَعۡلَمُونَۗ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿٩﴾", "w": [["وإذا مسّ الإنسان", "الإنسان المشرك."], ["ضرّ", "مرض أو خوف غرق ونحوه من كل مكروه."], ["دعا ربه منيباً إليه", "سأل ربه كشف ما أصابه راجعاً إليه معرضاً عمن سواه."], ["إذا خوّله نعمة منه", "أعطاه نعمة بأن كشف ما به من ضر."], ["نسي ما كان يدعو إليه من قبل", "ترك ما كان يتضرّع إليه من قبل وهو الله سبحانه."], ["وجعل لله أنداداً", "شركاء."], ["ليُضلّ عن سبيله", "ليُضلّ نفسه وغيره عن الإسلام."], ["قل تمتّع بكفرك قليلاً", "قل يا نبينا لهذا الكافر الضال المضل تهديداً."], ["إنك من أصحاب النار", "أهلها المتأهّلين لها بخبث نفوسهم وظلمة أرواحهم."], ["أمّن هو قانت آناء الليل", "مطيع لله ساعات الليل ساجداً وقائماً في صلاته."], ["إنما يتذكّر أولو الألباب", "يتعظ بما يسمع من الآيات أصحاب العقول النيّرة."]], "m": "ما زال السياق في تقرير التوحيد وإبطال التنديد، فأخبر عن حال المشرك: إذا مسّه ضرّ دعا ربه راجعاً إليه رافعاً يديه: يا رباه يا رباه، سائلاً كشف ما نزل به، ثم إذا فرّج الله كربه ونجّاه ترك دعاء الله وأقبل على عبادة غيره، وجعل لله شركاء ليُضلّ نفسه وغيره. فأمر رسوله أن يقول له: تمتّع بكفرك مدة بقية عمرك إنك من أصحاب النار؛ هدّده بعاقبة الشرك لعله يتوب ويرجع إلى الله رجوعاً حسناً. أمّن هو مطيع لله ولرسوله في أمرهما ونهيهما ساعات الليل، تراه ساجداً في صلاته أو قائماً يتلو آيات الله، يحذر عذاب الآخرة ويسأل الله أن يقيه منه، ويرجو رحمة ربه وهي الجنة، أهذا خير أم ذلك الكافر؟ والجواب معلوم للعقلاء. هل يستوي الذين يعلمون محابّ الله ومكارهه فيعملون بمحابّه تقرّباً إليه ويتركون مكارهه تحبّباً إليه، مع الذين لا يعلمون فهم يتخبّطون في الضلال؟ لا يستوون، وإنما يتذكّر بمثل هذا التوجيه أصحاب العقول السليمة الراجحة.", "h": ["تقرير التوحيد وإبطال الشرك والتنديد.", "الكشف عن داخلية الإنسان قبل أن يؤمن ويُسلم، وهو أنه إنسان متناقض لا خير فيه ولا رشد له، فلا يرشد ولا يكمل إلا بالإيمان والتوحيد.", "بشرى الضالين عن سبيل الله المضلّين عنه بالنار.", "مقارنة بين القانت المطيع والعاصي المضل المبين، وبين العالم والجاهل، وتقرير أفضلية المؤمن المطيع على الكافر العاصي، وأفضلية العالم بالله وبمحابّه ومكارهه على الجاهل بذلك.", "فضل العالم على الجاهل لعمله بعلمه، ولولا العمل بالعلم لاستويا في الخسّة والانحطاط."], "k": "«نسي ما كان يدعو إليه من قبل»… أدعو الله في الشدة بإلحاح؛ فهل أذكره بنفس الحرارة بعد الفرج؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 334;
insert into public.tdb_cards(topic, i, body) select 334, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ﴿١﴾ إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ فَٱعۡبُدِ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ ﴿٢﴾ أَلَا لِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ مَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلۡفَىٰٓ إِنَّ ٱللَّهَ يَحۡكُمُ بَيۡنَهُمۡ فِي مَا هُمۡ فِيهِ يَخۡتَلِفُونَۗ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ كَٰذِبٞ كَفَّارٞ ﴿٣﴾ لَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدٗا لَّٱصۡطَفَىٰ مِمَّا يَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ﴿٤﴾", "w": [["تنزيل الكتاب", "القرآن من الله."], ["العزيز الحكيم", "العزيز في ملكه وانتقامه، الحكيم في صنعه وتدبير خلقه."], ["مخلصاً له الدين", "مفرداً إياه بالعبادة فلا تشرك بعبادته أحداً."], ["له الدين الخالص", "له وحده خالص العبادة لا يشاركه في ذلك أحد سواه."], ["أولياء", "شركاء، وهي الأصنام."], ["ليقرّبونا إلى الله زلفى", "تقريباً وتشفع لنا عند الله."], ["من هو كاذب كفّار", "كاذب على الله، كفّار بعبادته غير الله."], ["سبحانه", "تنزيهاً له عن الولد والشريك."], ["هو الله الواحد القهار", "المعبود الحق الواحد الذي لا شريك له في ملكه وسلطانه."]], "m": "يخبر تعالى أن تنزيل القرآن كان منه سبحانه، العزيز في انتقامه من أعدائه، الحكيم في تدبير خلقه، ولم يكن عن غيره بحال. إنا أنزلنا إليك القرآن بالحق في كل ما جاء فيه من العقائد والعبادات والأحكام، فاعبد الله مخلصاً له الدين لا تعبد معه غيره، فإن العبادة لا تصلح لغيره أبداً. ألا لله الدين الخالص، والذين اتخذوا من دونه شركاء يعبدونهم ويقولون: ما نعبدهم إلا ليقرّبونا إلى الله ويشفعوا لنا في قضاء حوائجنا، هؤلاء يحكم الله بينهم وبين المؤمنين الموحّدين يوم القيامة، ويجزي بعدله كلاً بما يستحقه. إن الله لا يهدي من توغّلوا في الفساد فأصبح الكذب على الله وعلى عباده وصفاً لازماً لهم، وبالغوا في الكفر حتى صار وصفاً ثابتاً لهم؛ وهذه سنته في حرمان العبد من الهداية. لو أراد الله أن يتخذ ولداً كما زعم المشركون أن الملائكة بنات الله، وكما قال النصارى: المسيح ابن الله، وقال اليهود: عزير ابن الله، لاصطفى مما يخلق ما يشاء، ولا يتركهم ينسبون إليه الولد افتراءً، ولكنه منزّه عن صفات المحدَثين وافتقار المخلوقين، هو الله الواحد القهار لسائر خلقه، لا إله غيره ولا رب سواه.", "h": ["تقرير النبوة المحمدية.", "تقرير التوحيد.", "بطلان الشرك والتنديد بالمشركين.", "تقرير البعث والجزاء يوم القيامة."], "k": "«ألا لله الدين الخالص»… كم في عملي من شوائب تنتظر أن أخلّصها لله؟"}, {"lbl": "الآيات ٥ – ٧", "q": "خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ يُكَوِّرُ ٱلَّيۡلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِيزُ ٱلۡغَفَّـٰرُ ﴿٥﴾ خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖۚ يَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ ﴿٦﴾ إِن تَكۡفُرُواْ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنكُمۡۖ وَلَا يَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ وَإِن تَشۡكُرُواْ يَرۡضَهُ لَكُمۡۗ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٧﴾", "w": [["خلق السماوات والأرض بالحق", "من أجل أن يُذكر ويُشكر، لا من أجل اللهو والعبث."], ["يكوّر الليل على النهار", "يُدخل أحدهما في الآخر، فإذا جاء الليل ذهب النهار."], ["وسخّر الشمس والقمر", "ذلّلهما فلا يزالان يدوران في فلكيهما إلى نهاية الحياة، وبدورتهما تتم مصالح سكان الأرض."], ["خلقكم من نفس واحدة", "هي آدم ﵇."], ["ثم جعل منها زوجها", "هي حواء، خلقها الله من ضلع آدم الأيسر."], ["ثمانية أزواج", "من الإبل اثنين ومن البقر اثنين ومن الضأن اثنين ومن المعز اثنين."], ["خلقاً من بعد خلق", "أطواراً، طوراً بعد طور: نطفة فعلقة فمضغة."], ["في ظلمات ثلاث", "ظلمة البطن وظلمة الرحم وظلمة المشيمة."], ["ولا تزر وازرة وزر أخرى", "لا تحمل نفس ذات وزر وزر نفس أخرى."], ["بذات الصدور", "ما يخفيه المرء في صدره وما يُسرّه في ضميره."]], "m": "هذه الآيات في تقرير التوحيد بذكر البراهين التي لا تدع للشك مجالاً: خلق السماوات والأرض على غير مثال سابق، وخلقهما بالحق لغايات سامية لا للعبث، ومنها أن يُعبد فيهما فيُذكر ويُشكر. وبرهان ثانٍ: يكوّر الليل على النهار ويكوّر النهار على الليل، يغشى هذا هذا فيستره. وبرهان ثالث: سخّر الشمس والقمر كلٌّ يجري لأجل مسمى إلى قيام الساعة، وفي ذلك من المصالح ما لا يُقدَر قدره، منها معرفة عدد السنين والحساب. ألا هو العزيز في انتقامه من أعدائه، الغفّار لعباده التائبين. خلقكم من نفس واحدة هي آدم، فقد صحّ أنه لما خلقه مسح ظهره فأخرج منه ذريته وأشهدهم على أنفسهم، ولهذا جاء العطف بثمّ: ثم خلق منها زوجها حواء من ضلعه الأيسر. وبرهان آخر: أنزل لكم من الأنعام، الإبل والبقر والضأن والمعز، ذكراً وأنثى فهي ثمانية أزواج، وجائز أن يكون أصلها أُنزل من السماء كما أُنزل آدم وحواء، وجائز أن يكون أنزل الماء فنبت العشب وتكوّنت منه. وبرهان رابع: يخلقكم في بطون أمهاتكم نطفة ثم علقة ثم مضغة ثم عظاماً يكسوها لحماً، في ظلمات ثلاث: البطن والرحم والمشيمة. ذلكم الله ربكم خالقكم ومعبودكم، له الملك لا إله إلا هو، فكيف تُصرفون عن الحق إلى الباطل؟ إن تكفروا فإن الله غني عنكم لا يضرّه كفركم، إلا أنه لرحمته بعباده لا يرضى لهم الكفر لما يسبّبه لهم من شقاء، وإن تشكروا يرضه لكم فيثيبكم أحسن ثواب. ولا تحمل نفس ذنب نفس أخرى، وهذا مظهر من مظاهر عدله، ثم إلى ربكم مرجعكم بعد الموت فيخبركم بأعمالكم خفيّها وجليّها، إنه عليم بما في الصدور فضلاً عما كان ظاهراً. فهذا ربكم الحق فآمنوا به ووحّدوه وأطيعوه تنجوا وتسعدوا، ولا يهلك على الله إلا هالك.", "h": ["بيان آيات الله في الكون وإيرادها أدلة على التوحيد.", "بيان إفضال الله تعالى على العباد في خلقهم ورزقهم.", "بيان أن الكفر أعجب من الإيمان، إذ أدلة الإيمان لا تُعدّ كثرة وأما الكفر فلا دليل عليه البتة، ومع هذا أكثر الناس كافرون.", "بيان غنى الله تعالى عن خلقه وافتقار الخلق إليه.", "بيان عدالة الله تعالى يوم القيامة وتقريرها.", "بيان إحاطة علم الله بالخلق وعلمه بأفعالهم وأحوالهم ظاهراً وباطناً."], "k": "«ولا يرضى لعباده الكفر وإن تشكروا يرضه لكم»… ربي غني عني ومع ذلك يحب لي الخير؛ فهل أشكره؟"}, {"lbl": "الآيتان ٨ – ٩", "q": "۞وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَا رَبَّهُۥ مُنِيبًا إِلَيۡهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعۡمَةٗ مِّنۡهُ نَسِيَ مَا كَانَ يَدۡعُوٓاْ إِلَيۡهِ مِن قَبۡلُ وَجَعَلَ لِلَّهِ أَندَادٗا لِّيُضِلَّ عَن سَبِيلِهِۦۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِيلًا إِنَّكَ مِنۡ أَصۡحَٰبِ ٱلنَّارِ ﴿٨﴾ أَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدٗا وَقَآئِمٗا يَحۡذَرُ ٱلۡأٓخِرَةَ وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ يَسۡتَوِي ٱلَّذِينَ يَعۡلَمُونَ وَٱلَّذِينَ لَا يَعۡلَمُونَۗ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿٩﴾", "w": [["وإذا مسّ الإنسان", "الإنسان المشرك."], ["ضرّ", "مرض أو خوف غرق ونحوه من كل مكروه."], ["دعا ربه منيباً إليه", "سأل ربه كشف ما أصابه راجعاً إليه معرضاً عمن سواه."], ["إذا خوّله نعمة منه", "أعطاه نعمة بأن كشف ما به من ضر."], ["نسي ما كان يدعو إليه من قبل", "ترك ما كان يتضرّع إليه من قبل وهو الله سبحانه."], ["وجعل لله أنداداً", "شركاء."], ["ليُضلّ عن سبيله", "ليُضلّ نفسه وغيره عن الإسلام."], ["قل تمتّع بكفرك قليلاً", "قل يا نبينا لهذا الكافر الضال المضل تهديداً."], ["إنك من أصحاب النار", "أهلها المتأهّلين لها بخبث نفوسهم وظلمة أرواحهم."], ["أمّن هو قانت آناء الليل", "مطيع لله ساعات الليل ساجداً وقائماً في صلاته."], ["إنما يتذكّر أولو الألباب", "يتعظ بما يسمع من الآيات أصحاب العقول النيّرة."]], "m": "ما زال السياق في تقرير التوحيد وإبطال التنديد، فأخبر عن حال المشرك: إذا مسّه ضرّ دعا ربه راجعاً إليه رافعاً يديه: يا رباه يا رباه، سائلاً كشف ما نزل به، ثم إذا فرّج الله كربه ونجّاه ترك دعاء الله وأقبل على عبادة غيره، وجعل لله شركاء ليُضلّ نفسه وغيره. فأمر رسوله أن يقول له: تمتّع بكفرك مدة بقية عمرك إنك من أصحاب النار؛ هدّده بعاقبة الشرك لعله يتوب ويرجع إلى الله رجوعاً حسناً. أمّن هو مطيع لله ولرسوله في أمرهما ونهيهما ساعات الليل، تراه ساجداً في صلاته أو قائماً يتلو آيات الله، يحذر عذاب الآخرة ويسأل الله أن يقيه منه، ويرجو رحمة ربه وهي الجنة، أهذا خير أم ذلك الكافر؟ والجواب معلوم للعقلاء. هل يستوي الذين يعلمون محابّ الله ومكارهه فيعملون بمحابّه تقرّباً إليه ويتركون مكارهه تحبّباً إليه، مع الذين لا يعلمون فهم يتخبّطون في الضلال؟ لا يستوون، وإنما يتذكّر بمثل هذا التوجيه أصحاب العقول السليمة الراجحة.", "h": ["تقرير التوحيد وإبطال الشرك والتنديد.", "الكشف عن داخلية الإنسان قبل أن يؤمن ويُسلم، وهو أنه إنسان متناقض لا خير فيه ولا رشد له، فلا يرشد ولا يكمل إلا بالإيمان والتوحيد.", "بشرى الضالين عن سبيل الله المضلّين عنه بالنار.", "مقارنة بين القانت المطيع والعاصي المضل المبين، وبين العالم والجاهل، وتقرير أفضلية المؤمن المطيع على الكافر العاصي، وأفضلية العالم بالله وبمحابّه ومكارهه على الجاهل بذلك.", "فضل العالم على الجاهل لعمله بعلمه، ولولا العمل بالعلم لاستويا في الخسّة والانحطاط."], "k": "«نسي ما كان يدعو إليه من قبل»… أدعو الله في الشدة بإلحاح؛ فهل أذكره بنفس الحرارة بعد الفرج؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (335, 39, 10, 20, 'سورة الزمر ١٠ – ٢٠', 'الزمر: إنما يُوفّى الصابرون أجرهم بغير حساب', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 335) = $j$[{"lbl": "الآيات ١٠ – ١٦", "q": "قُلۡ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ رَبَّكُمۡۚ لِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۗ وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ إِنَّمَا يُوَفَّى ٱلصَّـٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ ﴿١٠﴾ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ ﴿١١﴾ وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ ﴿١٢﴾ قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ ﴿١٣﴾ قُلِ ٱللَّهَ أَعۡبُدُ مُخۡلِصٗا لَّهُۥ دِينِي ﴿١٤﴾ فَٱعۡبُدُواْ مَا شِئۡتُم مِّن دُونِهِۦۗ قُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَا ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ ﴿١٥﴾ لَهُم مِّن فَوۡقِهِمۡ ظُلَلٞ مِّنَ ٱلنَّارِ وَمِن تَحۡتِهِمۡ ظُلَلٞۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥۚ يَٰعِبَادِ فَٱتَّقُونِ ﴿١٦﴾", "w": [["اتقوا ربكم", "اجعلوا بينكم وبين عذابه وقاية بالإيمان والتقوى."], ["للذين أحسنوا", "أحسنوا العبادة."], ["حسنة", "الجنة."], ["وأرض الله واسعة", "فهاجروا فيها لتتمكنوا من عبادة الله إن مُنعتم منها في دياركم."], ["إني أُمرت", "أمرني ربي عز وجل."], ["مخلصاً له الدين", "مفرداً إياه بالعبادة."], ["أول المسلمين", "أول من يُسلم في هذه الأمة فينقاد لله بعبادته والإخلاص له فيها."], ["عذاب يوم عظيم", "عذاب يوم القيامة."], ["الله أعبد", "لا أعبد معه سواه."], ["فاعبدوا ما شئتم", "إن أبيتم عبادة الله وحده فاعبدوا ما شئتم من الأوثان فإنكم خاسرون."], ["خسروا أنفسهم", "فحرموها الجنة وخلّدوها في النار."], ["وأهليهم", "الحور العين اللائي كنّ لهم في الجنة لو آمنوا واتقوا."], ["ظُلَل من النار", "دخان ولهب وحرّ من فوقهم ومن تحتهم."], ["يا عباد فاتقون", "يا من أنا خالقهم ورازقهم ومالكهم، فاتقوني بالإيمان والتقوى."]], "m": "تضمّنت هذه الآيات توجيهات ربانية للمؤمنين والرسول ﷺ: يأمر رسوله أن يقول للمؤمنين: اتقوا ربكم بطاعته وطاعة رسوله، فإن للذين أحسنوا الطاعة الجنة، وإن لم يقدروا على الطاعة بين المشركين فليهاجروا، فأرض الله واسعة، ويشجّعهم على الهجرة فيقول: إنما يُوفّى الصابرون على الاغتراب والهجرة لأجل طاعة الله ورسوله أجرهم بلا كيل ولا وزن ولا عدّ، لأنه فوق ذلك. ويأمره أن يقول: إني أمرت أن أعبد الله باعتقاد وقول وفعل ما يأمرني به وترك ما ينهاني عنه مخلصاً له الدين فلا أشرك في عبادته أحداً، وأمرت أن أكون أول من يُسلم قلبه وجوارحه لله في هذه الأمة. وأن يقول للمشركين: إني أخاف إن عصيت ربي فرضيت بعبادة غيره عذاب يوم عظيم، الله أعبد مخلصاً له ديني، وأما أنتم فإن أبيتم التوحيد فاعبدوا ما شئتم من دونه. وإن الخاسرين بحق ليسوا الذين يخسرون دنياهم فيفقدون الدار والمال والأهل، بل الذين خسروا أنفسهم بتخليدهم في النار، وأهليهم من الحور العين المعدّة لهم لو آمنوا، ألا ذلك هو الخسران المبين: لهم من فوقهم طبقات من النار ومن تحتهم طبقات، كلها دخان ولهب وحرّ. ذلك يخوّف الله به عباده المؤمنين ليواصلوا طاعتهم فينجوا، يا عبادي فاتقون ولا تعصون.", "h": ["بيان عناية الله تعالى برسوله والمؤمنين إذ أرشدهم إلى ما يكمّلهم ويسعدهم.", "وجوب التقوى والصبر على الأذى في ذلك.", "تقرير التوحيد بأن يُعبد الله وحده.", "فضل الإسلام وشرف المسلمين.", "تقرير البعث والجزاء وبيان شيء من أهوال الآخرة وعذاب النار فيها.", "كل خسران في الدنيا إذا قيس بخسران الآخرة لا يُعدّ خسراناً أبداً."], "k": "«إن الخاسرين الذين خسروا أنفسهم»… أحزن على خسارة دنيا؛ فهل أحسب خسارة الآخرة بنفس الحرص؟"}, {"lbl": "الآيات ١٧ – ٢٠", "q": "وَٱلَّذِينَ ٱجۡتَنَبُواْ ٱلطَّـٰغُوتَ أَن يَعۡبُدُوهَا وَأَنَابُوٓاْ إِلَى ٱللَّهِ لَهُمُ ٱلۡبُشۡرَىٰۚ فَبَشِّرۡ عِبَادِ ﴿١٧﴾ ٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ أُوْلَـٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَـٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿١٨﴾ أَفَمَنۡ حَقَّ عَلَيۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِي ٱلنَّارِ ﴿١٩﴾ لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ غُرَفٞ مِّن فَوۡقِهَا غُرَفٞ مَّبۡنِيَّةٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَعۡدَ ٱللَّهِ لَا يُخۡلِفُ ٱللَّهُ ٱلۡمِيعَادَ ﴿٢٠﴾", "w": [["والذين اجتنبوا الطاغوت", "تركوا عبادة الأصنام وغيرها مما يُعبد من دون الله."], ["وأنابوا إلى الله", "بالإيمان به وعبادته وتوحيده فيها."], ["لهم البشرى", "بالجنة عند الموت وفي القبر وعند القيام من القبور."], ["فيتّبعون أحسنه", "أوفاه وأكمله وأقربه إلى مرضاة الله."], ["أولو الألباب", "العقول السليمة."], ["أفمن حقّ عليه كلمة العذاب", "وجب عليه العذاب بقول الله: لأملأنّ جهنم."], ["أفأنت تُنقذ من في النار", "تخلّصه منها وتخرجه من عذابها."], ["لكنِ الذين اتقوا ربهم", "خافوه فآمنوا به وأطاعوه موحّدين."], ["تجري من تحتها الأنهار", "من خلال قصورها وأشجارها."], ["وعد الله", "وعدهم الله وعداً فهو منجزه لهم."]], "m": "لما ذكر حال أهل النار من عبدة الأوثان ذكر حال الذين اجتنبوا الطواغيت، فجمع بين الترهيب والترغيب المطلوب لهداية البشر: والذين اجتنبوا الطاغوت أن يعبدوها، وهي الأوثان وكل ما زيّن الشيطان عبادته، وأنابوا إلى الله بعبادته وتوحيده، لهم البشرى في كتاب الله وعلى لسان رسوله، ويرونها عند نزول الموت وفي القبر وفي الحشر. فبشّر عباد الذين يستمعون القول فيتبعون أحسن ما يسمعون ويتركون ما دونه، فهؤلاء لهم همم عالية ونفوس توّاقة للخير، فاستوجبوا البشرى والثناء من رب العالمين: أولئك الذين هداهم الله وأولئك هم أولو الألباب، فحسبهم كمالاً أن أثنى الله عليهم. أفمن وجب له العذاب قضاءً وقدراً فأسرف في الكفر والإجرام كأبي جهل والعاص بن وائل فأحاطت به خطيئاته، أفأنت أيها الرسول تُنقذه من النار؟ لا، فهوّن على نفسك واتركهم لشأنهم. لكن الذين اتقوا فآمنوا وعملوا الصالحات لهم غرف في الجنة من فوقها غرف مبنية، تجري من تحت القصور والأشجار أنهار الماء واللبن والعسل والخمر، وعدهم الله بها وعداً حقاً، والله لا يخلف الميعاد.", "h": ["كرامة زيد بن عمرو بن نفيل وأبي ذر الغفاري وسلمان الفارسي، إذ هذه الآية تعنيهم؛ فقد رفضوا عبادة الطاغوت في الجاهلية قبل الإسلام ثم أنابوا إلى ربهم فصدقت الآية عليهم.", "فضيلة أهل التمييز والوعي والإدراك الذين يميّزون بين ما يسمعون فيتبعون الأحسن ويتركون ما دونه من الحسن والسيئ.", "إعلام من الله تعالى أن من وجبت له النار أزلاً لا تمكن هدايته مهما بذل الداعي في هدايته وإصلاحه ما بذل.", "بيان ما أعدّ الله تعالى لأهل الإيمان والتقوى من نعيم الجنة وكرامة الله لأهلها."], "k": "«الذين يستمعون القول فيتّبعون أحسنه»… أسمع كثيراً؛ فهل أختار الأحسن وأعمل به؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 335;
insert into public.tdb_cards(topic, i, body) select 335, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠ – ١٦", "q": "قُلۡ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ رَبَّكُمۡۚ لِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۗ وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ إِنَّمَا يُوَفَّى ٱلصَّـٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ ﴿١٠﴾ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ ﴿١١﴾ وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ ﴿١٢﴾ قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ ﴿١٣﴾ قُلِ ٱللَّهَ أَعۡبُدُ مُخۡلِصٗا لَّهُۥ دِينِي ﴿١٤﴾ فَٱعۡبُدُواْ مَا شِئۡتُم مِّن دُونِهِۦۗ قُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَا ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ ﴿١٥﴾ لَهُم مِّن فَوۡقِهِمۡ ظُلَلٞ مِّنَ ٱلنَّارِ وَمِن تَحۡتِهِمۡ ظُلَلٞۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥۚ يَٰعِبَادِ فَٱتَّقُونِ ﴿١٦﴾", "w": [["اتقوا ربكم", "اجعلوا بينكم وبين عذابه وقاية بالإيمان والتقوى."], ["للذين أحسنوا", "أحسنوا العبادة."], ["حسنة", "الجنة."], ["وأرض الله واسعة", "فهاجروا فيها لتتمكنوا من عبادة الله إن مُنعتم منها في دياركم."], ["إني أُمرت", "أمرني ربي عز وجل."], ["مخلصاً له الدين", "مفرداً إياه بالعبادة."], ["أول المسلمين", "أول من يُسلم في هذه الأمة فينقاد لله بعبادته والإخلاص له فيها."], ["عذاب يوم عظيم", "عذاب يوم القيامة."], ["الله أعبد", "لا أعبد معه سواه."], ["فاعبدوا ما شئتم", "إن أبيتم عبادة الله وحده فاعبدوا ما شئتم من الأوثان فإنكم خاسرون."], ["خسروا أنفسهم", "فحرموها الجنة وخلّدوها في النار."], ["وأهليهم", "الحور العين اللائي كنّ لهم في الجنة لو آمنوا واتقوا."], ["ظُلَل من النار", "دخان ولهب وحرّ من فوقهم ومن تحتهم."], ["يا عباد فاتقون", "يا من أنا خالقهم ورازقهم ومالكهم، فاتقوني بالإيمان والتقوى."]], "m": "تضمّنت هذه الآيات توجيهات ربانية للمؤمنين والرسول ﷺ: يأمر رسوله أن يقول للمؤمنين: اتقوا ربكم بطاعته وطاعة رسوله، فإن للذين أحسنوا الطاعة الجنة، وإن لم يقدروا على الطاعة بين المشركين فليهاجروا، فأرض الله واسعة، ويشجّعهم على الهجرة فيقول: إنما يُوفّى الصابرون على الاغتراب والهجرة لأجل طاعة الله ورسوله أجرهم بلا كيل ولا وزن ولا عدّ، لأنه فوق ذلك. ويأمره أن يقول: إني أمرت أن أعبد الله باعتقاد وقول وفعل ما يأمرني به وترك ما ينهاني عنه مخلصاً له الدين فلا أشرك في عبادته أحداً، وأمرت أن أكون أول من يُسلم قلبه وجوارحه لله في هذه الأمة. وأن يقول للمشركين: إني أخاف إن عصيت ربي فرضيت بعبادة غيره عذاب يوم عظيم، الله أعبد مخلصاً له ديني، وأما أنتم فإن أبيتم التوحيد فاعبدوا ما شئتم من دونه. وإن الخاسرين بحق ليسوا الذين يخسرون دنياهم فيفقدون الدار والمال والأهل، بل الذين خسروا أنفسهم بتخليدهم في النار، وأهليهم من الحور العين المعدّة لهم لو آمنوا، ألا ذلك هو الخسران المبين: لهم من فوقهم طبقات من النار ومن تحتهم طبقات، كلها دخان ولهب وحرّ. ذلك يخوّف الله به عباده المؤمنين ليواصلوا طاعتهم فينجوا، يا عبادي فاتقون ولا تعصون.", "h": ["بيان عناية الله تعالى برسوله والمؤمنين إذ أرشدهم إلى ما يكمّلهم ويسعدهم.", "وجوب التقوى والصبر على الأذى في ذلك.", "تقرير التوحيد بأن يُعبد الله وحده.", "فضل الإسلام وشرف المسلمين.", "تقرير البعث والجزاء وبيان شيء من أهوال الآخرة وعذاب النار فيها.", "كل خسران في الدنيا إذا قيس بخسران الآخرة لا يُعدّ خسراناً أبداً."], "k": "«إن الخاسرين الذين خسروا أنفسهم»… أحزن على خسارة دنيا؛ فهل أحسب خسارة الآخرة بنفس الحرص؟"}, {"lbl": "الآيات ١٧ – ٢٠", "q": "وَٱلَّذِينَ ٱجۡتَنَبُواْ ٱلطَّـٰغُوتَ أَن يَعۡبُدُوهَا وَأَنَابُوٓاْ إِلَى ٱللَّهِ لَهُمُ ٱلۡبُشۡرَىٰۚ فَبَشِّرۡ عِبَادِ ﴿١٧﴾ ٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ أُوْلَـٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَـٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿١٨﴾ أَفَمَنۡ حَقَّ عَلَيۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِي ٱلنَّارِ ﴿١٩﴾ لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ غُرَفٞ مِّن فَوۡقِهَا غُرَفٞ مَّبۡنِيَّةٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَعۡدَ ٱللَّهِ لَا يُخۡلِفُ ٱللَّهُ ٱلۡمِيعَادَ ﴿٢٠﴾", "w": [["والذين اجتنبوا الطاغوت", "تركوا عبادة الأصنام وغيرها مما يُعبد من دون الله."], ["وأنابوا إلى الله", "بالإيمان به وعبادته وتوحيده فيها."], ["لهم البشرى", "بالجنة عند الموت وفي القبر وعند القيام من القبور."], ["فيتّبعون أحسنه", "أوفاه وأكمله وأقربه إلى مرضاة الله."], ["أولو الألباب", "العقول السليمة."], ["أفمن حقّ عليه كلمة العذاب", "وجب عليه العذاب بقول الله: لأملأنّ جهنم."], ["أفأنت تُنقذ من في النار", "تخلّصه منها وتخرجه من عذابها."], ["لكنِ الذين اتقوا ربهم", "خافوه فآمنوا به وأطاعوه موحّدين."], ["تجري من تحتها الأنهار", "من خلال قصورها وأشجارها."], ["وعد الله", "وعدهم الله وعداً فهو منجزه لهم."]], "m": "لما ذكر حال أهل النار من عبدة الأوثان ذكر حال الذين اجتنبوا الطواغيت، فجمع بين الترهيب والترغيب المطلوب لهداية البشر: والذين اجتنبوا الطاغوت أن يعبدوها، وهي الأوثان وكل ما زيّن الشيطان عبادته، وأنابوا إلى الله بعبادته وتوحيده، لهم البشرى في كتاب الله وعلى لسان رسوله، ويرونها عند نزول الموت وفي القبر وفي الحشر. فبشّر عباد الذين يستمعون القول فيتبعون أحسن ما يسمعون ويتركون ما دونه، فهؤلاء لهم همم عالية ونفوس توّاقة للخير، فاستوجبوا البشرى والثناء من رب العالمين: أولئك الذين هداهم الله وأولئك هم أولو الألباب، فحسبهم كمالاً أن أثنى الله عليهم. أفمن وجب له العذاب قضاءً وقدراً فأسرف في الكفر والإجرام كأبي جهل والعاص بن وائل فأحاطت به خطيئاته، أفأنت أيها الرسول تُنقذه من النار؟ لا، فهوّن على نفسك واتركهم لشأنهم. لكن الذين اتقوا فآمنوا وعملوا الصالحات لهم غرف في الجنة من فوقها غرف مبنية، تجري من تحت القصور والأشجار أنهار الماء واللبن والعسل والخمر، وعدهم الله بها وعداً حقاً، والله لا يخلف الميعاد.", "h": ["كرامة زيد بن عمرو بن نفيل وأبي ذر الغفاري وسلمان الفارسي، إذ هذه الآية تعنيهم؛ فقد رفضوا عبادة الطاغوت في الجاهلية قبل الإسلام ثم أنابوا إلى ربهم فصدقت الآية عليهم.", "فضيلة أهل التمييز والوعي والإدراك الذين يميّزون بين ما يسمعون فيتبعون الأحسن ويتركون ما دونه من الحسن والسيئ.", "إعلام من الله تعالى أن من وجبت له النار أزلاً لا تمكن هدايته مهما بذل الداعي في هدايته وإصلاحه ما بذل.", "بيان ما أعدّ الله تعالى لأهل الإيمان والتقوى من نعيم الجنة وكرامة الله لأهلها."], "k": "«الذين يستمعون القول فيتّبعون أحسنه»… أسمع كثيراً؛ فهل أختار الأحسن وأعمل به؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (336, 39, 21, 31, 'سورة الزمر ٢١ – ٣١', 'الزمر: الله نزّل أحسن الحديث', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 336) = $j$[{"lbl": "الآيات ٢١ – ٢٣", "q": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَلَكَهُۥ يَنَٰبِيعَ فِي ٱلۡأَرۡضِ ثُمَّ يُخۡرِجُ بِهِۦ زَرۡعٗا مُّخۡتَلِفًا أَلۡوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرّٗا ثُمَّ يَجۡعَلُهُۥ حُطَٰمًاۚ إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ ﴿٢١﴾ أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ فَهُوَ عَلَىٰ نُورٖ مِّن رَّبِّهِۦۚ فَوَيۡلٞ لِّلۡقَٰسِيَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُوْلَـٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ ﴿٢٢﴾ ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبٗا مُّتَشَٰبِهٗا مَّثَانِيَ تَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ ﴿٢٣﴾", "w": [["فسلكه ينابيع في الأرض", "أدخله في الأرض فصار جارياً تحتها ينبع منها."], ["مختلفاً ألوانه", "ما بين أخضر وأبيض وأحمر وأصفر، وأنواعه من بُرّ وشعير."], ["ثم يهيج فتراه مصفرّاً", "ييبس فتراه بعد الخضرة مصفرّاً."], ["ثم يجعله حطاماً", "فتاتاً متكسّراً."], ["إن في ذلك لذكرى", "في المذكور من إنزال الماء إلى أن يكون حطاماً."], ["أفمن شرح الله صدره للإسلام", "فاهتدى به، كمن لم يشرح الله صدره فلم يهتد؟"], ["فهو على نور من ربه", "يعيش في حياته على نور من ربه وهو معرفة الله."], ["فويل للقاسية قلوبهم من ذكر الله", "ويل كلمة عذاب للقاسية قلوبهم عن قبول القرآن فلم تؤمن به ولم تعمل بما فيه."], ["أحسن الحديث كتاباً", "هو القرآن الكريم."], ["متشابهاً", "يشبه بعضه بعضاً في النظم والحسن وصحة المعاني."], ["مثاني", "يُثنّى فيه الوعد والوعيد والقصص والأحكام."], ["تقشعرّ منه جلود الذين يخشون", "ترتعد منه جلودهم عند ذكر وعيده."], ["ثم تلين جلودهم وقلوبهم إلى ذكر الله", "تطمئن وتلين عند ذكر وعده لأهل الإيمان والتقوى بالجنة."]], "m": "هذه الآية تقرّر التوحيد والبعث بذكر مظاهر القدرة والعلم الإلهيين: ألم تر أن الله أنزل من السماء المطر فأدخله في الأرض وأخرجه منها ينابيع بحفر وبدونه، ثم يُخرج به زرعاً من قمح وشعير وذرة مختلفاً ألوانه، ثم يجفّ حسب سنة الله فتراه مصفرّاً ثم يجعله فتاتاً كالتبن، كل هذا بقدرة الله وعلمه وتدبيره، ففيه ذكرى لأولي القلوب الحيّة تهديهم إلى الإيمان بالله ولقائه. أفمن وسّع الله صدره فقبل الإسلام ديناً فاعتقد عقائده وعمل بشرائعه فهو يعيش على نور من ربه، كمن طبع الله على قلبه وجعل صدره ضيقاً فعاش على ظلمة الكفر ودخن الذنوب؟ فويل لأصحاب القلوب القاسية من سماع القرآن، وهذه أسوأ حال العبد: أن يهلك بالدواء ويضل بالهدى؛ فالأصل في سماع القرآن أن يُليّن القلوب الصالحة للحياة، فإذا كانت ميتة زادها موتاً وقسوة، أولئك في ضلال مبين. ولما قال الصحابة يوماً: حدّثنا يا رسول الله، نزل: الله نزّل أحسن الحديث، القرآن، يشبه بعضه بعضاً في حسن اللفظ وصحة المعاني، يُثنّى فيه الوعد والوعيد والأمر والنهي والقصص، تقشعرّ منه جلود الذين يخشون ربهم عند آيات الوعيد، ثم تلين جلودهم إذا سمعوا آيات الوعد، وتطمئن قلوبهم إلى ذكر الله، كما قال: ألا بذكر الله تطمئن القلوب. ذلك هدى الله يهدي به من يشاء فيوفّقه للإيمان والعمل به، ومن يضلل الله لما سبق في علمه ولوجود مانع كالإصرار والعناد والتقليد فما له من هاد بعد الله أبداً.", "h": ["مظاهر العلم والقدرة الإلهية الموجبة للإيمان به وبرسوله ولقائه.", "بيان أن القلوب قلبان: قلب قابل للهداية، وآخر غير قابل لها.", "بيان أن القرآن أحسن ما يحدّث به المؤمن، إذ أخباره كلها صدق وأحكامه كلها عدل.", "فضيلة أهل الخشية من الله، إذ هم الذين ينفعلون لسماع القرآن فترتعد فرائصهم عند سماع وعيده، وتلين قلوبهم وجلودهم عند سماع وعده."], "k": "«تقشعرّ منه جلود الذين يخشون ربهم»… متى آخر مرة اقشعرّ جلدي وأنا أقرأ؟"}, {"lbl": "الآيات ٢٤ – ٢٦", "q": "أَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَقِيلَ لِلظَّـٰلِمِينَ ذُوقُواْ مَا كُنتُمۡ تَكۡسِبُونَ ﴿٢٤﴾ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ ﴿٢٥﴾ فَأَذَاقَهُمُ ٱللَّهُ ٱلۡخِزۡيَ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ﴿٢٦﴾", "w": [["أفمن يتّقي بوجهه سوء العذاب", "يتلقّى العذاب بوجهه لا شيء يقيه منه، كمن أمن؟"], ["سوء العذاب", "أقساه وأشدّه."], ["وقيل للظالمين", "المشركين في جهنم."], ["ذوقوا ما كنتم تكسبون", "جزاء كسبكم الشر والفساد."], ["كذّب الذين من قبلهم", "من قبل أهل مكة."], ["من حيث لا يشعرون", "من حيث لا يدرون أنه آتيهم منه، أو من حيث لا يخطر ببالهم."], ["عذاب الخزي", "المسخ والذل والإهانة."], ["ولعذاب الآخرة أكبر لو كانوا يعلمون", "لو كانوا يعلمون ذلك ما كذّبوا ولا كفروا."]], "m": "ما زال السياق في تقرير البعث والجزاء: أفمن يتلقّى سوء العذاب يوم القيامة بوجهه، إذ ليس له ما يتّقي به لأن يديه مغلولتان إلى عنقه، فيتلقّاه بوجهه وهو أشرف أعضائه، كمن أمن العذاب ودخل الجنة؟ لا يستويان. ويقول زبانية جهنم للمشركين وهم في النار توبيخاً: ذوقوا ما كنتم تكسبون من الشرك والمعاصي، هذا جزاؤه. كذّب قبل أهل مكة أمم كذّبوا رسلهم فأتاهم العذاب من حيث لا يشعرون، فأذاقهم الله الخزي في الحياة الدنيا كالذل والمسخ والقتل والأسر والسبي، ولعذاب الآخرة أكبر وهم صائرون إليه لا محالة، لو كانوا يعلمون عنه علماً يقينياً ما كذّبوا رسلهم ولا كفروا بربهم، فهلكوا بجهلهم.", "h": ["تقرير البعث والجزاء بذكر شيء من أحوال يوم القيامة.", "تهديد قريش على إصرارها على التكذيب للرسول وما جاءها به من الإسلام.", "العذاب على التكذيب والمعاصي منه الدنيوي ومنه الأخروي.", "لو علم الناس عذاب الآخرة علماً يقينياً ما كذّبوا ولا كفروا ولا ظلموا، فالجهل هو سبب الهلاك والشقاء دائماً."], "k": "«لو كانوا يعلمون»… لو استيقنتُ ما أعلمه عن الآخرة، كيف كانت ستتغير ليلتي؟"}, {"lbl": "الآيات ٢٧ – ٣١", "q": "وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ لَّعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٢٧﴾ قُرۡءَانًا عَرَبِيًّا غَيۡرَ ذِي عِوَجٖ لَّعَلَّهُمۡ يَتَّقُونَ ﴿٢٨﴾ ضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلٗا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلٗا سَلَمٗا لِّرَجُلٍ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ﴿٢٩﴾ إِنَّكَ مَيِّتٞ وَإِنَّهُم مَّيِّتُونَ ﴿٣٠﴾ ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عِندَ رَبِّكُمۡ تَخۡتَصِمُونَ ﴿٣١﴾", "w": [["ولقد ضربنا للناس في هذا القرآن من كل مثل", "جعلنا للعرب في هذا القرآن من كل مثل من الأمم السابقة."], ["لعلهم يتذكّرون", "يتعظون فينزجرون عن الشرك والتكذيب إلى الإيمان والتوحيد."], ["قرآناً عربياً غير ذي عوج", "لا لبس فيه ولا اختلاف، فلا عذر لهم في عدم فهمه."], ["شركاء متشاكسون", "متنازعون لسوء أخلاقهم."], ["ورجلاً سَلَماً لرجل", "خالصاً سالماً لرجل لا شركة فيه لأحد."], ["هل يستويان مثلاً", "لا، الأول في تعب وحيرة، والثاني في راحة وهدوء بال."], ["الحمد لله", "على ظهور الحق وبطلان الباطل."], ["إنك ميت", "مقضيّ عليك بالموت في وقته."], ["وإنهم ميتون", "محكوم عليهم به عند انقضاء آجالهم."], ["عند ربكم تختصمون", "تحتكمون إلى الله في ساحة فصل القضاء فيحكم بينكم فيما كنتم فيه تختلفون."]], "m": "يخبر تعالى بما منّ به على العرب لهدايتهم، إذ جعل لهم في القرآن من أمثال الأمم السابقة في إيمانها وتكذيبها، وصلاحها وفسادها، ونجاتها وخسرانها، كل ذلك بلسان عربي لا خفاء فيه ولا اختلاف، لعلهم يتعظون فيؤمنون وينجون. ثم ضرب مثلاً للمشرك الذي يعبد عدة آلهة والموحّد الذي لا يعبد إلا الله: فالمشرك مثله رجل يملكه عدد من الرجال ذوي الأخلاق الشرسة والطباع الجافة يتنازعونه، هذا يقول: تعال، والآخر: اجلس، والثالث: قم، فهو في حيرة لا راحة بدن ولا راحة نفس. والموحّد مثله رجل خالص لرجل واحد، آمره وناهيه واحد. هل يستويان؟ لا، إذ بينهما كما بين الحرية والعبودية وأعظم. الحمد لله على أنه رب واحد وإله واحد، بل أكثر المشركين لا يعلمون عدم تساوي الرجلين لجهلهم وفساد عقولهم. ولما استبطأ المشركون موت الرسول ﷺ نزل: إنك ميت وإنهم ميتون، أي لا شماتة في الموت، ستموت ويموتون، ثم إنكم يوم القيامة، مؤمنكم وكافركم، قويكم وضعيفكم، تقفون بين يدي الله فيحكم بينكم فيما كنتم فيه تختلفون من أمور الدين والدنيا.", "h": ["مشروعية ضرب الأمثال للمبالغة في الإفهام والهداية لمن يراد هدايته.", "بيان مثل المشرك والموحّد: فالمشرك في حيرة وتعب، والموحّد في راحة وهدوء بال.", "تقرير أن كل نفس ذائقة الموت.", "بيان أن خصومة ستكون يوم القيامة، ويقضي الله تعالى فيها بالحق لأنه هو الحق."], "k": "«ورجلاً سَلَماً لرجل»… حين يتنازعني رضا الناس ورضا الله، لمن أكون خالصاً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 336;
insert into public.tdb_cards(topic, i, body) select 336, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢١ – ٢٣", "q": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَلَكَهُۥ يَنَٰبِيعَ فِي ٱلۡأَرۡضِ ثُمَّ يُخۡرِجُ بِهِۦ زَرۡعٗا مُّخۡتَلِفًا أَلۡوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرّٗا ثُمَّ يَجۡعَلُهُۥ حُطَٰمًاۚ إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ ﴿٢١﴾ أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ فَهُوَ عَلَىٰ نُورٖ مِّن رَّبِّهِۦۚ فَوَيۡلٞ لِّلۡقَٰسِيَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُوْلَـٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ ﴿٢٢﴾ ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبٗا مُّتَشَٰبِهٗا مَّثَانِيَ تَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ ﴿٢٣﴾", "w": [["فسلكه ينابيع في الأرض", "أدخله في الأرض فصار جارياً تحتها ينبع منها."], ["مختلفاً ألوانه", "ما بين أخضر وأبيض وأحمر وأصفر، وأنواعه من بُرّ وشعير."], ["ثم يهيج فتراه مصفرّاً", "ييبس فتراه بعد الخضرة مصفرّاً."], ["ثم يجعله حطاماً", "فتاتاً متكسّراً."], ["إن في ذلك لذكرى", "في المذكور من إنزال الماء إلى أن يكون حطاماً."], ["أفمن شرح الله صدره للإسلام", "فاهتدى به، كمن لم يشرح الله صدره فلم يهتد؟"], ["فهو على نور من ربه", "يعيش في حياته على نور من ربه وهو معرفة الله."], ["فويل للقاسية قلوبهم من ذكر الله", "ويل كلمة عذاب للقاسية قلوبهم عن قبول القرآن فلم تؤمن به ولم تعمل بما فيه."], ["أحسن الحديث كتاباً", "هو القرآن الكريم."], ["متشابهاً", "يشبه بعضه بعضاً في النظم والحسن وصحة المعاني."], ["مثاني", "يُثنّى فيه الوعد والوعيد والقصص والأحكام."], ["تقشعرّ منه جلود الذين يخشون", "ترتعد منه جلودهم عند ذكر وعيده."], ["ثم تلين جلودهم وقلوبهم إلى ذكر الله", "تطمئن وتلين عند ذكر وعده لأهل الإيمان والتقوى بالجنة."]], "m": "هذه الآية تقرّر التوحيد والبعث بذكر مظاهر القدرة والعلم الإلهيين: ألم تر أن الله أنزل من السماء المطر فأدخله في الأرض وأخرجه منها ينابيع بحفر وبدونه، ثم يُخرج به زرعاً من قمح وشعير وذرة مختلفاً ألوانه، ثم يجفّ حسب سنة الله فتراه مصفرّاً ثم يجعله فتاتاً كالتبن، كل هذا بقدرة الله وعلمه وتدبيره، ففيه ذكرى لأولي القلوب الحيّة تهديهم إلى الإيمان بالله ولقائه. أفمن وسّع الله صدره فقبل الإسلام ديناً فاعتقد عقائده وعمل بشرائعه فهو يعيش على نور من ربه، كمن طبع الله على قلبه وجعل صدره ضيقاً فعاش على ظلمة الكفر ودخن الذنوب؟ فويل لأصحاب القلوب القاسية من سماع القرآن، وهذه أسوأ حال العبد: أن يهلك بالدواء ويضل بالهدى؛ فالأصل في سماع القرآن أن يُليّن القلوب الصالحة للحياة، فإذا كانت ميتة زادها موتاً وقسوة، أولئك في ضلال مبين. ولما قال الصحابة يوماً: حدّثنا يا رسول الله، نزل: الله نزّل أحسن الحديث، القرآن، يشبه بعضه بعضاً في حسن اللفظ وصحة المعاني، يُثنّى فيه الوعد والوعيد والأمر والنهي والقصص، تقشعرّ منه جلود الذين يخشون ربهم عند آيات الوعيد، ثم تلين جلودهم إذا سمعوا آيات الوعد، وتطمئن قلوبهم إلى ذكر الله، كما قال: ألا بذكر الله تطمئن القلوب. ذلك هدى الله يهدي به من يشاء فيوفّقه للإيمان والعمل به، ومن يضلل الله لما سبق في علمه ولوجود مانع كالإصرار والعناد والتقليد فما له من هاد بعد الله أبداً.", "h": ["مظاهر العلم والقدرة الإلهية الموجبة للإيمان به وبرسوله ولقائه.", "بيان أن القلوب قلبان: قلب قابل للهداية، وآخر غير قابل لها.", "بيان أن القرآن أحسن ما يحدّث به المؤمن، إذ أخباره كلها صدق وأحكامه كلها عدل.", "فضيلة أهل الخشية من الله، إذ هم الذين ينفعلون لسماع القرآن فترتعد فرائصهم عند سماع وعيده، وتلين قلوبهم وجلودهم عند سماع وعده."], "k": "«تقشعرّ منه جلود الذين يخشون ربهم»… متى آخر مرة اقشعرّ جلدي وأنا أقرأ؟"}, {"lbl": "الآيات ٢٤ – ٢٦", "q": "أَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَقِيلَ لِلظَّـٰلِمِينَ ذُوقُواْ مَا كُنتُمۡ تَكۡسِبُونَ ﴿٢٤﴾ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ ﴿٢٥﴾ فَأَذَاقَهُمُ ٱللَّهُ ٱلۡخِزۡيَ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ﴿٢٦﴾", "w": [["أفمن يتّقي بوجهه سوء العذاب", "يتلقّى العذاب بوجهه لا شيء يقيه منه، كمن أمن؟"], ["سوء العذاب", "أقساه وأشدّه."], ["وقيل للظالمين", "المشركين في جهنم."], ["ذوقوا ما كنتم تكسبون", "جزاء كسبكم الشر والفساد."], ["كذّب الذين من قبلهم", "من قبل أهل مكة."], ["من حيث لا يشعرون", "من حيث لا يدرون أنه آتيهم منه، أو من حيث لا يخطر ببالهم."], ["عذاب الخزي", "المسخ والذل والإهانة."], ["ولعذاب الآخرة أكبر لو كانوا يعلمون", "لو كانوا يعلمون ذلك ما كذّبوا ولا كفروا."]], "m": "ما زال السياق في تقرير البعث والجزاء: أفمن يتلقّى سوء العذاب يوم القيامة بوجهه، إذ ليس له ما يتّقي به لأن يديه مغلولتان إلى عنقه، فيتلقّاه بوجهه وهو أشرف أعضائه، كمن أمن العذاب ودخل الجنة؟ لا يستويان. ويقول زبانية جهنم للمشركين وهم في النار توبيخاً: ذوقوا ما كنتم تكسبون من الشرك والمعاصي، هذا جزاؤه. كذّب قبل أهل مكة أمم كذّبوا رسلهم فأتاهم العذاب من حيث لا يشعرون، فأذاقهم الله الخزي في الحياة الدنيا كالذل والمسخ والقتل والأسر والسبي، ولعذاب الآخرة أكبر وهم صائرون إليه لا محالة، لو كانوا يعلمون عنه علماً يقينياً ما كذّبوا رسلهم ولا كفروا بربهم، فهلكوا بجهلهم.", "h": ["تقرير البعث والجزاء بذكر شيء من أحوال يوم القيامة.", "تهديد قريش على إصرارها على التكذيب للرسول وما جاءها به من الإسلام.", "العذاب على التكذيب والمعاصي منه الدنيوي ومنه الأخروي.", "لو علم الناس عذاب الآخرة علماً يقينياً ما كذّبوا ولا كفروا ولا ظلموا، فالجهل هو سبب الهلاك والشقاء دائماً."], "k": "«لو كانوا يعلمون»… لو استيقنتُ ما أعلمه عن الآخرة، كيف كانت ستتغير ليلتي؟"}, {"lbl": "الآيات ٢٧ – ٣١", "q": "وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ لَّعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٢٧﴾ قُرۡءَانًا عَرَبِيًّا غَيۡرَ ذِي عِوَجٖ لَّعَلَّهُمۡ يَتَّقُونَ ﴿٢٨﴾ ضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلٗا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلٗا سَلَمٗا لِّرَجُلٍ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ﴿٢٩﴾ إِنَّكَ مَيِّتٞ وَإِنَّهُم مَّيِّتُونَ ﴿٣٠﴾ ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عِندَ رَبِّكُمۡ تَخۡتَصِمُونَ ﴿٣١﴾", "w": [["ولقد ضربنا للناس في هذا القرآن من كل مثل", "جعلنا للعرب في هذا القرآن من كل مثل من الأمم السابقة."], ["لعلهم يتذكّرون", "يتعظون فينزجرون عن الشرك والتكذيب إلى الإيمان والتوحيد."], ["قرآناً عربياً غير ذي عوج", "لا لبس فيه ولا اختلاف، فلا عذر لهم في عدم فهمه."], ["شركاء متشاكسون", "متنازعون لسوء أخلاقهم."], ["ورجلاً سَلَماً لرجل", "خالصاً سالماً لرجل لا شركة فيه لأحد."], ["هل يستويان مثلاً", "لا، الأول في تعب وحيرة، والثاني في راحة وهدوء بال."], ["الحمد لله", "على ظهور الحق وبطلان الباطل."], ["إنك ميت", "مقضيّ عليك بالموت في وقته."], ["وإنهم ميتون", "محكوم عليهم به عند انقضاء آجالهم."], ["عند ربكم تختصمون", "تحتكمون إلى الله في ساحة فصل القضاء فيحكم بينكم فيما كنتم فيه تختلفون."]], "m": "يخبر تعالى بما منّ به على العرب لهدايتهم، إذ جعل لهم في القرآن من أمثال الأمم السابقة في إيمانها وتكذيبها، وصلاحها وفسادها، ونجاتها وخسرانها، كل ذلك بلسان عربي لا خفاء فيه ولا اختلاف، لعلهم يتعظون فيؤمنون وينجون. ثم ضرب مثلاً للمشرك الذي يعبد عدة آلهة والموحّد الذي لا يعبد إلا الله: فالمشرك مثله رجل يملكه عدد من الرجال ذوي الأخلاق الشرسة والطباع الجافة يتنازعونه، هذا يقول: تعال، والآخر: اجلس، والثالث: قم، فهو في حيرة لا راحة بدن ولا راحة نفس. والموحّد مثله رجل خالص لرجل واحد، آمره وناهيه واحد. هل يستويان؟ لا، إذ بينهما كما بين الحرية والعبودية وأعظم. الحمد لله على أنه رب واحد وإله واحد، بل أكثر المشركين لا يعلمون عدم تساوي الرجلين لجهلهم وفساد عقولهم. ولما استبطأ المشركون موت الرسول ﷺ نزل: إنك ميت وإنهم ميتون، أي لا شماتة في الموت، ستموت ويموتون، ثم إنكم يوم القيامة، مؤمنكم وكافركم، قويكم وضعيفكم، تقفون بين يدي الله فيحكم بينكم فيما كنتم فيه تختلفون من أمور الدين والدنيا.", "h": ["مشروعية ضرب الأمثال للمبالغة في الإفهام والهداية لمن يراد هدايته.", "بيان مثل المشرك والموحّد: فالمشرك في حيرة وتعب، والموحّد في راحة وهدوء بال.", "تقرير أن كل نفس ذائقة الموت.", "بيان أن خصومة ستكون يوم القيامة، ويقضي الله تعالى فيها بالحق لأنه هو الحق."], "k": "«ورجلاً سَلَماً لرجل»… حين يتنازعني رضا الناس ورضا الله، لمن أكون خالصاً؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;